INSERT INTO public.asistente_manual_fichas (clave,tipo,pantalla_key,titulo,resumen,fuentes,revision) VALUES ('actas_despachos','pantalla','actas_despachos','Actas & Despachos','Actas de entrega y de recepción de los equipos alquilados.','["operaciones-app/src/zahory-mock/pages/flota/ActasDespachosPage.jsx#ActasDespachosPage"]'::jsonb,'b079728c36')
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('actas_despachos',1,'actas_despachos',NULL,NULL,'Emite un acta con Crear acta. Cargar checklist sugerido trae una lista base de puntos a revisar.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('actas_despachos',2,'actas_despachos',NULL,NULL,'Marca cada punto como Conforme u Observado y avanza con Avanzar.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('actas_despachos',3,'actas_despachos',NULL,NULL,'Guardar borrador conserva el acta para seguirla con Continuar acta. Confirmar acta la cierra.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('actas_despachos',4,'actas_despachos',NULL,NULL,'Anular acta deja sin efecto un acta emitida.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('actas_despachos',5,'actas_despachos',NULL,NULL,'Para qué sirve: el acta deja constancia, con checklist, fotos y firmas, del estado en que un equipo alquilado se entrega al cliente o se recibe de vuelta. Es la evidencia ante un reclamo por daños.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('actas_despachos',6,'actas_despachos',NULL,NULL,'El acta avanza por pasos. En el checklist cada punto se marca Conforme u Observado; si lo marcas Observado debes describir la observación. Puedes agregar puntos propios y fotos, y con Guardar borrador sigues después.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('actas_despachos',7,'actas_despachos',NULL,NULL,'No se puede despachar un equipo con certificaciones obligatorias vencidas: la pantalla pide renovarlas primero en Certificaciones del Activo.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('actas_despachos',8,'actas_despachos',NULL,NULL,'Confirmar acta la cierra con sus firmas; Volver a firmar permite rehacer una firma antes de confirmar. Anular acta deja sin efecto un acta ya emitida.');
INSERT INTO public.asistente_manual_fichas (clave,tipo,pantalla_key,titulo,resumen,fuentes,revision) VALUES ('actividades','pantalla','actividades','Actividades','Registro de las actividades comerciales: llamadas, visitas y reuniones.','["src/pages_core.jsx#Actividades"]'::jsonb,'a926023fb3')
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('actividades',1,'actividades',NULL,NULL,'Registra una actividad con Nueva actividad y Guardar actividad.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('actividades',2,'actividades',NULL,NULL,'Puedes verlas en Kanban o en Lista y acotar con Filtros.');
INSERT INTO public.asistente_manual_fichas (clave,tipo,pantalla_key,titulo,resumen,fuentes,revision) VALUES ('activos_fijos','pantalla','activos_fijos','Activos Fijos','Registro de los activos fijos de la empresa, sus documentos y su baja.','["src/pages_fin.jsx#ActivosFijos"]'::jsonb,'ba438c208f')
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('activos_fijos',1,'activos_fijos',NULL,NULL,'Registra un activo con Nuevo activo indicando nombre, fecha, valor y vida útil. Nuevo activo (Compras) lo registra además como compra en Compras / Gastos.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('activos_fijos',2,'activos_fijos',NULL,NULL,'Agregar doc adjunta documentos al activo y Editar cambia sus datos.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('activos_fijos',3,'activos_fijos',NULL,NULL,'Promover al Maestro lleva el activo al maestro de la empresa.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('activos_fijos',4,'activos_fijos',NULL,NULL,'Dar de baja retira el activo: debes indicar el motivo y confirmar con Confirmar baja.');
INSERT INTO public.asistente_manual_fichas (clave,tipo,pantalla_key,titulo,resumen,fuentes,revision) VALUES ('agenda_comercial','pantalla','agenda_comercial','Agenda Comercial','Calendario de reuniones y visitas del equipo comercial.','["src/pages_core.jsx#AgendaComercial"]'::jsonb,'37a93e9e93')
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('agenda_comercial',1,'agenda_comercial',NULL,NULL,'Agenda una reunión o visita con Nuevo evento y Crear evento.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('agenda_comercial',2,'agenda_comercial',NULL,NULL,'Cambia la vista entre Día, Semana, Mes y Lista; Hoy vuelve a la fecha actual.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('agenda_comercial',3,'agenda_comercial',NULL,NULL,'Cuando el evento ocurre usa Marcar realizado y crear actividad: queda como realizado y se registra la actividad comercial.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('agenda_comercial',4,'agenda_comercial',NULL,NULL,'Eliminar evento lo borra y no se puede deshacer; solo aparece si tu rol puede eliminar eventos.');
INSERT INTO public.asistente_manual_fichas (clave,tipo,pantalla_key,titulo,resumen,fuentes,revision) VALUES ('inventario_admin','pantalla','inventario','Almacenes','Existencias, entradas, ajustes, transferencias y conteos del almacén desde Administración.','["src/pages_extra.jsx#Inventario"]'::jsonb,'71bf749470')
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('inventario_admin',1,'inventario',NULL,NULL,'Registrar Entrada ingresa material al almacén; Primera Entrada registra el stock inicial de un material.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('inventario_admin',2,'inventario',NULL,NULL,'Ajustar corrige una diferencia de stock y Transferir mueve material entre almacenes.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('inventario_admin',3,'inventario',NULL,NULL,'Iniciar Conteo abre un conteo físico: Escanear lee los códigos, Guardar avance permite continuar después y Cerrar Conteo genera los ajustes. Un código que no pertenece al conteo se rechaza.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('inventario_admin',4,'inventario',NULL,NULL,'Generar SOLPE crea la solicitud de compra y la envía a Compras.');
INSERT INTO public.asistente_manual_fichas (clave,tipo,pantalla_key,titulo,resumen,fuentes,revision) VALUES ('api_keys','pantalla','api_keys','API Keys','Llaves de acceso para integrar otros sistemas con el ERP.','["src/pages_api_keys.jsx#ApiKeys"]'::jsonb,'e7d844db55')
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('api_keys',1,'api_keys',NULL,NULL,'Crea una llave con Nuevo API Key y Crear API Key.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('api_keys',2,'api_keys',NULL,NULL,'La llave se muestra una sola vez: cópiala con Copiar y confirma con Entendido, ya lo guardé.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('api_keys',3,'api_keys',NULL,NULL,'Editar permisos cambia lo que la llave puede hacer.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('api_keys',4,'api_keys',NULL,NULL,'Revocar key la desactiva de forma irreversible.');
INSERT INTO public.asistente_manual_fichas (clave,tipo,pantalla_key,titulo,resumen,fuentes,revision) VALUES ('backlog','pantalla','backlog','Backlog','Requerimientos pendientes que aún no son órdenes de trabajo.','["src/pages_ops.jsx#Backlog"]'::jsonb,'95cd76d187')
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('backlog',1,'backlog',NULL,NULL,'Registra un pendiente con Nuevo requerimiento y Agregar requerimiento.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('backlog',2,'backlog',NULL,NULL,'Puedes verlos en Kanban o en Lista y acotar con Filtros.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('backlog',3,'backlog',NULL,NULL,'Convertir a OT crea la orden de trabajo a partir del requerimiento.');
INSERT INTO public.asistente_manual_fichas (clave,tipo,pantalla_key,titulo,resumen,fuentes,revision) VALUES ('bandeja_ots','pantalla','ot','Bandeja de OTs','Lista todas las órdenes de trabajo con sus indicadores, filtros y búsqueda, y permite iniciar una OT programada.','["operaciones-app/src/zahory-mock/pages/pages2_v2.jsx#OTsListadoPage"]'::jsonb,'b22cbde9d1')
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('bandeja_ots',1,'ot',NULL,NULL,'Los indicadores de arriba (abiertas, programadas, en ejecución, sin técnico, por valorizar, con sobrecosto) filtran la lista al tocarlos.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('bandeja_ots',2,'ot',NULL,NULL,'Busca por número, cliente o servicio y filtra por estado o técnico. Solo retrabajos muestra las OT de retrabajo propio. Limpiar quita todos los filtros.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('bandeja_ots',3,'ot',NULL,NULL,'Para iniciar una OT programada usa Iniciar en su fila: la OT debe tener técnico responsable y centro de costo, y necesitas una sociedad operativa seleccionada (la vista consolidada es solo de lectura).');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('bandeja_ots',4,'ot',NULL,NULL,'Nueva OT abre el asistente de creación.');
INSERT INTO public.asistente_manual_fichas (clave,tipo,pantalla_key,titulo,resumen,fuentes,revision) VALUES ('sourcing_bandeja','pantalla','ordenes_compra','Bandeja de Sourcing','Reparte los materiales de las SOLPE aprobadas entre proveedores, línea por línea, y genera una orden de compra por proveedor.','["src/pages_ops.jsx#BandejaSourcing"]'::jsonb,'59f4c3339c')
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('sourcing_bandeja',1,'ordenes_compra',NULL,NULL,'Para qué sirve: aquí llegan las líneas de las SOLPE aprobadas que aún no tienen orden de compra. Permite comprar una misma SOLPE a varios proveedores, o juntar líneas de varias SOLPE en una sola orden. Está en Compras › Bandeja de Sourcing y también se abre con Generar OC desde la SOLPE.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('sourcing_bandeja',2,'ordenes_compra',NULL,NULL,'Filtra por Familia, SOLPE de origen, Estado de campo o Comprador de campo, y usa Actualizar para recargar la bandeja.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('sourcing_bandeja',3,'ordenes_compra',NULL,NULL,'Asigna un proveedor a cada línea. Los marcados como «sugerido» son los habilitados para la familia de ese material; con + Otro proveedor buscas cualquier otro. Si eliges uno que no está habilitado para esa familia, la pantalla pregunta si es Solo esta compra o si quieres Habilitar para esta familia en adelante.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('sourcing_bandeja',4,'ordenes_compra',NULL,NULL,'Las líneas asignadas se agrupan en una columna por proveedor con su total. Generar OC crea la orden de compra de ese proveedor con sus líneas; repítelo por cada proveedor. Quitar proveedor devuelve la línea a la bandeja.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('sourcing_bandeja',5,'ordenes_compra',NULL,NULL,'Una línea «en campo» la tomó un comprador de campo para comprarla en persona: mientras tanto no se le puede asignar proveedor. Quitar al comprador la libera, previa confirmación, porque esa persona podría estar comprándola en ese momento.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('sourcing_bandeja',6,'ordenes_compra',NULL,NULL,'Si un proveedor no entregará parte de una orden, Liberar pendiente en la orden de compra devuelve ese saldo a esta bandeja para comprarlo a otro proveedor.');
INSERT INTO public.asistente_manual_fichas (clave,tipo,pantalla_key,titulo,resumen,fuentes,revision) VALUES ('bi_cs','pantalla','bi_cs','BI Customer Success','Indicadores de retención, salud y crecimiento de los clientes.','["src/pages_cs.jsx#BICustomerSuccess"]'::jsonb,'41eae9e552')
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('bi_cs',1,'bi_cs',NULL,NULL,'Es un tablero de consulta: clientes saludables, clientes en riesgo, health score promedio y NPS promedio.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('bi_cs',2,'bi_cs',NULL,NULL,'También muestra los onboardings en curso y las renovaciones próximas.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('bi_cs',3,'bi_cs',NULL,NULL,'Exportar descarga la información.');
INSERT INTO public.asistente_manual_fichas (clave,tipo,pantalla_key,titulo,resumen,fuentes,revision) VALUES ('caja','pantalla','caja','Caja Chica','Administra fondos de caja chica, sus egresos, aportes, rendiciones, arqueos y el cierre del fondo con saldo cero; permite editar y anular egresos y anular aportes desde el historial del fondo.','["src/pages_fin.jsx#CajaChica","src/components/NuevoEgreso.jsx#NuevoEgreso","src/components/CerrarFondoModal.jsx#CerrarFondoModal","src/services/cajaChicaService.js"]'::jsonb,'99d34ba223 2c804b78dc e7344f6212 5c04bfa6a6')
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('caja',1,'caja','caja','crear','Usa Nuevo fondo para crear un fondo con su responsable, importe, moneda y origen del dinero (cuenta bancaria o aporte directo). Mientras el fondo no tenga movimientos se puede modificar.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('caja',2,'caja',NULL,NULL,'Usa Nuevo egreso para registrar un gasto del fondo. El asistente tiene tres pasos: elige el tipo de gasto (puedes buscar por tipo o por categoría del Estado de Resultados), completa los datos del comprobante y del fondo, y revisa antes de confirmar. Lo puede registrar el responsable del fondo o quien tenga permiso de crear en Caja Chica.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('caja',3,'caja',NULL,NULL,'En el paso de datos del egreso la categoría del Estado de Resultados es obligatoria y editable; la IA puede sugerirla a partir del tipo de gasto y la descripción. Adjunta el comprobante y vincula la OT si corresponde.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('caja',4,'caja',NULL,NULL,'Usa Agregar aporte para reforzar el fondo con dinero de una cuenta bancaria o con un aporte directo.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('caja',5,'caja',NULL,NULL,'Usa Solicitar rendición para presentar los egresos del periodo; la solicitud queda disponible para revisión.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('caja',6,'caja','caja','aprobar','Revisa la rendición y usa Aprobar o Rechazar para continuar con la reposición del fondo.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('caja',7,'caja',NULL,NULL,'Usa Arqueo y luego Registrar arqueo con el efectivo contado; revisa las diferencias que muestra la pantalla.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('caja',8,'caja','caja','editar','Usa Cerrar para cerrar el fondo. Ningún fondo puede cerrar con saldo a favor: transfiere el saldo a otra caja abierta de la misma moneda y sociedad, o devuélvelo a una cuenta bancaria activa.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('caja',9,'caja',NULL,NULL,'Para corregir un egreso abre el fondo y, en Historial > Egresos, usa el botón Editar que aparece bajo el estado de la fila; se abre una ventana donde puedes cambiar concepto, categoría del Estado de Resultados, centro de costo, número de comprobante y fecha. El monto no se edita; si está mal, anula el egreso y regístralo de nuevo. Lo puede hacer el responsable del fondo o quien tenga permiso de editar en Caja Chica, solo si el egreso está registrado y no cae en una rendición solicitada, aprobada o repuesta.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('caja',10,'caja',NULL,NULL,'Para anular un egreso o un aporte usa el botón Anular que aparece bajo el estado de la fila en Historial e indica el motivo en la ventana que se abre. Un egreso anulado devuelve su monto al saldo y deja de contar en el Estado de Resultados. Un aporte solo lo anula quien tenga permiso de editar o anular en Caja Chica y siempre que el saldo del fondo no quede negativo; si vino de una cuenta bancaria, Tesorería registra el ingreso de reversión. Los anulados quedan visibles con su motivo. Cuando una fila no tiene botones, debajo de su estado se indica por qué: egreso incluido en una rendición (con su periodo), reposición que viene de una rendición aprobada o movimiento ya anulado.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('caja',11,'caja',NULL,NULL,'Para corregir los datos de un fondo usa Editar fondo y Guardar cambios. Eliminar fondo lo borra con confirmación y no se puede deshacer; un fondo que ya tiene movimientos no se puede eliminar. En un egreso, Subir adjunto carga el comprobante y Descargar lo baja.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('caja',12,'caja',NULL,NULL,'Al abrir un fondo, la tarjeta Asignado muestra el total que entró al fondo y, debajo, su detalle: apertura, aportes vigentes, transferencias recibidas de otras cajas y reposiciones. Los aportes anulados no suman. Disponible es ese total menos los egresos y las transferencias enviadas. En Historial, las transferencias entre cajas aparecen en Ingresos (recibidas) o en Egresos (enviadas) y no se editan.');
INSERT INTO public.asistente_manual_fichas (clave,tipo,pantalla_key,titulo,resumen,fuentes,revision) VALUES ('servicios','pantalla','servicios','Catalogo Servicios','Catálogo de los servicios que la empresa vende y cotiza.','["src/pages_admin.jsx#Servicios"]'::jsonb,'fb5e7f9dc7')
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('servicios',1,'servicios',NULL,NULL,'Crea un servicio con Nuevo servicio. Si la familia no existe, Crear y seleccionar la crea en el momento.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('servicios',2,'servicios',NULL,NULL,'Marca Recurrente mensual en los servicios que se cobran todos los meses.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('servicios',3,'servicios',NULL,NULL,'Para cargar muchos servicios descarga la Plantilla y usa Importar Excel; solo se importan las filas válidas.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('servicios',4,'servicios',NULL,NULL,'Eliminar borra un servicio y pide confirmación.');
INSERT INTO public.asistente_manual_fichas (clave,tipo,pantalla_key,titulo,resumen,fuentes,revision) VALUES ('catalogo_venta','pantalla','inventario','Catálogo de venta','Productos del almacén que se ofrecen a la venta.','["operaciones-app/src/zahory-mock/pages/wms/CatalogoVentaPage.jsx#CatalogoVentaPage"]'::jsonb,'7819c0b8aa')
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('catalogo_venta',1,'inventario',NULL,NULL,'Agregar producto suma un material del almacén al catálogo con Agregar al catálogo.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('catalogo_venta',2,'inventario',NULL,NULL,'Un producto que ya está en el catálogo se puede editar con Guardar cambios.');
INSERT INTO public.asistente_manual_fichas (clave,tipo,pantalla_key,titulo,resumen,fuentes,revision) VALUES ('certificaciones_activo','pantalla','certificaciones_activo','Certificaciones del Activo','Certificaciones de los equipos y su renovación.','["operaciones-app/src/zahory-mock/pages/flota/CertificacionesActivoPage.jsx#CertificacionesActivoPage"]'::jsonb,'e36b54098c')
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('certificaciones_activo',1,'certificaciones_activo',NULL,NULL,'Registrar certificación anota una certificación de un equipo.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('certificaciones_activo',2,'certificaciones_activo',NULL,NULL,'Renovar registra su renovación y Anular la deja sin efecto.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('certificaciones_activo',3,'certificaciones_activo',NULL,NULL,'Catálogo de tipos define los tipos de certificación: Nuevo tipo crea uno y Cargar tipos sugeridos trae una lista base.');
INSERT INTO public.asistente_manual_fichas (clave,tipo,pantalla_key,titulo,resumen,fuentes,revision) VALUES ('cierre','pantalla','cierre','Cierre y Calidad','Consulta de las OT cerradas, la conformidad del cliente y su estado de valorización.','["src/pages_ops.jsx#Cierre"]'::jsonb,'db8d14d20f')
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('cierre',1,'cierre',NULL,NULL,'La lista muestra las OT cerradas con su cierre técnico, su acta de conformidad y su estado de valorización.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('cierre',2,'cierre',NULL,NULL,'Filtra por OS, cliente, responsable y fecha de cierre; Limpiar quita los filtros.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('cierre',3,'cierre',NULL,NULL,'Detalle abre el cierre de una OT y Valorizar lleva a valorizar una OT lista para ello.');
INSERT INTO public.asistente_manual_fichas (clave,tipo,pantalla_key,titulo,resumen,fuentes,revision) VALUES ('cierre_conformidad','pantalla','ot','Cierre & Conformidad','Cierre de las órdenes de trabajo con el acta de conformidad firmada por el técnico y el cliente.','["operaciones-app/src/zahory-mock/pages/CierreConformidadPage.jsx#CierreConformidadPage"]'::jsonb,'b188e26ea6')
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('cierre_conformidad',1,'ot',NULL,NULL,'La lista muestra las OT por cerrar y si están listas para acta; busca por OT, servicio o cliente.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('cierre_conformidad',2,'ot',NULL,NULL,'Una OT solo admite acta si tiene técnico responsable, al menos un parte aprobado y ningún parte pendiente de aprobar.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('cierre_conformidad',3,'ot',NULL,NULL,'El acta recorre seis pasos: Resumen, Fotos, Conformidad, Firma técnico, Firma cliente y Revisión. En el resumen la descripción del trabajo realizado es obligatoria.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('cierre_conformidad',4,'ot',NULL,NULL,'En Conformidad eliges el resultado: conforme, con observaciones o pendiente de firma. Si queda pendiente debes indicar por qué el cliente no firma y un correo para enviarle el enlace.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('cierre_conformidad',5,'ot',NULL,NULL,'Para la firma del cliente se piden su nombre completo, su documento y un correo para recibir el acta.');
INSERT INTO public.asistente_manual_fichas (clave,tipo,pantalla_key,titulo,resumen,fuentes,revision) VALUES ('comisiones','pantalla','comisiones','Comisiones','Comisiones de los vendedores: aprobación, recibo por honorarios y cuenta por pagar.','["src/pages_admin.jsx#Comisiones"]'::jsonb,'f28b0f4d0f')
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('comisiones',1,'comisiones',NULL,NULL,'La pestaña Comisiones lista las comisiones; Recalcular cobradas recupera las de ventas ya cobradas que aún no estaban registradas.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('comisiones',2,'comisiones',NULL,NULL,'Revisar abre una comisión: Aprobar la aprueba y Rechazar exige escribir el motivo.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('comisiones',3,'comisiones',NULL,NULL,'Corregir monto cobrado y Corregir bonificación ajustan una comisión; Guardar corrección conserva el cambio.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('comisiones',4,'comisiones',NULL,NULL,'Generar crea el recibo de la comisión. Para confirmarlo debes ingresar el número de RHE y adjuntar el documento; Confirmar y generar CxP crea la cuenta por pagar.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('comisiones',5,'comisiones',NULL,NULL,'Acuerdos pendientes muestra los acuerdos de comisión por aprobar; solo aparece si tu rol puede aprobarlos.');
INSERT INTO public.asistente_manual_fichas (clave,tipo,pantalla_key,titulo,resumen,fuentes,revision) VALUES ('como_usar_aria','proceso',NULL,'Cómo usar Aria','Cómo preguntarle a Aria escribiendo o dictando, cómo escuchar sus respuestas, cuántas consultas puedes hacer al día y cómo ver o borrar lo que recuerda de ti.','["src/components/AsistenteErpPanel.jsx#AsistenteErpPanelBase","src/components/AriaMicrofono.jsx#AriaMicrofono","src/lib/ariaHabla.js","src/components/AriaConversaciones.jsx#AriaConversaciones","src/components/AriaRecuerdos.jsx#AriaRecuerdos"]'::jsonb,'9d11a7c3fd c65836e99c c4d45aa981 3ed41385e9 cd021d0a54')
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('como_usar_aria',1,'ninguna',NULL,NULL,'Abre Aria con el robot de la esquina inferior derecha, disponible en las pantallas de Administración y de Operaciones, o escribe en el cuadro Pregúntale a Aria del Inicio.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('como_usar_aria',2,'ninguna',NULL,NULL,'Escribe tu pregunta y pulsa Enviar. Aria responde solo con la información que tus permisos te dejan ver y te indica qué módulos revisó.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('como_usar_aria',3,'ninguna',NULL,NULL,'Para dictar, toca el micrófono, habla y vuelve a tocarlo al terminar; puedes hablar hasta un minuto. La primera vez el navegador te pedirá permiso para usar el micrófono.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('como_usar_aria',4,'ninguna',NULL,NULL,'Lo que dictaste aparece escrito en el cuadro para que lo revises o corrijas antes de enviarlo; nada se envía solo. Cuando Aria te pide elegir, por ejemplo el fondo, la categoría o el centro de costo de un gasto, toca uno de los botones que muestra debajo de su mensaje.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('como_usar_aria',5,'ninguna',NULL,NULL,'Cuando preguntas por voz, Aria lee su respuesta en voz alta. Toca Detener voz para callarla.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('como_usar_aria',6,'ninguna',NULL,NULL,'Puedes hacer 30 preguntas y 60 dictados al día; los contadores se renuevan a medianoche, hora de Lima.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('como_usar_aria',7,'ninguna',NULL,NULL,'Aria puede preparar tres registros: un gasto de caja chica, un lead y una cuenta (prospecto, cliente o partner). Dile los datos que tengas; ella pide lo que falte, avisa si parece duplicado y te muestra una tarjeta. Solo se guarda cuando tú pulsas Confirmar en esa tarjeta, y necesitas el permiso de crear en esa pantalla. Lo demás (editar, borrar, cotizaciones, órdenes) se hace en su pantalla.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('como_usar_aria',8,'ninguna',NULL,NULL,'Aria recuerda lo que vienen conversando. Si vuelves a abrirla dentro de las 24 horas, retoma tu última conversación; con el botón del reloj ves tus conversaciones anteriores, puedes buscarlas por una palabra y abrir cualquiera, y con el botón + empiezas una nueva. Se guardan 180 días y solo tú las ves. También puedes preguntarle qué revisaron antes, por ejemplo la semana pasada.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('como_usar_aria',9,'ninguna',NULL,NULL,'Aria también recuerda cómo trabajas de una conversación a otra. Dile recuerda que… para que guarde algo, por ejemplo con qué fondo o centro de costo trabajas; además aprende sola y te avisa en el chat con Aria recordó. Cada aviso trae Deshacer. Para ver, buscar o borrar tus recuerdos, o pausar la memoria, abre el botón del reloj y entra a Lo que Aria recuerda de ti. Solo tú ves tus recuerdos, y Aria no guarda montos ni saldos: esos siempre los consulta en el ERP.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('como_usar_aria',10,'ninguna',NULL,NULL,'Cuando Aria te explica cómo hacer algo, te dice la ruta exacta de la pantalla (aplicación, módulo y pantalla) y debajo de su respuesta muestra el botón Ir a con el nombre de esa pantalla: tócalo y te lleva directo, también si la pantalla está en la otra aplicación.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('como_usar_aria',11,'ninguna',NULL,NULL,'Los administradores de la empresa ven arriba del chat dos pestañas: Aria y Aria experta. Aria experta, en color violeta, responde a fondo: explica el porqué, el recorrido entre pantallas, los errores frecuentes y qué pasa después, y sirve también para pedir análisis. Cada pestaña guarda sus propias conversaciones. La empresa tiene 150 consultas expertas al mes, compartidas entre sus administradores; el pie del chat indica cuántas quedan y se renuevan el día 1. Desde el chat normal, Ampliar en Aria experta abre el chat experto con esa misma pregunta. El chat normal sigue respondiendo todas tus preguntas sin gastar esa cuota.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('como_usar_aria',12,'ninguna',NULL,NULL,'Qué puedes preguntarle con datos reales de tu empresa, según tus permisos: ventas y facturación, quiénes son tus mejores clientes y cuáles dejaron de comprar; cobros y pagos pendientes y por vencer; bancos y caja chica; compras, órdenes y gastos; stock y kárdex; órdenes de trabajo atrasadas, sin parte o con sobrecosto y por qué una OT no avanza; la utilidad del mes con el mismo Estado de Resultados de Finanzas; cómo va el presupuesto del mes y qué partidas se excedieron; márgenes y rentabilidad del taller y la flota; personal, asistencia, planilla y comisiones; préstamos de la empresa; viajes de transporte; y qué contratos de alquiler, documentos de equipos o contratos del personal están por vencer.');
INSERT INTO public.asistente_manual_fichas (clave,tipo,pantalla_key,titulo,resumen,fuentes,revision) VALUES ('compras_gastos','pantalla','compras_gastos','Compras / Gastos','Consulta y registra compras y gastos con su comprobante, revisa los gastos que llegan desde campo y edita los que no dependen de otro módulo.','["src/pages_ops.jsx#ComprasGastos","src/components/NuevoEgreso.jsx#NuevoEgreso"]'::jsonb,'74938db849 2c804b78dc')
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('compras_gastos',1,'compras_gastos',NULL,NULL,'Revisa los gastos y compras registrados con las pestañas Todos, Campo, Backoffice y Pendientes revisión. Usa la búsqueda y los filtros para localizar un documento o proveedor.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('compras_gastos',2,'compras_gastos',NULL,NULL,'Usa Nuevo egreso para registrar una compra o gasto con el asistente de tres pasos: tipo de gasto, datos (fecha, monto, comprobante, proveedor, centro de costo, categoría del Estado de Resultados y método de pago) y revisión. Si el pago es por transferencia indica la cuenta bancaria; puedes vincular la orden de compra de origen y la OT.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('compras_gastos',3,'compras_gastos',NULL,NULL,'Los gastos registrados desde campo llegan como pendientes de revisión. Ábrelos, verifica el comprobante y usa Confirmar — marcar revisado.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('compras_gastos',4,'compras_gastos','caja','editar','Para editar un gasto ábrelo y usa Editar; la edición exige el permiso de edición de Caja. No se puede editar aquí si tiene una CxP generada, si viene de Personal/Nómina, si está registrado en Caja Chica o si se capitalizó como activo fijo; la pantalla indica dónde editarlo.');
INSERT INTO public.asistente_manual_fichas (clave,tipo,pantalla_key,titulo,resumen,fuentes,revision) VALUES ('concepto_acceso_usuario','proceso',NULL,'Tu usuario, tu contraseña, tu rol y la sociedad activa','Cómo entrar, cambiar o recuperar la contraseña, por qué ves unas pantallas y otras no, y cómo cambiar de sociedad.','["src/AuthGate.jsx","src/shell.jsx#SociedadSelector"]'::jsonb,'dd5fb2e78e cb9cdeb2fa')
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('concepto_acceso_usuario',1,'ninguna',NULL,NULL,'Tu usuario lo crea el administrador de tu empresa en Configuración › Usuarios. Si te dio una contraseña temporal, al entrar por primera vez el sistema te obliga a crear una nueva: debe tener al menos 6 caracteres y debes escribirla dos veces igual.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('concepto_acceso_usuario',2,'ninguna',NULL,NULL,'Si olvidaste tu contraseña, en la pantalla de ingreso usa Olvide mi contrasena: el sistema envía a tu correo un enlace para crear una nueva. Si no llega, revisa la carpeta de correo no deseado o pide al administrador que te defina una contraseña temporal desde Usuarios.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('concepto_acceso_usuario',3,'ninguna',NULL,NULL,'Lo que puedes ver y hacer depende de tu rol. Cada rol define, pantalla por pantalla, si puedes ver, crear, editar, anular, aprobar y exportar. Por eso un botón puede no aparecerte o aparecer deshabilitado: no es una falla. Pregúntale a Aria "¿por qué no puedo…?" y te dirá si es por tu rol; el cambio lo hace el administrador de la empresa en Configuración › Roles y Permisos.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('concepto_acceso_usuario',4,'ninguna',NULL,NULL,'Si tu empresa trabaja con varias sociedades (razones sociales), arriba aparece el selector de sociedad. Elige la sociedad con la que vas a trabajar: lo que registres queda en esa sociedad. La opción GRUPO — Vista consolidada muestra todo junto y sirve para consultar; para registrar documentos, movimientos de almacén o iniciar órdenes de trabajo el sistema te pide elegir antes una sociedad concreta.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('concepto_acceso_usuario',5,'ninguna',NULL,NULL,'Tu acceso puede estar limitado a algunas sociedades: lo define el administrador al crear tu usuario. Si no ves una sociedad en el selector, pídele que te la asigne.');
INSERT INTO public.asistente_manual_fichas (clave,tipo,pantalla_key,titulo,resumen,fuentes,revision) VALUES ('concepto_almacen','proceso',NULL,'Conceptos de almacén: stock, reserva, kardex, ubicación y conteo','Explica los términos del almacén y cómo se relacionan con las compras y las órdenes de trabajo.','["operaciones-app/src/zahory-mock/pages/InventarioKardexPage.jsx#InventarioKardexPage"]'::jsonb,'8dad26c438')
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('concepto_almacen',1,'ninguna',NULL,NULL,'El stock es lo que hay de cada material. Se divide en disponible, que se puede usar o vender, y reservado, que ya está apartado para una orden de trabajo o un pedido y no debe tocarse para otra cosa.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('concepto_almacen',2,'ninguna',NULL,NULL,'El kardex es el historial de movimientos de un material: cada entrada, salida, traslado y ajuste, con su fecha y su origen. Si el stock no coincide con lo que esperas, el kardex dice qué movimiento lo cambió.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('concepto_almacen',3,'ninguna',NULL,NULL,'El stock entra con la recepción de una compra y sale con el despacho a una orden de trabajo, a una venta o a un retiro. Cuando una OT necesita repuestos, primero se reservan y luego se despachan al taller; si no se usan, la reserva se libera y vuelven a disponible.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('concepto_almacen',4,'ninguna',NULL,NULL,'La ubicación es el lugar físico dentro del almacén (estante, posición). Mover traslada stock entre ubicaciones. Un almacén puede ser central o periférico, por ejemplo el de una mina.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('concepto_almacen',5,'ninguna',NULL,NULL,'El conteo cíclico compara lo que dice el sistema con lo que hay físicamente. Las diferencias se vuelven ajustes en el kardex; si superan el umbral que configuró la empresa, otra persona debe aprobarlos.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('concepto_almacen',6,'ninguna',NULL,NULL,'El stock mínimo es la cantidad por debajo de la cual hay que reponer. La pantalla Stock mínimos & reposición lista los materiales bajo su mínimo y genera la SOLPE para comprarlos.');
INSERT INTO public.asistente_manual_fichas (clave,tipo,pantalla_key,titulo,resumen,fuentes,revision) VALUES ('concepto_ceco_cebe','proceso',NULL,'Qué son el CECO y el CEBE y por qué el sistema los pide','Explica el centro de costo y el centro de beneficio, dónde se crean y en qué documentos son obligatorios.','["src/pages_admin.jsx#Maestros"]'::jsonb,'50855bc116')
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('concepto_ceco_cebe',1,'ninguna',NULL,NULL,'El CECO (centro de costo) responde a la pregunta "¿a qué área o actividad se le carga este gasto?": taller, administración, un proyecto, una mina. El CEBE (centro de beneficio) responde a "¿qué línea de negocio genera este ingreso?". Con ellos la empresa puede ver cuánto gasta y cuánto gana cada área, y arma su Estado de Resultados y su Presupuesto vs Real.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('concepto_ceco_cebe',2,'ninguna',NULL,NULL,'Se crean en Administración › Configuración › Maestros Base, con Agregar CECO y Agregar CEBE. Un CECO en uso no se borra: se desactiva, y deja de aparecer para nuevas asignaciones aunque las órdenes que ya lo usan siguen vinculadas.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('concepto_ceco_cebe',3,'ninguna',NULL,NULL,'El CECO es obligatorio al pedir y comprar: sin CECO la SOLPE no se guarda, la orden de compra no se emite y la orden de servicio a proveedor no continúa. Si una orden de compra mezcla líneas con CECO distintos o sin CECO, hay que reasignarlas antes de emitirla.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('concepto_ceco_cebe',4,'ninguna',NULL,NULL,'En el trabajo operativo, cada orden de trabajo necesita un centro de costo para poder iniciarse, y la OS Cliente debe tener CEBE asignado antes de crear sus órdenes de trabajo.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('concepto_ceco_cebe',5,'ninguna',NULL,NULL,'Si al registrar algo no encuentras el CECO que necesitas, no elijas uno parecido: pide al administrador que lo cree en Maestros Base. Un gasto cargado al CECO equivocado distorsiona los resultados del área.');
INSERT INTO public.asistente_manual_fichas (clave,tipo,pantalla_key,titulo,resumen,fuentes,revision) VALUES ('concepto_costeo','proceso',NULL,'Cómo se calcula el precio de un trabajo: Hoja de Costeo, margen y costo real','Explica la Hoja de Costeo, las variables que usa, el margen y la comparación entre lo estimado y lo real.','["src/pages_hoja_costeo_wizard.jsx#HojaCosteoWizard","src/pages_costeo_variables.jsx#CosteoVariables"]'::jsonb,'c181c07274 f42c3b0172')
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('concepto_costeo',1,'ninguna',NULL,NULL,'La Hoja de Costeo calcula cuánto le cuesta a la empresa hacer un trabajo antes de cotizarlo, para ponerle un precio que deje ganancia. Suma mano de obra (horas por el costo hora de cada cargo), materiales, depreciación de los equipos que se usan y un porcentaje de gasto administrativo, y sobre eso aplica el margen.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('concepto_costeo',2,'ninguna',NULL,NULL,'Los valores base se mantienen en Variables de Costeo: el costo hora por cargo, la depreciación de activos y el gasto administrativo. Si un cargo no tiene costo por hora, la hoja lo avisa: hay que completarlo ahí para que el cálculo sea correcto.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('concepto_costeo',3,'ninguna',NULL,NULL,'El porcentaje de gasto administrativo más el de margen debe ser menor a 100 %. La hoja se envía a revisión y solo después se puede aprobar; con la hoja aprobada se genera la cotización.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('concepto_costeo',4,'ninguna',NULL,NULL,'Si el trabajo viene de un diagnóstico técnico del taller, la hoja se arma a partir de los trabajos y actividades del diagnóstico, y las recetas de actividad definen qué tareas lleva cada actividad.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('concepto_costeo',5,'ninguna',NULL,NULL,'Cuando el trabajo se ejecuta, la orden de trabajo acumula su costo real: horas de los partes diarios, repuestos despachados, servicios de terceros y gastos logísticos. Comparar el costo real con el estimado de la hoja muestra si el trabajo dejó el margen esperado o tuvo sobrecosto.');
INSERT INTO public.asistente_manual_fichas (clave,tipo,pantalla_key,titulo,resumen,fuentes,revision) VALUES ('concepto_detraccion','proceso',NULL,'Qué es la detracción (SPOT) y cómo se registra','Explica la detracción al vender y al comprar, la autodetracción y la cuenta del Banco de la Nación.','["src/pages_fin.jsx#CxC"]'::jsonb,'06993c9c6e')
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('concepto_detraccion',1,'ninguna',NULL,NULL,'La detracción (SPOT) es una parte del importe de una factura que no se paga al proveedor sino que se deposita en su cuenta del Banco de la Nación. Aplica a determinados bienes y servicios según las reglas de SUNAT. El resultado práctico: el que paga hace dos pagos, el neto al proveedor y la detracción al Banco de la Nación.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('concepto_detraccion',2,'ninguna',NULL,NULL,'Cuando tú compras: en Cuentas por Pagar registra la obligación con Aplicar detracción y paga al proveedor exactamente el neto; el depósito al Banco de la Nación se registra aparte con su constancia. El proveedor debe tener registrada en su ficha su cuenta del Banco de la Nación, que debe estar en soles.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('concepto_detraccion',3,'ninguna',NULL,NULL,'Cuando tú vendes: el cliente te paga el neto y deposita la detracción en tu cuenta del Banco de la Nación. Registra el cobro normal por el neto en Cuentas por Cobrar o en Facturación.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('concepto_detraccion',4,'ninguna',NULL,NULL,'Si el cliente no depositó la detracción y te pagó el total, te toca hacer el depósito a ti: usa Registrar autodetracción, selecciona las cuentas e ingresa el número y la fecha de la constancia del depósito.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('concepto_detraccion',5,'ninguna',NULL,NULL,'Las cuentas de detracciones no se usan para transferencias entre cuentas propias en Tesorería.');
INSERT INTO public.asistente_manual_fichas (clave,tipo,pantalla_key,titulo,resumen,fuentes,revision) VALUES ('concepto_documentos_compra','proceso',NULL,'Los documentos de una compra: SOLPE, orden de compra, recepción, factura y pago','Explica qué es cada documento del ciclo de compra, quién interviene y las otras formas de registrar un gasto.','["src/pages_ops.jsx#OrdenesServicio","src/pages_ops.jsx#CotizacionesCompras"]'::jsonb,'0144236b2a 1618a00848')
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('concepto_documentos_compra',1,'ninguna',NULL,NULL,'La SOLPE (solicitud de pedido) es el pedido interno: alguien de un área dice qué necesita, para qué CECO y con qué urgencia. Nace en borrador, se envía y alguien la atiende y la aprueba. Una SOLPE no es una compra todavía: es la necesidad.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('concepto_documentos_compra',2,'ninguna',NULL,NULL,'Con la SOLPE aprobada, Compras decide a quién comprar en la Bandeja de Sourcing: se elige proveedor por cada línea, de modo que un mismo pedido puede repartirse entre varios proveedores y se genera una orden de compra por proveedor. Si hace falta comparar precios, antes se abre un proceso de cotización con proveedores.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('concepto_documentos_compra',3,'ninguna',NULL,NULL,'La OC (orden de compra) es el compromiso con el proveedor: ítems, cantidades, precios y CECO. Se guarda en borrador, se emite y se puede marcar como confirmada cuando el proveedor la acepta. Permite registrar anticipos y el tránsito de la mercadería.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('concepto_documentos_compra',4,'ninguna',NULL,NULL,'La recepción registra lo que llegó de verdad y actualiza el stock. La recepción física y la factura van por separado: puede llegar la mercadería sin factura, y la factura se completa después. Si el proveedor no entregará un saldo, esa cantidad se libera y vuelve a la Bandeja de Sourcing.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('concepto_documentos_compra',5,'ninguna',NULL,NULL,'La factura del proveedor crea la CxP (cuenta por pagar), vinculada a su orden de compra para no duplicar la deuda. El pago se registra en Cuentas por Pagar eligiendo la cuenta bancaria, y admite pagos parciales. Si la factura está sujeta a detracción se paga al proveedor el neto.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('concepto_documentos_compra',6,'ninguna',NULL,NULL,'No toda salida de dinero pasa por una orden de compra. Un servicio contratado a un tercero va con Orden de Servicio a proveedor y su conformidad. Un gasto menor se registra en Compras / Gastos con Nuevo egreso, o en Caja Chica si se pagó con el fondo. Los recibos por honorarios, tributos y reembolsos se registran directo en Cuentas por Pagar.');
INSERT INTO public.asistente_manual_fichas (clave,tipo,pantalla_key,titulo,resumen,fuentes,revision) VALUES ('concepto_documentos_venta','proceso',NULL,'Los documentos de una venta: cotización, OS Cliente, OT, OF, valorización y factura','Explica qué es cada documento del ciclo de venta, en qué se diferencian y en qué orden nacen.','["src/pages_core.jsx#OSCliente","src/pages_extra.jsx#Cotizaciones","src/pages_extra.jsx#Valorizacion","src/pages_fin.jsx#Ventas"]'::jsonb,'90315ca39a 2e3ef06c5d e710949e0a 9566fef6c9')
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('concepto_documentos_venta',1,'ninguna',NULL,NULL,'La cotización es la oferta al cliente: qué se le va a hacer y por cuánto. Puede salir de una oportunidad del Pipeline y, si el trabajo necesita calcular costos, de una Hoja de Costeo. Mientras no esté aprobada no compromete nada.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('concepto_documentos_venta',2,'ninguna',NULL,NULL,'La OS Cliente (orden de servicio del cliente) es el compromiso: nace de una cotización aprobada y agrupa todo lo que se le hará a ese cliente por ese pedido. Es el documento que se valoriza y se factura. Vive en Administración › Comercial › OS Cliente.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('concepto_documentos_venta',3,'ninguna',NULL,NULL,'La OT (orden de trabajo) es el trabajo concreto que ejecuta el taller o el equipo de campo para cumplir la OS: tiene técnico responsable, tareas, repuestos, partes diarios y costos reales. Una OS puede tener varias OT. La OF (orden de fabricación) es lo mismo pero para fabricar una pieza: tiene ruta de tareas y lista de materiales. Se usa OT para mantenimiento o servicio y OF para fabricación.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('concepto_documentos_venta',4,'ninguna',NULL,NULL,'La valorización dice cuánto de lo ejecutado ya se puede cobrar. Se registra dentro de la OS Cliente y debe aprobarse; se apoya en el cierre técnico de la OT y en el acta de conformidad del cliente.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('concepto_documentos_venta',5,'ninguna',NULL,NULL,'La factura (comprobante) se emite desde la valorización aprobada, en Administración › Administración › Facturación, y con Generar CxC crea la cuenta por cobrar, que es donde se controla el cobro y la mora.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('concepto_documentos_venta',6,'ninguna',NULL,NULL,'Ventas y Facturación no son lo mismo. Ventas registra ventas directas que no pasan por orden de servicio (por ejemplo un producto o un servicio simple): se registra la venta, se confirma, se emite su comprobante y se cobra ahí mismo. Facturación reúne todos los comprobantes, vengan de una valorización, de una venta o emitidos directamente.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('concepto_documentos_venta',7,'ninguna',NULL,NULL,'Un servicio que se cobra todos los meses se configura en la OS Cliente como cobro mensual: indicas la tarifa mensual sin IGV y la fecha de inicio; la primera OT la creas tú y después se crea sola el día 1 de cada mes.');
INSERT INTO public.asistente_manual_fichas (clave,tipo,pantalla_key,titulo,resumen,fuentes,revision) VALUES ('concepto_personal_planilla','proceso',NULL,'Cómo se conectan el personal, la asistencia y la planilla','Explica qué necesita un trabajador para marcar y cobrar, y cómo la asistencia y las solicitudes llegan a la planilla.','["src/pages_ops.jsx#Nomina","src/pages_ops.jsx#ControlAsistencia"]'::jsonb,'21d2972451 ce8d288576')
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('concepto_personal_planilla',1,'ninguna',NULL,NULL,'Cada trabajador tiene una ficha en Personal Administrativo o en Personal Operativo, con su contrato, su cargo, su jornada, su cuenta bancaria y sus documentos. Al contratar desde Reclutamiento, el sistema pregunta en cuál de las dos se crea.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('concepto_personal_planilla',2,'ninguna',NULL,NULL,'Para marcar asistencia el trabajador necesita un turno asignado en su ficha. Marca desde el celular; la geocerca define desde dónde es válido marcar, y si está fuera puede enviar un reporte para revisión. Sin señal, la marcación se guarda y se sincroniza al recuperar conexión.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('concepto_personal_planilla',3,'ninguna',NULL,NULL,'Las vacaciones, permisos y descansos se piden como solicitudes; una vez aprobadas, Aplicar a asistencia crea los registros de esos días para que no cuenten como falta. Una marcación errada se corrige con un ajuste, que exige motivo y aprobación.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('concepto_personal_planilla',4,'ninguna',NULL,NULL,'La planilla se calcula por período en Nómina: se crea el período y se calcula con Procesar; si se paga por quincenas, la primera quincena se procesa antes que la segunda. Los ingresos o descuentos extraordinarios se registran antes de cerrar. Al cerrar el período se generan los egresos de la planilla, por eso conviene revisar las boletas antes.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('concepto_personal_planilla',5,'ninguna',NULL,NULL,'El trabajador ve sus boletas en Mi portal, después de registrar su consentimiento de entrega electrónica. Ahí también sube su contrato firmado y pide constancias, horas extra, vacaciones y permisos.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('concepto_personal_planilla',6,'ninguna',NULL,NULL,'Cuando un trabajador cesa, la Liquidación por Cese calcula lo que se le debe; al confirmarla se genera la cuenta por pagar y se bloquea su acceso al sistema.');
INSERT INTO public.asistente_manual_fichas (clave,tipo,pantalla_key,titulo,resumen,fuentes,revision) VALUES ('concepto_que_es_opera','proceso',NULL,'Qué es OPERA y para qué sirve cada aplicación','Orientación para quien recién entra: qué es OPERA, qué hace el sistema, para qué sirve cada una de sus tres aplicaciones, cómo está organizado el menú y qué hacer el primer día.','["catalogo/pantallas.json"]'::jsonb,'3495e022a1')
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('concepto_que_es_opera',1,'ninguna',NULL,NULL,'OPERA es el sistema donde la empresa lleva todo su trabajo en un solo lugar: lo que vende, lo que compra, lo que cobra y paga, su personal, su taller, su almacén, su flota y su transporte. Lo que una persona registra en un módulo lo usan los demás: por ejemplo, una cotización aprobada se vuelve orden de servicio, la orden genera trabajo en el taller, el trabajo terminado se valoriza y se factura, y la factura queda como cuenta por cobrar.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('concepto_que_es_opera',2,'ninguna',NULL,NULL,'Tiene tres aplicaciones, que eliges al entrar en la pantalla Elige una aplicación. Administración es para oficina: comercial, compras, finanzas, RRHH y configuración. Operaciones es para el trabajo operativo: órdenes de trabajo del taller, almacén, flota y alquileres, transporte y producción. Control de asistencia y la versión móvil son para el celular: marcar asistencia, registrar partes, aprobar y vender en campo.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('concepto_que_es_opera',3,'ninguna',NULL,NULL,'En Administración el menú se agrupa por área: Inicio, CRM & Marketing, Comercial, Compras, Logística, Operaciones, Administración (finanzas), RRHH, Customer Success, Dashboards y Configuración. Solo ves las áreas y pantallas que tu rol permite; si no ves algo, no es un error: tu rol no lo tiene asignado y lo habilita el administrador de tu empresa en Roles y Permisos.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('concepto_que_es_opera',4,'ninguna',NULL,NULL,'Empieza siempre por Inicio: muestra lo que tienes pendiente hoy (aprobaciones, documentos por atender, avisos) y un botón para ir directo a cada cosa. Ahí mismo puedes preguntarle a Aria.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('concepto_que_es_opera',5,'ninguna',NULL,NULL,'El primer día conviene: revisar tu ficha y tus documentos en Mi portal, marcar tu asistencia si te corresponde, y pedirle a Aria que te explique la pantalla donde estás. Aria te dice la ruta exacta de cada pantalla y te lleva con el botón Ir a.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('concepto_que_es_opera',6,'ninguna',NULL,NULL,'Casi todas las pantallas funcionan igual: una lista con buscador y filtros, un botón para crear (Nuevo…), y al abrir un registro ves su detalle con las acciones permitidas según su estado. Los indicadores de arriba de cada lista suelen servir también como filtro al tocarlos.');
INSERT INTO public.asistente_manual_fichas (clave,tipo,pantalla_key,titulo,resumen,fuentes,revision) VALUES ('configuracion_wms','pantalla','inventario','Configuración del WMS','Opciones de funcionamiento del almacén.','["operaciones-app/src/zahory-mock/pages/wms/ConfiguracionWmsPage.jsx#ConfiguracionWmsPage"]'::jsonb,'a3620ec951')
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('configuracion_wms',1,'inventario',NULL,NULL,'Activa o desactiva las funciones del almacén y define el umbral de aprobación de los conteos, que debe ser cero o mayor.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('configuracion_wms',2,'inventario',NULL,NULL,'Guardar cambios conserva la configuración; el menú de Almacén se actualiza al recargar la página.');
INSERT INTO public.asistente_manual_fichas (clave,tipo,pantalla_key,titulo,resumen,fuentes,revision) VALUES ('conteos_ciclicos','pantalla','inventario','Conteos cíclicos','Conteo físico del almacén y ajuste de las diferencias.','["operaciones-app/src/zahory-mock/pages/wms/ConteosPage.jsx#ConteosPage"]'::jsonb,'f926063c1c')
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('conteos_ciclicos',1,'inventario',NULL,NULL,'Inicia con Nuevo conteo y elige el almacén a contar; Crear conteo genera sus líneas.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('conteos_ciclicos',2,'inventario',NULL,NULL,'Registra lo contado y usa Guardar avance para continuar después. Un código que no pertenece al conteo se rechaza.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('conteos_ciclicos',3,'inventario',NULL,NULL,'Cerrar conteo exige contar todas las líneas y registra los ajustes en el kardex.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('conteos_ciclicos',4,'inventario',NULL,NULL,'Si las diferencias superan el umbral, el conteo queda por aprobar por otra persona, que usa Aprobar ajustes o Devolver a recontar.');
INSERT INTO public.asistente_manual_fichas (clave,tipo,pantalla_key,titulo,resumen,fuentes,revision) VALUES ('contratos_rental','pantalla','contratos_alquiler','Contratos Rental','Contratos de alquiler de equipos y sus tarifas.','["operaciones-app/src/zahory-mock/pages/flota/ContratosRentalPage.jsx#ContratosRentalPage"]'::jsonb,'b8f7626900')
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('contratos_rental',1,'contratos_alquiler',NULL,NULL,'Registra un alquiler con Nuevo contrato y Crear contrato.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('contratos_rental',2,'contratos_alquiler',NULL,NULL,'Cambiar tarifa modifica la tarifa y Guardar versión conserva el cambio como una nueva versión del contrato.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('contratos_rental',3,'contratos_alquiler',NULL,NULL,'Cambiar a cambia el estado del contrato.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('contratos_rental',4,'contratos_alquiler',NULL,NULL,'Para qué sirve: el contrato de alquiler fija con qué cliente, qué equipos, en qué moneda y a qué tarifa por hora se alquila, y el mínimo que se cobra aunque el equipo opere menos. Al crear el contrato son obligatorios el cliente, la sociedad, la moneda y el mínimo con su unidad y su periodicidad.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('contratos_rental',5,'contratos_alquiler',NULL,NULL,'La tarifa tiene versiones. Cambiar tarifa pide la nueva tarifa por hora, la fecha desde la que rige y el motivo, y Guardar versión la conserva sin borrar la anterior. La liquidación del mes cobra cada día con la tarifa que estaba vigente ese día, así que un cambio de tarifa a mitad de mes se aplica solo desde su fecha.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('contratos_rental',6,'contratos_alquiler',NULL,NULL,'El contrato alimenta el resto del módulo: los equipos del contrato se entregan y se reciben con Actas & Despachos, sus horas se registran en los partes diarios de Liquidación & DMR, y la liquidación mensual usa su tarifa, su mínimo y su meta de disponibilidad.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('contratos_rental',7,'contratos_alquiler',NULL,NULL,'Quien edita contratos puede crearlos y cambiarlos; los demás roles con acceso solo los consultan. Si no ves Nuevo contrato o Cambiar tarifa, es por tu rol.');
INSERT INTO public.asistente_manual_fichas (clave,tipo,pantalla_key,titulo,resumen,fuentes,revision) VALUES ('asistencia','pantalla','asistencia','Control de Asistencia','Marcaciones, geocercas, ajustes y reportes de asistencia del personal.','["src/pages_ops.jsx#ControlAsistencia"]'::jsonb,'ce8d288576')
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('asistencia',1,'asistencia',NULL,NULL,'Cada trabajador necesita un turno asignado antes de marcar asistencia; se le asigna desde su ficha en Personal.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('asistencia',2,'asistencia',NULL,NULL,'Las marcaciones llegan del Reloj Control (Móvil). También puedes registrarlas a mano, con Registro masivo o con Importar marcaciones desde un archivo, que muestra una vista previa antes de Confirmar importacion.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('asistencia',3,'asistencia',NULL,NULL,'Las geocercas definen dónde se puede marcar: se crean con nombre, latitud y longitud, o dibujando en el mapa un polígono de al menos tres vértices.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('asistencia',4,'asistencia',NULL,NULL,'Para corregir una marcación se pide un ajuste con su motivo, que es obligatorio; quien aprueba usa Aprobar o Rechazar. Registrar una falta también exige motivo.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('asistencia',5,'asistencia',NULL,NULL,'En operaciones mineras, el ciclo de cada trabajador se registra con Guardar Ciclo, que genera sus registros diarios.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('asistencia',6,'asistencia',NULL,NULL,'Reporte mensual resume el mes y Exportar Excel descarga los registros.');
INSERT INTO public.asistente_manual_fichas (clave,tipo,pantalla_key,titulo,resumen,fuentes,revision) VALUES ('control_horas','pantalla','control_horas','Control de Horas','Horas trabajadas por colaborador en cada OT, con su disponibilidad y su costo imputado.','["src/pages_ops.jsx#ControlHoras"]'::jsonb,'e8ca7edb9b')
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('control_horas',1,'control_horas',NULL,NULL,'Muestra las horas por colaborador y por OT del mes elegido; cambia de mes con Mes anterior y Mes siguiente.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('control_horas',2,'control_horas',NULL,NULL,'Filtra por colaborador y por modalidad: planilla u honorarios.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('control_horas',3,'control_horas',NULL,NULL,'Evaluar mes revisa la productividad del período y avisa cuántas alertas de baja productividad encontró.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('control_horas',4,'control_horas',NULL,NULL,'Exportar Excel descarga el reporte.');
INSERT INTO public.asistente_manual_fichas (clave,tipo,pantalla_key,titulo,resumen,fuentes,revision) VALUES ('cot_compras','pantalla','cot_compras','Cotizaciones de Compras','Procesos de cotización con proveedores hasta generar la orden de compra o de servicio.','["src/pages_ops.jsx#CotizacionesCompras"]'::jsonb,'1618a00848')
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('cot_compras',1,'cot_compras',NULL,NULL,'Inicia con Nuevo proceso de cotizacion y avanza con Siguiente; al confirmar, el proceso se crea y se envía a los proveedores.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('cot_compras',2,'cot_compras',NULL,NULL,'Registrar respuesta anota lo que cotizó cada proveedor.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('cot_compras',3,'cot_compras',NULL,NULL,'Seleccionar ganador elige la mejor oferta y Confirmar seleccion y generar OC / OS crea la orden de compra o la orden de servicio.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('cot_compras',4,'cot_compras',NULL,NULL,'Ver proceso abre el detalle de un proceso.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('cot_compras',5,'cot_compras',NULL,NULL,'Úsalo cuando quieres comparar precios antes de comprar: el mismo pedido se envía a varios proveedores, registras lo que responde cada uno y eliges al ganador. Si ya sabes a quién comprar, no hace falta: ve directo a la Bandeja de Sourcing o a la orden de compra.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('cot_compras',6,'cot_compras',NULL,NULL,'Si cada material conviene comprarlo a un proveedor distinto, usa la Bandeja de Sourcing: ahí se asigna el proveedor línea por línea y se genera una orden por proveedor.');
INSERT INTO public.asistente_manual_fichas (clave,tipo,pantalla_key,titulo,resumen,fuentes,revision) VALUES ('cotizaciones','pantalla','cotizaciones','Cotizaciones','Elaboración, envío y aprobación de cotizaciones, y su paso a orden de servicio.','["src/pages_extra.jsx#Cotizaciones"]'::jsonb,'2e3ef06c5d')
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('cotizaciones',1,'cotizaciones',NULL,NULL,'Crea una cotización con Nueva cotización: elige la cuenta, agrega las partidas con Agregar partida e indica la condición de pago. Puedes dividir el pago en hitos con Agregar hito.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('cotizaciones',2,'cotizaciones',NULL,NULL,'Si sales con cambios sin guardar, la pantalla pregunta si quieres Salir sin guardar o Seguir editando.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('cotizaciones',3,'cotizaciones',NULL,NULL,'Envía la cotización con PDF o con Copiar enlace. Página de firmas muestra la hoja de firmas del documento.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('cotizaciones',4,'cotizaciones',NULL,NULL,'Cuando el cliente acepta usa Confirmar aprobación e indica el canal de aprobación; puedes adjuntar el sustento.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('cotizaciones',5,'cotizaciones',NULL,NULL,'Con la cotización aprobada usa Crear OS Cliente, como Crear nueva OS o Agregar a OS existente. El indicador Por convertir filtra las aprobadas que aún no tienen OS.');
INSERT INTO public.asistente_manual_fichas (clave,tipo,pantalla_key,titulo,resumen,fuentes,revision) VALUES ('cuentas','pantalla','cuentas','Cuentas y Contactos','Ficha de cada cliente: datos, contactos, precios acordados y condiciones comerciales.','["src/pages_ops.jsx#Cuentas"]'::jsonb,'4c81d6e303')
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('cuentas',1,'cuentas',NULL,NULL,'Crea un cliente con Nueva cuenta. Editar cuenta cambia sus datos y Eliminar cuenta lo borra con confirmación.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('cuentas',2,'cuentas',NULL,NULL,'Agrega a las personas del cliente con Nuevo contacto y marca al Principal.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('cuentas',3,'cuentas',NULL,NULL,'Agregar precio registra un precio acordado con ese cliente, y Guardar condiciones conserva sus condiciones comerciales.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('cuentas',4,'cuentas',NULL,NULL,'Para cargar muchas cuentas descarga la plantilla y usa Importar Excel.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('cuentas',5,'cuentas',NULL,NULL,'Tipos de cuenta: Prospecto es una empresa que aún no compra; Cliente ya compra; Partner es un aliado comercial. Para crear una cuenta basta la razón social; el RUC es opcional pero conviene registrarlo para facturar y para detectar duplicados.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('cuentas',6,'cuentas',NULL,NULL,'También puedes pedirle a Aria que cree la cuenta: dile la razón social y lo que tengas (RUC, tipo, nombre comercial, industria, tamaño, teléfono, correo, dirección, condición de pago, límite de crédito, origen y el contacto principal). Aria avisa si ya existe una cuenta con ese RUC o ese nombre, muestra una tarjeta con los datos y nada se graba hasta pulsar Confirmar. Requiere permiso de crear en Cuentas.');
INSERT INTO public.asistente_manual_fichas (clave,tipo,pantalla_key,titulo,resumen,fuentes,revision) VALUES ('cxc','pantalla','cxc','Cuentas por cobrar','Controla lo que deben los clientes: cobros, gestiones de cobranza, mora, autodetracciones y carga masiva de facturas desde Excel.','["src/pages_fin.jsx#CxC"]'::jsonb,'06993c9c6e')
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('cxc',1,'cxc',NULL,NULL,'La lista muestra cada cuenta por cobrar con su saldo y vencimiento. Usa Cobrar para registrar un pago: elige el medio de pago e ingresa el número de operación o referencia bancaria.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('cxc',2,'cxc',NULL,NULL,'Nueva gestión registra una acción de cobranza (llamada, correo, compromiso de pago). Según el resultado, la fecha de próxima acción es obligatoria.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('cxc',3,'cxc',NULL,NULL,'Si el cliente no depositó la detracción, usa Registrar autodetracción con las cuentas y la constancia del depósito.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('cxc',4,'cxc','cxc','editar','La mora se calcula con una tasa diaria. Puedes Condonar mora para que deje de calcularse (queda en el historial) o Restaurar tasa al valor estándar.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('cxc',5,'cxc','cxc','anular','Revertir cobros deshace los cobros y conciliaciones de una cuenta; Anular factura y CxC relacionada anula ambas con confirmación.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('cxc',6,'cxc',NULL,NULL,'Carga masiva sube muchas facturas de clientes a la vez desde una plantilla de Excel: descargas la plantilla, la completas con las facturas que tienen saldo pendiente y subes el archivo; la pantalla muestra una revisión antes de importar. Cada fila crea la factura y su cuenta por cobrar, y crea al cliente si no existía. Es el mismo botón Carga masiva de Facturación. Exportar descarga la lista.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('cxc',7,'cxc',NULL,NULL,'En la cuenta por cobrar puedes guardar sustentos con Adjuntar archivo y bajarlos con Descargar.');
INSERT INTO public.asistente_manual_fichas (clave,tipo,pantalla_key,titulo,resumen,fuentes,revision) VALUES ('cxp','pantalla','cxp','Cuentas por pagar','Registra y controla las deudas con proveedores, colaboradores y tributos: facturas, recibos por honorarios, notas de crédito o débito, detracciones y pagos.','["src/pages_fin.jsx#CxP"]'::jsonb,'d66ee1335d')
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('cxp',1,'cxp',NULL,NULL,'Usa Nuevo egreso para registrar una obligación. Según el tipo, completa proveedor y factura, el emisor del recibo por honorarios (interno o externo), el tributo y su periodo, o el colaborador del reembolso.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('cxp',2,'cxp',NULL,NULL,'Una factura de compra debe vincularse a su orden de compra de origen. La pantalla avisa si el número de factura ya existe para ese proveedor y sociedad.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('cxp',3,'cxp',NULL,NULL,'Para pagar usa Pagar en la CxP: elige la cuenta bancaria de origen, la fecha y el monto. Se admiten pagos parciales y el saldo queda pendiente.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('cxp',4,'cxp',NULL,NULL,'Si la factura está sujeta a detracción (SPOT), registra la obligación con Aplicar detracción y paga al proveedor exactamente el neto; el depósito al Banco de la Nación se registra con la constancia.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('cxp',5,'cxp',NULL,NULL,'Registrar NC y Registrar ND ajustan la deuda con notas de crédito o débito del proveedor. Completar factura agrega los datos de una CxP preliminar.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('cxp',6,'cxp','cxp','editar','Puedes cambiar la Prioridad de pago de una CxP para ordenar qué se paga primero.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('cxp',7,'cxp','cxp','anular','Anular una CxP conserva su historial e indica el motivo; antes la pantalla verifica que no tenga pagos ni dependencias que lo impidan.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('cxp',8,'cxp',NULL,NULL,'Para cargar muchas deudas a la vez usa Descargar plantilla, complétala y súbela con Subir plantilla masiva; la pantalla muestra las filas válidas y rechazadas antes de importar. Descargar reporte Excel exporta las cuentas y sus pagos.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('cxp',9,'cxp',NULL,NULL,'Una CxP preliminar se puede borrar con Eliminar CxP preliminar, que elimina el registro; Anular, en cambio, conserva el historial. Guardar clasificación corrige la clasificación de una CxP, y puedes adjuntar archivos a la cuenta con Adjuntar archivo.');
INSERT INTO public.asistente_manual_fichas (clave,tipo,pantalla_key,titulo,resumen,fuentes,revision) VALUES ('custodia_terceros','pantalla','inventario','Custodia de terceros','Mercadería de clientes guardada en el almacén (custodia): ingresos, posiciones, retiros, tarifa y liquidación del almacenaje para facturar.','["operaciones-app/src/zahory-mock/pages/wms/CustodiaPage.jsx#CustodiaPage"]'::jsonb,'b96d4c42a1')
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('custodia_terceros',1,'inventario',NULL,NULL,'Registrar ingreso anota la mercadería de un tercero que entra en custodia y Asignar posiciones define dónde se guarda.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('custodia_terceros',2,'inventario',NULL,NULL,'Solicitar retiro crea el retiro de esa mercadería.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('custodia_terceros',3,'inventario',NULL,NULL,'Tarifa define lo que se cobra por la custodia.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('custodia_terceros',4,'inventario',NULL,NULL,'Calcular obtiene la liquidación del período y Enviar a Ventas la envía como venta en borrador.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('custodia_terceros',5,'inventario',NULL,NULL,'Para qué sirve: guardar mercadería de un cliente en tus posiciones. No es tuya: no se valoriza en tu inventario y se cobra por posición-día (cada posición ocupada por cada día) y por movimiento (ingresos y retiros).');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('custodia_terceros',6,'inventario',NULL,NULL,'Antes de liquidar, cada cliente necesita su Tarifa: importe por posición-día, importe por movimiento y moneda. Sin tarifa la pantalla avisa «Sin tarifa» y no se puede liquidar.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('custodia_terceros',7,'inventario',NULL,NULL,'Registrar ingreso pide cliente, material, cantidad y, si la hay, la guía del cliente; Asignar posiciones indica en qué ubicación queda. Solicitar retiro crea el retiro por la cantidad indicada; lo solicitado queda como Comprometido hasta que se despacha.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('custodia_terceros',8,'inventario',NULL,NULL,'Para cobrar: elige el cliente, el período (Desde y Hasta) y usa Calcular; verás posiciones-día por tarifa, movimientos por tarifa y el total sin IGV. Enviar a Ventas crea una venta en borrador por ese importe más IGV para que Facturación la emita. Un período ya enviado no se envía de nuevo.');
INSERT INTO public.asistente_manual_fichas (clave,tipo,pantalla_key,titulo,resumen,fuentes,revision) VALUES ('dashboard_gerencial','pantalla','dashboard','Dashboard Gerencial','Indicadores gerenciales de la operación.','["operaciones-app/src/zahory-mock/pages/dashboardGerencial.jsx#DashboardPage"]'::jsonb,'33352eff28')
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('dashboard_gerencial',1,'dashboard',NULL,NULL,'Es un tablero de consulta con los indicadores de la operación del período.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('dashboard_gerencial',2,'dashboard',NULL,NULL,'Exportar PDF descarga el tablero.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('dashboard_gerencial',3,'dashboard',NULL,NULL,'Si no hay tipo de cambio para el período, la pantalla lo avisa.');
INSERT INTO public.asistente_manual_fichas (clave,tipo,pantalla_key,titulo,resumen,fuentes,revision) VALUES ('dashboard','pantalla','dashboard','Dashboards','Tableros de indicadores de la empresa.','["src/pages_dashboards.jsx#DashboardsPage"]'::jsonb,'063f9e54c0')
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('dashboard',1,'dashboard',NULL,NULL,'Es una pantalla de consulta: reúne los tableros de indicadores disponibles para tu rol.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('dashboard',2,'dashboard',NULL,NULL,'No registra información; los datos vienen de lo que se registra en el resto del sistema.');
INSERT INTO public.asistente_manual_fichas (clave,tipo,pantalla_key,titulo,resumen,fuentes,revision) VALUES ('despachos_almacen','pantalla','inventario','Despachos de almacén','Cola única de salida del almacén: entregas a taller por OT, ventas con guía de remisión y retiros de custodia, preparadas con picking.','["operaciones-app/src/zahory-mock/pages/wms/DespachosPage.jsx#DespachosPage"]'::jsonb,'4b4a871230')
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('despachos_almacen',1,'inventario',NULL,NULL,'Filtra la cola por canal (OT, Venta o Custodia) y selecciona un pedido para prepararlo.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('despachos_almacen',2,'inventario',NULL,NULL,'Escanea el código del material o de la ubicación para marcar lo preparado, o usa Preparar todo lo listo para cargar las cantidades pendientes.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('despachos_almacen',3,'inventario','inventario','despachar','Si faltan unidades en una venta o retiro, usa Reintentar reserva para reservar lo que ya está disponible.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('despachos_almacen',4,'inventario','inventario','despachar','Despacha el pedido: en OT queda entregado al taller y se actualiza el kardex; en ventas completa la guía de remisión (modalidad, transporte y peso), que se emite con la serie T001 al despachar.');
INSERT INTO public.asistente_manual_fichas (clave,tipo,pantalla_key,titulo,resumen,fuentes,revision) VALUES ('detalle_of','pantalla','of','Detalle de OF','Ficha de una orden de fabricación (OF): estados, ruta de tareas, materiales, material no planificado, aprobación, registro y revisión de avance por partes, costo real y calidad.','["operaciones-app/src/zahory-mock/pages/of/DetalleOFPage.jsx#DetalleOFPage"]'::jsonb,'8875d0cc93')
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('detalle_of',1,'of',NULL,NULL,'En Ruta arma la secuencia de trabajo con Agregar tarea.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('detalle_of',2,'of',NULL,NULL,'En Materiales agrega lo que consume la orden con Agregar material; lo que no estaba previsto se agrega como Material no planificado.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('detalle_of',3,'of',NULL,NULL,'Editar y Quitar corrigen una tarea o un material.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('detalle_of',4,'of',NULL,NULL,'Aprobar OF aprueba la orden.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('detalle_of',5,'of',NULL,NULL,'Estados de la OF: Borrador e Ingeniería son editables; al aprobar pasa a Aprobada y la ruta queda fija. Una OF anulada ya no admite cambios. La línea de tiempo de la cabecera muestra en qué estado va.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('detalle_of',6,'of',NULL,NULL,'La ruta se ordena como Trabajo › Actividad › Tarea. Cada tarea lleva cargo, horas estimadas y, si corresponde, el equipo con que se hace. La bahía no se escribe: sale del equipo elegido, y si la tarea no tiene equipo la ubica el Planner (se lee «La asigna el Planner»).');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('detalle_of',7,'of',NULL,NULL,'Si la OF nació de una OS con Hoja de Costeo llega precargada con las tareas y materiales de la hoja, y toma su moneda; revísala antes de aprobar. Si se creó como OF adicional llega vacía y se arma a mano.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('detalle_of',8,'of',NULL,NULL,'Después de aprobar solo se puede agregar un Material no planificado, y exige escribir el motivo; ese motivo queda visible en la lista de materiales. Para cambiar la ruta de una OF aprobada no hay botón: hay que pedirlo a quien administra el sistema.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('detalle_of',9,'of',NULL,NULL,'Si no ves Aprobar OF es porque tu rol no tiene el permiso de aprobar Órdenes de Fabricación o porque la OF ya no está en Borrador o Ingeniería. Si no ves Agregar tarea, tu rol no puede editar OF.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('detalle_of',10,'of',NULL,NULL,'Con la OF Aprobada o En producción, Registrar avance crea un parte: elige la operación, el técnico, la fecha (no futura), las horas trabajadas y el avance de la operación (0 a 100; con 100 queda terminada). El parte queda Por aprobar.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('detalle_of',11,'of',NULL,NULL,'La pestaña Partes lista los partes de la OF con su estado (Por aprobar, Aprobado, Observado). Revisar abre el parte: Aprobar parte suma las horas, actualiza el avance de la operación y de la OF y el costo real; Observar lo devuelve con una observación y el técnico registra uno corregido. Si cambias el avance reportado, la observación es obligatoria.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('detalle_of',12,'of',NULL,NULL,'La OF pasa de Aprobada a En producción con el primer parte aprobado. Desde ahí la cabecera muestra el avance (ponderado por horas estimadas), las horas reales, el costo real a la fecha y los partes por aprobar; la Ruta muestra por tarea las horas reales, una barra de avance y su estado.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('detalle_of',13,'of',NULL,NULL,'El costo real suma la mano de obra de los partes aprobados (horas por la tarifa del técnico; si no tiene, la del cargo de la operación) y los materiales despachados. Si no ves Registrar avance tu rol no puede editar OF o todas las operaciones están terminadas; si no ves Revisar, tu rol no tiene el permiso de aprobar OF.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('detalle_of',14,'of',NULL,NULL,'Con la OF en producción, Enviar a calidad la pasa a En calidad; en la pestaña Calidad se registran las mediciones por unidad y las no conformidades. Liberar OF la deja Lista para entrega cuando todas las críticas están dentro de tolerancia y no hay no conformidades abiertas.');
INSERT INTO public.asistente_manual_fichas (clave,tipo,pantalla_key,titulo,resumen,fuentes,revision) VALUES ('detalle_viaje','pantalla','transporte_comercial','Detalle de viaje','Asignación, despacho y reprogramación de un viaje.','["operaciones-app/src/zahory-mock/pages/transporte/ViajeDetallePage.jsx#ViajeDetallePage"]'::jsonb,'42c87dc48a')
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('detalle_viaje',1,'transporte_comercial',NULL,NULL,'Asignar y despachar define la unidad y el conductor y da la salida del viaje.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('detalle_viaje',2,'transporte_comercial',NULL,NULL,'Cambiar asignación reemplaza la unidad o el conductor, y Reprogramar cambia la fecha.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('detalle_viaje',3,'transporte_comercial',NULL,NULL,'Desde el detalle puedes ir a la Hoja de Ruta o volver al Monitor de Viajes.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('detalle_viaje',4,'transporte_comercial',NULL,NULL,'Para qué sirve: desde el detalle se asigna quién hace el viaje y se le da la salida. Solo se puede asignar y despachar un viaje que está programado.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('detalle_viaje',5,'transporte_comercial',NULL,NULL,'Al asignar, el sistema bloquea una unidad o un conductor que esté inactivo, que pertenezca a otro transportista, que ya esté en otro viaje en curso o que tenga el certificado MTC o el brevete vencido.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('detalle_viaje',6,'transporte_comercial',NULL,NULL,'En otros casos deja continuar pero pide escribir un motivo de excepción: cuando la unidad no tiene registrada su capacidad o esta no alcanza para la carga, o cuando el MTC o el brevete no tienen fecha de vigencia registrada. En ese caso el botón dice Despachar con excepción.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('detalle_viaje',7,'transporte_comercial',NULL,NULL,'Guardar asignación deja la unidad y el conductor definidos sin dar la salida, y queda anotado en la bitácora del viaje. Agregar nota suma una nota a la bitácora sin cambiar el estado. Cancelar viaje pide confirmación.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('detalle_viaje',8,'transporte_comercial',NULL,NULL,'El sistema no recibe GPS de las unidades: la posición y la hora de llegada que muestra un viaje en ruta son estimadas por el tiempo transcurrido desde la salida. Un incidente deja el viaje en estado con incidente.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('detalle_viaje',9,'transporte_comercial',NULL,NULL,'Si no puedes despachar, lo más frecuente es un brevete o un MTC vencido: actualiza su vigencia en Transporte › Flota.');
INSERT INTO public.asistente_manual_fichas (clave,tipo,pantalla_key,titulo,resumen,fuentes,revision) VALUES ('devoluciones_almacen','pantalla','inventario','Devoluciones','Ingreso de mercadería devuelta y su inspección.','["operaciones-app/src/zahory-mock/pages/wms/DevolucionesPage.jsx#DevolucionesPage"]'::jsonb,'895a94a0ee')
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('devoluciones_almacen',1,'inventario',NULL,NULL,'Registrar devolución ingresa la mercadería devuelta por un cliente o por una OT; queda en cuarentena para inspección.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('devoluciones_almacen',2,'inventario',NULL,NULL,'Revisa las cantidades de cada línea antes de registrar.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('devoluciones_almacen',3,'inventario',NULL,NULL,'Cerrar inspección termina la revisión; en una devolución de venta, Administración recibe el aviso para emitir la nota de crédito.');
INSERT INTO public.asistente_manual_fichas (clave,tipo,pantalla_key,titulo,resumen,fuentes,revision) VALUES ('diagnostico_tecnico','pantalla','diagnostico_tecnico','Diagnóstico Técnico','Evaluación técnica del equipo: hallazgos, trabajos, actividades, informe al cliente y hoja de costeo.','["operaciones-app/src/zahory-mock/pages/DiagnosticoTecnicoPage.jsx#DiagnosticoTecnicoPage"]'::jsonb,'e945eecb6f')
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('diagnostico_tecnico',1,'diagnostico_tecnico',NULL,NULL,'Elige si el diagnóstico es de Mantenimiento o de Fabricación y avanza por sus pasos con Siguiente; Abrir borrador retoma uno sin terminar.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('diagnostico_tecnico',2,'diagnostico_tecnico',NULL,NULL,'Registra lo encontrado con Agregar hallazgo y guárdalo con Guardar hallazgo.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('diagnostico_tecnico',3,'diagnostico_tecnico',NULL,NULL,'Arma los trabajos con Agregar trabajo y sus actividades con Agregar actividad. Un trabajo sin actividades ni tareas impide continuar: agrega una o quita el trabajo.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('diagnostico_tecnico',4,'diagnostico_tecnico',NULL,NULL,'Emitir diagnóstico lo cierra. Informe al cliente prepara el informe y Emitir informe lo emite.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('diagnostico_tecnico',5,'diagnostico_tecnico',NULL,NULL,'Generar hoja de costeo crea la Hoja de Costeo del diagnóstico; si ya existe, el botón la abre.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('diagnostico_tecnico',6,'diagnostico_tecnico',NULL,NULL,'Si la empresa operativa está en modo solo lectura no se pueden guardar diagnósticos.');
INSERT INTO public.asistente_manual_fichas (clave,tipo,pantalla_key,titulo,resumen,fuentes,revision) VALUES ('tenants','pantalla','tenants','Empresas / Tenants','Alta y mantenimiento de las empresas de la plataforma.','["src/pages_admin.jsx#Tenants"]'::jsonb,'859eca11fc')
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('tenants',1,'tenants',NULL,NULL,'Crea una empresa con Nuevo grupo y Crear grupo.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('tenants',2,'tenants',NULL,NULL,'Editar cambia sus datos y Eliminar la borra.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('tenants',3,'tenants',NULL,NULL,'Reporte plataforma descarga el reporte general.');
INSERT INTO public.asistente_manual_fichas (clave,tipo,pantalla_key,titulo,resumen,fuentes,revision) VALUES ('equipos_clientes','pantalla','os_cliente','Equipos de Clientes','Consulta de los equipos de los clientes y su historial de órdenes de servicio.','["src/pages_equipos_clientes.jsx#EquiposClientes"]'::jsonb,'c24d7b5762')
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('equipos_clientes',1,'os_cliente',NULL,NULL,'Es una pantalla de consulta: busca por código, equipo o cliente.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('equipos_clientes',2,'os_cliente',NULL,NULL,'Muestra los activos en custodia y el historial de OS Cliente de cada equipo.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('equipos_clientes',3,'os_cliente',NULL,NULL,'Necesita una empresa activa seleccionada para mostrar datos.');
INSERT INTO public.asistente_manual_fichas (clave,tipo,pantalla_key,titulo,resumen,fuentes,revision) VALUES ('resultados','pantalla','resultados','Estado Resultados','Estado de Resultados (ganancias y pérdidas) del mes: ingresos, costos, gastos, utilidad bruta, resultado operativo y neto, con sus márgenes y el detalle de cada línea.','["src/pages_fin.jsx#Resultados"]'::jsonb,'07b83d2f9d')
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('resultados',1,'resultados',NULL,NULL,'Elige el período y revisa el resultado por línea.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('resultados',2,'resultados',NULL,NULL,'Abre una línea para ver el detalle de sus gastos y ciérralo con Cerrar detalle.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('resultados',3,'resultados',NULL,NULL,'PDF descarga el reporte.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('resultados',4,'resultados',NULL,NULL,'Para qué sirve: muestra si la empresa ganó o perdió en un mes. Se lee de arriba abajo: Ingresos menos Costo de ventas da la Utilidad bruta; menos Gastos operativos da el Resultado operativo; luego se restan los Gastos financieros y la Depreciación hasta el Resultado neto. Cada resultado muestra su margen, que es su porcentaje sobre los ingresos.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('resultados',5,'resultados',NULL,NULL,'De dónde sale cada cifra: los ingresos son las facturas y boletas emitidas en el mes, sin IGV y sin las anuladas, más las ventas cobradas sin comprobante. Los costos y gastos salen de lo registrado en Compras y Gastos, cuentas por pagar, caja chica, la planilla del período y los costos de las órdenes de trabajo; los gastos financieros incluyen los intereses de los préstamos pagados en el mes.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('resultados',6,'resultados',NULL,NULL,'Si una cifra no cuadra, revisa primero la categoría del gasto: cada egreso cae en la línea que indica su categoría del Estado de Resultados, que se elige al registrarlo. Un gasto mal categorizado aparece en la línea equivocada; abre la línea para ver su detalle y ubicar el registro.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('resultados',7,'resultados',NULL,NULL,'Soles y dólares se muestran por separado y no se suman. Los filtros de centro de costo y de centro de beneficio permiten ver el resultado de un área o de una línea de negocio.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('resultados',8,'resultados',NULL,NULL,'En empresas con varias sociedades eliges ver una sociedad, compararlas lado a lado o el consolidado, que elimina las operaciones entre sociedades del grupo.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('resultados',9,'resultados',NULL,NULL,'Solo lo ven los roles con acceso a Estado de Resultados y con permiso para ver finanzas. También puedes pedírselo a Aria (por ejemplo «¿cuál fue la utilidad de octubre?»): usa este mismo cálculo, para la sociedad activa.');
INSERT INTO public.asistente_manual_fichas (clave,tipo,pantalla_key,titulo,resumen,fuentes,revision) VALUES ('etiquetas_almacen','pantalla','inventario','Etiquetas','Impresión de etiquetas del almacén.','["operaciones-app/src/zahory-mock/pages/wms/EtiquetasPage.jsx#EtiquetasPage"]'::jsonb,'3cbd212622')
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('etiquetas_almacen',1,'inventario',NULL,NULL,'Marca las etiquetas que necesitas; debes marcar al menos una.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('etiquetas_almacen',2,'inventario',NULL,NULL,'Descargar PDF genera el archivo para imprimir.');
INSERT INTO public.asistente_manual_fichas (clave,tipo,pantalla_key,titulo,resumen,fuentes,revision) VALUES ('evaluaciones_desempeno','pantalla','evaluaciones_desempeno','Evaluación de Desempeño','Plantillas de evaluación, autoevaluación, evaluación del jefe y resultados.','["src/pages_evaluaciones.jsx#EvaluacionesDesempeno"]'::jsonb,'fcea293bf5')
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('evaluaciones_desempeno',1,'evaluaciones_desempeno',NULL,NULL,'Quien administra crea la evaluación con Nueva plantilla: Agregar competencia y Agregar objetivo definen qué se evalúa, y Crear y activar plantilla la pone en marcha.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('evaluaciones_desempeno',2,'evaluaciones_desempeno',NULL,NULL,'Cada colaborador usa Autoevaluarme; puede Guardar borrador y, una vez enviada, ya no puede editarla.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('evaluaciones_desempeno',3,'evaluaciones_desempeno',NULL,NULL,'El jefe usa Evaluar; al enviar su evaluación tampoco puede editarla.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('evaluaciones_desempeno',4,'evaluaciones_desempeno',NULL,NULL,'Cerrar plantilla publica los resultados a los colaboradores, que los ven con Ver resultado.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('evaluaciones_desempeno',5,'evaluaciones_desempeno',NULL,NULL,'Exportar Excel descarga los resultados.');
INSERT INTO public.asistente_manual_fichas (clave,tipo,pantalla_key,titulo,resumen,fuentes,revision) VALUES ('facturacion','pantalla','facturacion','Facturación','Emite y consulta los comprobantes de venta, genera su cuenta por cobrar, registra cobros y autodetracciones, emite notas de crédito o débito y permite la carga masiva de facturas desde Excel.','["src/pages_fin.jsx#Facturacion"]'::jsonb,'e697a23316')
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('facturacion',1,'facturacion','facturacion','crear','Emite un comprobante desde una valorización, desde una venta o como comprobante directo eligiendo cliente y partidas. El número es obligatorio y se necesita al menos una partida; no se emite a un cliente con la cuenta bloqueada, y la pantalla pide confirmar un número repetido o un monto que excede el saldo de la OS.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('facturacion',2,'facturacion',NULL,NULL,'Desde el comprobante usa Generar CxC para crear la cuenta por cobrar; Ver CxC la abre si ya existe.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('facturacion',3,'facturacion',NULL,NULL,'Registrar cobro deja constancia del pago del cliente. Si el cliente no depositó la detracción, usa Registrar autodetracción con las cuentas y la constancia del depósito.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('facturacion',4,'facturacion',NULL,NULL,'Nota de Crédito y Nota de Débito emiten un ajuste vinculado al comprobante original. Una nota de crédito por devolución puede generar la cuenta por pagar al cliente si tienes permiso de cuentas por pagar.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('facturacion',5,'facturacion','facturacion','editar','Editar permite corregir datos del comprobante; Anular lo deja sin efecto con confirmación, y Restaurar lo devuelve a emitido.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('facturacion',6,'facturacion',NULL,NULL,'Ver OS y Ver valorización abren la orden de servicio o la valorización que originó la factura. Puedes adjuntar archivos al comprobante.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('facturacion',7,'facturacion','facturacion','crear','Para subir muchas facturas de clientes a la vez usa Carga masiva, en la lista de Facturación: descarga la plantilla de Excel, complétala con las facturas que tienen saldo pendiente y sube el archivo. La pantalla muestra una revisión antes de importar; cada fila crea la factura y su cuenta por cobrar, y crea al cliente si no existía. El mismo botón está en Cuentas por cobrar.');
INSERT INTO public.asistente_manual_fichas (clave,tipo,pantalla_key,titulo,resumen,fuentes,revision) VALUES ('cs_fidelizacion','pantalla','cs_fidelizacion','Fidelizacion y NPS','Encuestas de satisfacción y oportunidades que nacen de clientes satisfechos.','["src/pages_cs.jsx#CSFidelizacion"]'::jsonb,'7031d7e4c6')
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('cs_fidelizacion',1,'cs_fidelizacion',NULL,NULL,'Enviar encuesta manda la encuesta de satisfacción a un cliente.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('cs_fidelizacion',2,'cs_fidelizacion',NULL,NULL,'En los casos de éxito, Solicitar autorización al cliente pide su permiso para publicar el caso.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('cs_fidelizacion',3,'cs_fidelizacion',NULL,NULL,'Convertir a lead crea un prospecto en Leads.');
INSERT INTO public.asistente_manual_fichas (clave,tipo,pantalla_key,titulo,resumen,fuentes,revision) VALUES ('financiamiento','pantalla','financiamiento','Financiamiento y Deuda','Registra los préstamos, leasing y líneas de crédito de la empresa, agrupados por acreedor, con su cronograma, sus pagos y el reporte de deuda por moneda.','["src/pages_fin_deuda.jsx#FinanciamientoDeuda","src/pages/financiamiento/FinanciamientoListado.jsx#FinanciamientoListado","src/pages/financiamiento/FinanciamientoDetalle.jsx#FinanciamientoDetalle","src/pages/financiamiento/FinanciamientoAsistente.jsx#FinanciamientoAsistente","src/pages/financiamiento/FinanciamientoPago.jsx#FinanciamientoPago"]'::jsonb,'e70663fd74 28c6bf4edc 482865b9e7 13ebb51f4c 727b981b96')
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('financiamiento',1,'financiamiento',NULL,NULL,'Revisa arriba el capital pendiente, lo que vence este mes, los intereses del mes, lo vencido y los préstamos activos; los importes se muestran por moneda. Los préstamos se agrupan por acreedor: toca un acreedor para ver u ocultar sus préstamos, usa Vigentes, Cancelados o Todos y busca por acreedor, código o banco.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('financiamiento',2,'financiamiento','financiamiento','crear','Usa Nuevo préstamo para abrir el asistente de cuatro pasos. En Acreedor indicas quién presta (banco, persona o tercero, leasing) y, si aplica, la sociedad. En Condiciones eliges la modalidad: cuota fija, cuota decreciente, solo intereses con vencimiento o interés sobre saldo sin plazo (cada mes se paga un porcentaje del capital que se debe y el capital se amortiza cuando se puede); luego la moneda, el monto, la fecha, la tasa (TEA, TNA o TEM; en interés sobre saldo, la tasa mensual), el día de pago o de corte y, en las modalidades con cuotas, el plazo y los meses de gracia. En Desembolso eliges la cuenta de Tesorería donde entró el dinero y, si lo marcas, se registra el ingreso (con tipo de cambio si la cuenta está en otra moneda). En Revisión ves el resumen y las primeras cuotas antes de registrar.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('financiamiento',3,'financiamiento',NULL,NULL,'Toca un préstamo para abrir su detalle: arriba ves el saldo de capital, el próximo pago, el capital amortizado y los intereses pagados; en Movimientos, lo que falta pagar y lo ya pagado; en Cronograma, cada cuota o período con su estado; a la derecha, las condiciones del préstamo. Un préstamo vencido sin pagar aparece como Atrasado con los días de atraso.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('financiamiento',4,'financiamiento','financiamiento','editar','En el detalle usa Registrar pago, o toca una cuota o un período pendiente en Cronograma. En interés sobre saldo eliges Interés del mes, Abono a capital o Interés + capital; el interés del período se calcula sobre el saldo al corte y el capital abonado baja el interés de los meses siguientes. En las demás modalidades eliges Cuota pactada, Abono a capital (se recalculan las cuotas que faltan) o Cancelar el capital. Siempre eliges la cuenta de Tesorería y, si está en otra moneda, el tipo de cambio; el pago genera el egreso en Tesorería y, si incluye interés, el gasto financiero.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('financiamiento',5,'financiamiento','financiamiento','editar','En el detalle del préstamo usa Editar: se abre el mismo asistente con los datos cargados y puedes saltar a cualquier paso. Las cuotas pagadas no cambian y las pendientes se recalculan sobre el saldo que queda; si ya tiene pagos, no se puede cambiar la moneda ni pasar entre interés sobre saldo y cuotas. Si sales con cambios sin guardar, el sistema te pide confirmar.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('financiamiento',6,'financiamiento','financiamiento','anular','En el detalle del préstamo usa Eliminar. Tras la primera confirmación, una segunda alerta detalla todo lo que se borrará: cuotas, pagos, egresos de Tesorería por cuenta (cuyo saldo subirá) y gastos de intereses. Marca que lo entiendes y confirma; la acción no se puede deshacer.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('financiamiento',7,'financiamiento',NULL,NULL,'En la pestaña Documentos del detalle puedes descargar el contrato, el cronograma del banco u otros respaldos. Usa Reporte de deuda para ver el resumen por moneda, la deuda por acreedor y el calendario de pagos; desde ahí, Exportar reporte Excel descarga el reporte.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('financiamiento',8,'financiamiento','financiamiento','editar','En la pestaña Documentos usa Adjuntar para subir un PDF, imagen, Word, Excel o ZIP de hasta 20 MB, y Eliminar para quitar un documento. Al eliminar el préstamo también se borran sus documentos.');
INSERT INTO public.asistente_manual_fichas (clave,tipo,pantalla_key,titulo,resumen,fuentes,revision) VALUES ('flota_transporte','pantalla','transporte_comercial','Flota de transporte','Unidades, conductores y transportistas del transporte.','["operaciones-app/src/zahory-mock/pages/transporte/FlotaPage.jsx#FlotaPage"]'::jsonb,'56162d01ba')
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('flota_transporte',1,'transporte_comercial',NULL,NULL,'Nueva unidad, Nuevo conductor y Nuevo transportista registran cada uno; solo aparecen si tu rol puede crear.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('flota_transporte',2,'transporte_comercial',NULL,NULL,'La lista distingue lo propio de lo de terceros y avisa de documentos por vencer, como el certificado MTC o el brevete.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('flota_transporte',3,'transporte_comercial',NULL,NULL,'Revisar abre el registro que tiene una alerta.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('flota_transporte',4,'transporte_comercial',NULL,NULL,'Para qué sirve: aquí se mantienen los transportistas, las unidades y los conductores que se asignan a los viajes. Cada unidad lleva placa, tipo, certificado MTC con su vigencia y su capacidad en toneladas y en metros cúbicos; cada conductor, su brevete con categoría y vigencia.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('flota_transporte',5,'transporte_comercial',NULL,NULL,'Mantén al día las vigencias y la capacidad: un MTC o un brevete vencido impide despachar, y una capacidad sin registrar obliga a justificar una excepción en cada despacho.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('flota_transporte',6,'transporte_comercial',NULL,NULL,'Una unidad o un conductor que ya no se usa se inactiva, no se elimina, porque los viajes y las guías de remisión anteriores lo siguen referenciando. Lo que registres aquí también aparece al emitir guías de remisión.');
INSERT INTO public.asistente_manual_fichas (clave,tipo,pantalla_key,titulo,resumen,fuentes,revision) VALUES ('gemelo_digital','pantalla','inventario','Gemelo digital','Plano del almacén con sus posiciones, su stock y la ruta hacia cada ubicación.','["operaciones-app/src/zahory-mock/pages/gemelo/GemeloAlmacenPage.jsx#GemeloAlmacenPage"]'::jsonb,'94a9ef772e')
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('gemelo_digital',1,'inventario',NULL,NULL,'Muestra el plano del almacén con las posiciones que tienen stock y las que están bajo su punto de reorden. Vista 3D cambia a la vista en tres dimensiones.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('gemelo_digital',2,'inventario',NULL,NULL,'Ruta desde la puerta traza el camino hasta una posición.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('gemelo_digital',3,'inventario',NULL,NULL,'Editor de plano o Dibujar el plano permite armar el plano; al guardarlo se crean, actualizan o desactivan las ubicaciones.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('gemelo_digital',4,'inventario',NULL,NULL,'Ver con datos de ejemplo muestra un almacén de muestra y Volver a mis datos regresa al tuyo.');
INSERT INTO public.asistente_manual_fichas (clave,tipo,pantalla_key,titulo,resumen,fuentes,revision) VALUES ('gestion_garantias','pantalla','garantias_flota','Gestión de Garantías','Garantías de los equipos y sus reclamos.','["operaciones-app/src/zahory-mock/pages/flota/GarantiasFlotaPage.jsx#GarantiasFlotaPage"]'::jsonb,'0d2ed03b84')
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('gestion_garantias',1,'garantias_flota',NULL,NULL,'Registrar garantía anota una garantía; Renovar la extiende y Anular la deja sin efecto.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('gestion_garantias',2,'garantias_flota',NULL,NULL,'Sobre una garantía vigente, Liberar y Ejecutar registran su liberación o su ejecución, cada una con su motivo.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('gestion_garantias',3,'garantias_flota',NULL,NULL,'Registrar reclamo abre un reclamo y Actualizar estado lo hace avanzar; algunos estados exigen escribir la resolución.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('gestion_garantias',4,'garantias_flota',NULL,NULL,'Catálogo de tipos define los tipos de garantía: Nuevo tipo crea uno y Cargar tipos sugeridos trae una lista base.');
INSERT INTO public.asistente_manual_fichas (clave,tipo,pantalla_key,titulo,resumen,fuentes,revision) VALUES ('gestion_partes_taller','pantalla','partes','Gestión de partes de taller','Lista de partes diarios del taller para revisarlos: aprobar, observar, rechazar o reabrir un parte.','["operaciones-app/src/zahory-mock/pages/pages2_v2.jsx#GestionPartesTallerPage"]'::jsonb,'5ebecf6ab0')
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('gestion_partes_taller',1,'partes',NULL,NULL,'La lista muestra los partes diarios del taller.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('gestion_partes_taller',2,'partes',NULL,NULL,'Nuevo Parte Diario registra un parte y Ver detalle del Parte Diario lo abre.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('gestion_partes_taller',3,'partes',NULL,NULL,'Desde aquí el jefe de taller revisa los partes: los que están En revisión esperan su decisión. Aprobar confirma horas y avance; Observar y Rechazar exigen escribir el motivo, que el técnico verá para corregir.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('gestion_partes_taller',4,'partes',NULL,NULL,'Solo aprueba, observa, rechaza o reabre quien tiene el permiso de aprobar Partes. Si no ves esos botones, pide ese permiso en Roles y permisos.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('gestion_partes_taller',5,'partes',NULL,NULL,'Para saber qué OT no tienen parte en los últimos días, pregúntale a Aria por las OT sin parte, o filtra la bandeja de OT por las que están en ejecución y revisa su pestaña de partes.');
INSERT INTO public.asistente_manual_fichas (clave,tipo,pantalla_key,titulo,resumen,fuentes,revision) VALUES ('cs_health','pantalla','cs_health','Health Score','Puntaje de salud de cada cliente y planes de retención.','["src/pages_cs.jsx#CSHealthScore"]'::jsonb,'05155164d5')
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('cs_health',1,'cs_health',NULL,NULL,'La lista muestra el puntaje de salud de cada cliente; Ver detalle abre su desglose.');
