INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('cs_health',3,'cs_health',NULL,NULL,'Exportar descarga la lista.');
INSERT INTO public.asistente_manual_fichas (clave,tipo,pantalla_key,titulo,resumen,fuentes,revision) VALUES ('hoja_costeo_lista','pantalla','hoja_costeo','Hoja de Costeo (listado)','Listado de hojas de costeo, su revisión, aprobación y paso a cotización.','["src/pages_extra.jsx#HojaCosteo"]'::jsonb,'6a72bdfbb6')
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('hoja_costeo_lista',1,'hoja_costeo',NULL,NULL,'La lista muestra las hojas de costeo. El indicador Por cotizar filtra las aprobadas que aún no tienen cotización.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('hoja_costeo_lista',2,'hoja_costeo',NULL,NULL,'Abrir wizard lleva a la hoja en el asistente de costeo paso a paso.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('hoja_costeo_lista',3,'hoja_costeo',NULL,NULL,'Agregar línea suma una línea de costo y Guardar y Continuar conserva el avance.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('hoja_costeo_lista',4,'hoja_costeo',NULL,NULL,'Enviar a revision la manda a revisión, Aprobar Costeo la aprueba y Volver a borrador la devuelve para corregir.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('hoja_costeo_lista',5,'hoja_costeo',NULL,NULL,'Con la hoja aprobada, Generar Cotización crea la cotización. PDF descarga la hoja.');
INSERT INTO public.asistente_manual_fichas (clave,tipo,pantalla_key,titulo,resumen,fuentes,revision) VALUES ('hoja_costeo','pantalla','hoja_costeo','Hoja de Costeo','Costeo de un servicio: trabajos, materiales, gasto administrativo y margen, hasta su aprobación.','["src/pages_hoja_costeo_wizard.jsx#HojaCosteoWizard"]'::jsonb,'c181c07274')
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('hoja_costeo',1,'hoja_costeo',NULL,NULL,'Agrega los trabajos con Agregar trabajo: cada uno necesita tarea, cargo y horas mayores a cero. Si el cargo no tiene costo por hora, la pantalla lo avisa.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('hoja_costeo',2,'hoja_costeo',NULL,NULL,'Agrega los materiales con Agregar material indicando descripción, cantidad, unidad y un costo unitario mayor a cero.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('hoja_costeo',3,'hoja_costeo',NULL,NULL,'Define el porcentaje de gasto administrativo y el de margen; la suma de ambos debe ser menor a 100 %.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('hoja_costeo',4,'hoja_costeo',NULL,NULL,'Si la hoja nació de un diagnóstico, Actualizar desde el diagnóstico trae sus cambios.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('hoja_costeo',5,'hoja_costeo',NULL,NULL,'Usa Enviar a revisión; solo después se puede aprobar con Aprobar hoja. Crear nueva versión abre una versión nueva de la hoja y Generar cotización especial crea la cotización a partir de ella.');
INSERT INTO public.asistente_manual_fichas (clave,tipo,pantalla_key,titulo,resumen,fuentes,revision) VALUES ('hoja_ruta','pantalla','transporte_comercial','Hoja de Ruta','Programación diaria de las rutas de transporte y logística.','["operaciones-app/src/zahory-mock/pages/transporte/HojaDeRutaPage.jsx#HojaDeRutaPage"]'::jsonb,'fb0b722c0a')
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('hoja_ruta',1,'transporte_comercial',NULL,NULL,'Crea una ruta del día y agrégale pedidos con Agregar; Nueva ruta de logística crea una ruta propia de logística.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('hoja_ruta',2,'transporte_comercial',NULL,NULL,'Asignar define la unidad y el conductor de la ruta, y Editar la modifica.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('hoja_ruta',3,'transporte_comercial',NULL,NULL,'Hoja imprime la hoja de una ruta e Imprimir hojas del día las de todo el día.');
INSERT INTO public.asistente_manual_fichas (clave,tipo,pantalla_key,titulo,resumen,fuentes,revision) VALUES ('inicio_operaciones','pantalla','app_operativo','Inicio de Operaciones con Aria','Muestra tu día en Operaciones: resumen de Aria, indicadores, pendientes por resolver de taller, producción, almacén, transporte, flota y compras, avisos, tus OT y accesos rápidos.','["operaciones-app/src/InicioOperaciones.jsx#InicioOperaciones","src/inicio/Inicio.jsx#InicioBase","src/inicio/datos.js"]'::jsonb,'29fababf8c 6912d1acde ab320441f0')
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('inicio_operaciones',1,'app_operativo',NULL,NULL,'Al entrar a Operaciones se abre Inicio. Aria te saluda y resume tu día; Escuchar mi día lo lee en voz alta y Preséntame mi día recorre contigo los indicadores y pendientes.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('inicio_operaciones',2,'app_operativo',NULL,NULL,'Los indicadores muestran tus pendientes, las OT en ejecución, los partes por revisar y los repuestos por despachar. Cada uno aparece solo si tienes permiso para ver esa información.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('inicio_operaciones',3,'app_operativo',NULL,NULL,'En Por resolver elige Míos para ver lo asignado a ti o Mi área para ver todo lo de tu área, y filtra por Taller, Almacén, Producción, Transporte, Flota o Compras. El botón de cada pendiente abre la pantalla donde se resuelve; el reloj lo pospone hasta mañana.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('inicio_operaciones',4,'app_operativo',NULL,NULL,'La bandeja reúne partes diarios por revisar, órdenes de fabricación con compromiso vencido, viajes programados sin iniciar, reservas de repuestos por despachar, diagnósticos técnicos en borrador, SOLPE por aprobar, certificaciones de equipos que vencen en 30 días y OT en ejecución sin parte desde ayer.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('inicio_operaciones',5,'app_operativo',NULL,NULL,'En la columna derecha, Aria te avisa de certificaciones por vencer, viajes atrasados y OT con mucho tiempo en ejecución; Mi día lista tus OT programadas y en ejecución, y Accesos rápidos te lleva al Planner, a Nueva OT, a la Bandeja de OT y al Monitor de viajes.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('inicio_operaciones',6,'app_operativo',NULL,NULL,'Para preguntar o registrar algo usa el cuadro Pregúntale a Aria o el robot de Aria, que está disponible en todas las pantallas de Operaciones.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('inicio_operaciones',7,'app_operativo',NULL,NULL,'En celular y tablet el menú se abre con el botón ☰ de arriba a la izquierda; ahí también están las notificaciones, el modo oscuro y la salida.');
INSERT INTO public.asistente_manual_fichas (clave,tipo,pantalla_key,titulo,resumen,fuentes,revision) VALUES ('inventario_kardex','pantalla','inventario','Inventario & Kardex','Existencias por material y sus movimientos.','["operaciones-app/src/zahory-mock/pages/InventarioKardexPage.jsx#InventarioKardexPage"]'::jsonb,'8dad26c438')
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('inventario_kardex',1,'inventario',NULL,NULL,'La pestaña Stock muestra las existencias y Kardex los movimientos de cada material.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('inventario_kardex',2,'inventario',NULL,NULL,'Registrar entrada y Registrar salida registran movimientos manuales; Mover traslada stock y Ajustar stock corrige una diferencia.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('inventario_kardex',3,'inventario',NULL,NULL,'Liberar devuelve stock reservado al disponible.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('inventario_kardex',4,'inventario',NULL,NULL,'Antes de registrar un movimiento debes elegir una sociedad concreta.');
INSERT INTO public.asistente_manual_fichas (clave,tipo,pantalla_key,titulo,resumen,fuentes,revision) VALUES ('leads','pantalla','leads','Leads y Scoring','Registro y seguimiento de prospectos hasta convertirlos en clientes o descartarlos.','["src/pages_core.jsx#Leads"]'::jsonb,'5cd977019c')
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('leads',1,'leads',NULL,NULL,'Registra un prospecto con Nuevo lead. Puedes verlos en Lista o en Kanban y acotar con Filtros.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('leads',2,'leads',NULL,NULL,'Registrar Actividad deja constancia de cada contacto con el prospecto.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('leads',3,'leads',NULL,NULL,'Cuando el prospecto califica usa Convertir: el paso Convertir y crear cuenta crea su cuenta de cliente.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('leads',4,'leads',NULL,NULL,'Descartar saca al lead del seguimiento y Reactivar lo devuelve. Eliminar lo borra de forma definitiva y pide confirmación.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('leads',5,'leads',NULL,NULL,'Diferencia entre lead y cuenta: el lead es una persona interesada a la que se le da seguimiento hasta saber si hay negocio; la cuenta es la empresa (prospecto, cliente o partner) con la que se cotiza y factura. Un lead que califica se convierte y crea su cuenta.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('leads',6,'leads',NULL,NULL,'También puedes pedirle a Aria que registre el lead: dile el nombre del contacto y su empresa, y agrega lo que tengas (RUC o DNI, cargo, teléfono, correo, LinkedIn, origen, industria, necesidad, presupuesto, urgencia, campaña). Aria avisa si ya existe un lead o una cuenta con ese documento o correo, muestra una tarjeta con los datos y nada se graba hasta pulsar Confirmar. Requiere permiso de crear en Leads.');
INSERT INTO public.asistente_manual_fichas (clave,tipo,pantalla_key,titulo,resumen,fuentes,revision) VALUES ('liquidacion_dmr','pantalla','liquidacion_flota','Liquidación & DMR','Partes diarios de los equipos alquilados y su liquidación mensual.','["operaciones-app/src/zahory-mock/pages/flota/LiquidacionFlotaPage.jsx#LiquidacionFlotaPage"]'::jsonb,'a3c150a93e')
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('liquidacion_dmr',1,'liquidacion_flota',NULL,NULL,'En Partes diarios registra cada día con Nuevo parte: horas operadas, horómetro y paradas, que se agregan con Agregar parada. Guardar parte lo conserva y Anular parte lo deja sin efecto.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('liquidacion_dmr',2,'liquidacion_flota',NULL,NULL,'En Liquidaciones usa Liquidar un mes y Crear liquidación; la liquidación queda en borrador. Recalcular la actualiza con los partes.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('liquidacion_dmr',3,'liquidacion_flota',NULL,NULL,'Enviar a revisión la manda a aprobación; quien revisa usa Aprobar o Devolver.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('liquidacion_dmr',4,'liquidacion_flota',NULL,NULL,'Para qué sirve: aquí se controla cuánto operó cada equipo alquilado y se calcula lo que se le cobra al cliente en el mes. La fuente de las horas es el parte diario: uno por equipo y por día, con horómetro de inicio y de fin, horas programadas, paradas con su causa y el nombre de quien da el visto bueno por el cliente. Un día sin trabajo se registra como Sin operación.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('liquidacion_dmr',5,'liquidacion_flota',NULL,NULL,'El horómetro no puede retroceder respecto a los partes del día anterior o siguiente, y la pantalla avisa si las horas operadas superan las disponibles: revisa el horómetro o las paradas. Cada parte actualiza el horómetro actual del equipo.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('liquidacion_dmr',6,'liquidacion_flota',NULL,NULL,'La causa de cada parada define a quién se atribuye: al proveedor, al cliente o a nadie. Solo las paradas del proveedor bajan la disponibilidad. El DMR es la disponibilidad: horas programadas menos paradas del proveedor, dividido entre horas programadas.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('liquidacion_dmr',7,'liquidacion_flota',NULL,NULL,'Qué se cobra: las horas facturables son el mayor valor entre las horas operadas y el mínimo del contrato, prorrateado por los días del mes que el equipo estuvo en contrato. Lo operado se cobra con la tarifa vigente de cada día. Si el DMR quedó por debajo de la meta del contrato, se descuenta una penalidad proporcional a esa diferencia, por equipo.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('liquidacion_dmr',8,'liquidacion_flota',NULL,NULL,'La liquidación pasa por Borrador, En revisión y Aprobada. No se puede enviar a revisión si faltan partes de algún día ni antes de que termine el mes. Quien revisa usa Aprobar o Devolver con un motivo. Mientras la liquidación está en revisión o aprobada, los partes de ese mes quedan de solo lectura.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('liquidacion_dmr',9,'liquidacion_flota',NULL,NULL,'Si no puedes editar un parte, casi siempre es porque el mes ya está liquidado. Si no puedes enviar la liquidación, revisa en Partes diarios qué días faltan. Aprobar y anular liquidaciones corresponde a los administradores de la empresa.');
INSERT INTO public.asistente_manual_fichas (clave,tipo,pantalla_key,titulo,resumen,fuentes,revision) VALUES ('liquidaciones_cese','pantalla','liquidaciones_cese','Liquidación por Cese','Cálculo y confirmación de la liquidación de un trabajador que cesa.','["src/pages_liquidaciones.jsx#LiquidacionesCese"]'::jsonb,'8409cfda1b')
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('liquidaciones_cese',1,'liquidaciones_cese',NULL,NULL,'Inicia con Nueva liquidación: elige al colaborador, el tipo de cese y la fecha de cese, que no puede ser anterior a su fecha de ingreso. El colaborador debe tener fecha de ingreso en su ficha.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('liquidaciones_cese',2,'liquidaciones_cese',NULL,NULL,'Si el cese es por falta grave debes indicar el motivo específico. Recalcular vuelve a calcular los importes.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('liquidaciones_cese',3,'liquidaciones_cese',NULL,NULL,'Para confirmar marca la casilla de confirmación y usa Confirmar liquidación: se genera la cuenta por pagar y se bloquea el acceso del trabajador al sistema. Ver CxP generada abre esa cuenta.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('liquidaciones_cese',4,'liquidaciones_cese',NULL,NULL,'Anular deja sin efecto una liquidación; el motivo es obligatorio.');
INSERT INTO public.asistente_manual_fichas (clave,tipo,pantalla_key,titulo,resumen,fuentes,revision) VALUES ('lugares_transporte','pantalla','transporte_comercial','Lugares','Lugares de carga y de entrega del transporte.','["operaciones-app/src/zahory-mock/pages/transporte/LugaresPage.jsx#LugaresPage"]'::jsonb,'ca6f642574')
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('lugares_transporte',1,'transporte_comercial',NULL,NULL,'Nuevo lugar registra un punto de carga o de entrega.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('lugares_transporte',2,'transporte_comercial',NULL,NULL,'Un lugar que ya no se usa se inactiva.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('lugares_transporte',3,'transporte_comercial',NULL,NULL,'Para qué sirve: los lugares son los puntos de carga y de entrega que usan las rutas y las paradas de los viajes: almacenes, plantas, obras, minas, puertos o locales de clientes. Un lugar puede ser general o pertenecer a un cliente.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('lugares_transporte',4,'transporte_comercial',NULL,NULL,'La ubicación es obligatoria para guardar: se marca con un clic en el mapa o pegando un enlace de Google Maps. También se registran el contacto, el horario de atención, los requisitos de ingreso y las restricciones, que después ve quien programa y quien conduce.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('lugares_transporte',5,'transporte_comercial',NULL,NULL,'El lugar muestra en Usado en las rutas que lo emplean. No se puede repetir el nombre de un lugar. Un lugar que ya no se usa se inactiva.');
INSERT INTO public.asistente_manual_fichas (clave,tipo,pantalla_key,titulo,resumen,fuentes,revision) VALUES ('maestro_rutas','pantalla','transporte_comercial','Maestro de Rutas','Rutas de transporte.','["operaciones-app/src/zahory-mock/pages/transporte/MaestroRutasPage.jsx#MaestroRutasPage"]'::jsonb,'aaec02a4ba')
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('maestro_rutas',1,'transporte_comercial',NULL,NULL,'Nueva ruta registra una ruta.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('maestro_rutas',2,'transporte_comercial',NULL,NULL,'Editar cambia sus datos.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('maestro_rutas',3,'transporte_comercial',NULL,NULL,'Para qué sirve: una ruta es un trayecto de un lugar a otro que la empresa atiende con frecuencia; sobre ella se definen las tarifas y se crean los viajes. Nueva ruta abre una sola vista con el mapa: eliges origen y destino del maestro de Lugares y el sistema propone el nombre, un código que empieza con R, la distancia y la duración.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('maestro_rutas',4,'transporte_comercial',NULL,NULL,'La distancia y la duración son estimadas a partir de la ubicación de los dos lugares y se pueden corregir a mano. En la misma vista puedes definir la tarifa base de la ruta y crear también la ruta de regreso: en ese caso el botón dice Guardar 2 rutas.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('maestro_rutas',5,'transporte_comercial',NULL,NULL,'Si ya existe una ruta entre esos dos lugares, la pantalla lo avisa: Ver ruta abre la existente y Crear igual sigue adelante. Puedes cambiar el trayecto de una ruta que ya tiene viajes; los viajes anteriores conservan sus datos.');
INSERT INTO public.asistente_manual_fichas (clave,tipo,pantalla_key,titulo,resumen,fuentes,revision) VALUES ('maestros','pantalla','maestros','Maestros Base','Datos comunes de la empresa: centros de costo y de beneficio, materiales, familias y otros catálogos.','["src/pages_admin.jsx#Maestros"]'::jsonb,'50855bc116')
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('maestros',1,'maestros',NULL,NULL,'Aquí se mantienen los centros de costo (Agregar CECO), los centros de beneficio (Agregar CEBE), los materiales y sus familias.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('maestros',2,'maestros',NULL,NULL,'Para cargas grandes usa Descargar plantilla e Importar Excel; la pantalla muestra una vista previa antes de confirmar la importación.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('maestros',3,'maestros',NULL,NULL,'Un registro en uso no se borra: se desactiva. Si un CECO tiene órdenes de trabajo activas, la pantalla avisa que seguirán vinculadas aunque ya no aparezca para nuevas asignaciones.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('maestros',4,'maestros',NULL,NULL,'Fusionar une dos registros duplicados en uno solo.');
INSERT INTO public.asistente_manual_fichas (clave,tipo,pantalla_key,titulo,resumen,fuentes,revision) VALUES ('marketing','pantalla','marketing','Marketing Automation','Campañas de marketing, su audiencia y su activación.','["src/pages_core.jsx#Marketing"]'::jsonb,'7bd4a6c570')
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('marketing',1,'marketing',NULL,NULL,'Crea una campaña con Nueva campaña y Crear campaña. Editar cambia sus datos.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('marketing',2,'marketing',NULL,NULL,'Audiencia muestra a quién va dirigida.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('marketing',3,'marketing',NULL,NULL,'Activar la pone en marcha, Pausar la detiene y Reactivar la retoma.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('marketing',4,'marketing',NULL,NULL,'Eliminar campana la borra y no se puede deshacer.');
INSERT INTO public.asistente_manual_fichas (clave,tipo,pantalla_key,titulo,resumen,fuentes,revision) VALUES ('mi_portal','pantalla','mi_portal','Mi portal','Espacio personal del trabajador: boletas, documentos, contrato y solicitudes.','["src/pages_mi_portal.jsx#MiPortal"]'::jsonb,'8a66482254')
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('mi_portal',1,'mi_portal',NULL,NULL,'Para abrir tus boletas primero debes registrar el consentimiento de entrega electrónica; la pantalla te lleva a Firma y consentimiento.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('mi_portal',2,'mi_portal',NULL,NULL,'Abrir muestra una boleta y Me doy por enterado registra tu acuse.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('mi_portal',3,'mi_portal',NULL,NULL,'Pedir vacaciones, Pedir permiso, Solicitar HE y Solicitar constancia envían tus solicitudes; las horas extra exigen completar todos los campos obligatorios.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('mi_portal',4,'mi_portal',NULL,NULL,'Subir firmado carga tu contrato o documento firmado, que queda en revisión por RRHH. El archivo no puede estar vacío ni pasar de 20 MB.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('mi_portal',5,'mi_portal',NULL,NULL,'Para pedir un cambio en tus datos, ingresa el nuevo valor propuesto y usa Enviar a RRHH.');
INSERT INTO public.asistente_manual_fichas (clave,tipo,pantalla_key,titulo,resumen,fuentes,revision) VALUES ('minas_proyectos','pantalla','inventario','Minas y proyectos','Minas, sus proyectos y sus almacenes periféricos.','["operaciones-app/src/zahory-mock/pages/MinasProyectosPage.jsx#MinasProyectosPage"]'::jsonb,'67b307ee29')
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('minas_proyectos',1,'inventario',NULL,NULL,'Nueva mina registra una mina y Editar mina cambia sus datos; ambos dependen de lo que tu rol puede crear o editar.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('minas_proyectos',2,'inventario',NULL,NULL,'Nuevo proyecto crea un proyecto en la mina y Asignar proyecto existente vincula uno ya creado.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('minas_proyectos',3,'inventario',NULL,NULL,'Agregar almacén periférico crea el almacén de la mina.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('minas_proyectos',4,'inventario',NULL,NULL,'Devolver a central regresa el material del almacén periférico al almacén central.');
INSERT INTO public.asistente_manual_fichas (clave,tipo,pantalla_key,titulo,resumen,fuentes,revision) VALUES ('mis_ots_dia','pantalla','ot','Mis OTs del día','Muestra al técnico las OT asignadas para hoy y le permite registrar su parte diario.','["operaciones-app/src/zahory-mock/pages/MisOTsPage.jsx#MisOTsPage"]'::jsonb,'aa0aa52182')
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('mis_ots_dia',1,'ot',NULL,NULL,'Verás las OT que tienes asignadas para el día con su estado.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('mis_ots_dia',2,'ot',NULL,NULL,'Registrar parte abre el parte diario de esa OT. Registrar parte sin OT sirve para trabajo que todavía no tiene orden.');
INSERT INTO public.asistente_manual_fichas (clave,tipo,pantalla_key,titulo,resumen,fuentes,revision) VALUES ('monitor_viajes','pantalla','transporte_comercial','Monitor de viajes','Seguimiento de los viajes de transporte comercial: estado, filtros, asignación de unidad y conductor, y creación de órdenes de viaje.','["operaciones-app/src/zahory-mock/pages/transporte/MonitorViajesPage.jsx#MonitorViajesPage"]'::jsonb,'89fb9d5ef7')
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('monitor_viajes',1,'transporte_comercial',NULL,NULL,'El tablero agrupa los viajes por estado (programado, despachado y siguientes) y marca los atrasados, los que salen hoy, los que no tienen unidad asignada y los que tienen incidentes. Usa los filtros y Limpiar filtros para volver a verlos todos.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('monitor_viajes',2,'transporte_comercial',NULL,NULL,'Nueva orden de viaje abre el registro de un viaje nuevo con su ruta y cliente.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('monitor_viajes',3,'transporte_comercial',NULL,NULL,'Cuando hay viajes atrasados o que salen hoy sin unidad, aparece un aviso con Asignar y despachar, que abre el viaje para asignar unidad y conductor.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('monitor_viajes',4,'transporte_comercial',NULL,NULL,'Abre un viaje para ver su detalle y su hoja de ruta. Exportar descarga la lista.');
INSERT INTO public.asistente_manual_fichas (clave,tipo,pantalla_key,titulo,resumen,fuentes,revision) VALUES ('movil_asistencia','pantalla','campo','Móvil — Asistencia','Marcación de entrada, refrigerio y salida desde el celular.','["src/pages_mobile.jsx#AsistenciaMobileView"]'::jsonb,'823e538216')
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('movil_asistencia',1,'campo',NULL,NULL,'Entrada y Salida registran tu marcación con la ubicación del celular; debes dar permiso de ubicación.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('movil_asistencia',2,'campo',NULL,NULL,'Sin señal, la marcación se guarda en el celular y se sincroniza sola al recuperar la conexión.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('movil_asistencia',3,'campo',NULL,NULL,'Si marcas la salida con un refrigerio sin cerrar, la pantalla pide confirmación.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('movil_asistencia',4,'campo',NULL,NULL,'Si estás fuera de la geocerca puedes enviar un reporte con Enviar reporte, que queda para revisión.');
INSERT INTO public.asistente_manual_fichas (clave,tipo,pantalla_key,titulo,resumen,fuentes,revision) VALUES ('movil_compras','pantalla','campo','Móvil — Compras','Registro de un gasto con la foto del comprobante desde el celular.','["src/pages_mobile.jsx#ComprasView"]'::jsonb,'51d45cfa58')
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('movil_compras',1,'campo',NULL,NULL,'Adjuntar foto del comprobante o Tomar captura la factura; también puedes usar Ingresar datos manualmente.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('movil_compras',2,'campo',NULL,NULL,'El total de las líneas debe coincidir con el de la factura; Recalcular lo actualiza.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('movil_compras',3,'campo',NULL,NULL,'Si la factura tiene más de 30 días, la pantalla pide confirmar antes de continuar.');
INSERT INTO public.asistente_manual_fichas (clave,tipo,pantalla_key,titulo,resumen,fuentes,revision) VALUES ('movil_gerencia','pantalla','campo','Móvil — Gerencia','Aprobaciones pendientes desde el celular.','["src/pages_mobile.jsx#GerenciaView"]'::jsonb,'a2308d7303')
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('movil_gerencia',1,'campo',NULL,NULL,'Aprobar pendientes muestra lo que espera tu decisión.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('movil_gerencia',2,'campo',NULL,NULL,'Aprobar o Rechazar resuelve cada pendiente y pide confirmación; el comentario es obligatorio.');
INSERT INTO public.asistente_manual_fichas (clave,tipo,pantalla_key,titulo,resumen,fuentes,revision) VALUES ('movil_logistica','pantalla','campo','Móvil — Logística','Rutas y viajes del conductor desde el celular.','["src/pages_mobile.jsx#LogisticaView"]'::jsonb,'4d6a4cf5e2')
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('movil_logistica',1,'campo',NULL,NULL,'Muestra tus rutas y viajes del día; Abrir viaje entra a uno.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('movil_logistica',2,'campo',NULL,NULL,'Antes de salir se hace la inspección de la unidad. Si hay puntos críticos debes esperar la autorización del despachador.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('movil_logistica',3,'campo',NULL,NULL,'En el viaje registras el kilometraje de salida y de llegada, los gastos y los incidentes; un incidente deja el viaje «con incidente» y el despachador lo ve en el Monitor.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('movil_logistica',4,'campo',NULL,NULL,'Omitir parada exige escribir el motivo, y el pedido vuelve a «Por enviar a ruta».');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('movil_logistica',5,'campo',NULL,NULL,'Al terminar se registra la conformidad del cliente con la hora y el GPS, que sirven para la facturación.');
INSERT INTO public.asistente_manual_fichas (clave,tipo,pantalla_key,titulo,resumen,fuentes,revision) VALUES ('movil_mi_portal','pantalla','campo','Móvil — Mi portal','Espacio personal del trabajador en el celular: documentos, contrato y solicitudes.','["src/pages_mobile.jsx#MiEspacioMobileView"]'::jsonb,'1f9e81e467')
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('movil_mi_portal',1,'campo',NULL,NULL,'Marcar entrada/salida lleva a la asistencia.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('movil_mi_portal',2,'campo',NULL,NULL,'Solicitudes, Nueva licencia, Solicitar HE y Solicitar constancia envían tus pedidos; debes completar los campos obligatorios.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('movil_mi_portal',3,'campo',NULL,NULL,'Subir contrato firmado carga tu contrato, que queda en revisión por RRHH. El archivo no puede estar vacío ni pasar de 20 MB.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('movil_mi_portal',4,'campo',NULL,NULL,'Si no aparece tu ficha de personal, contacta a RRHH.');
INSERT INTO public.asistente_manual_fichas (clave,tipo,pantalla_key,titulo,resumen,fuentes,revision) VALUES ('movil_supervisor','pantalla','campo','Móvil — Supervisor','Revisión de partes y solicitudes desde el celular.','["src/pages_mobile.jsx#SupervisorView"]'::jsonb,'a634a954c2')
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('movil_supervisor',1,'campo',NULL,NULL,'Aprobar, Observar o Rechazar resuelve cada pendiente y pide confirmación; el comentario es obligatorio.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('movil_supervisor',2,'campo',NULL,NULL,'Solicitudes RRHH muestra las solicitudes del personal por atender.');
INSERT INTO public.asistente_manual_fichas (clave,tipo,pantalla_key,titulo,resumen,fuentes,revision) VALUES ('movil_tareo','pantalla','campo','Móvil — Tareo','Registro de horas del día desde el celular.','["src/pages_mobile.jsx#AdministrativoView"]'::jsonb,'098b9894da')
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('movil_tareo',1,'campo',NULL,NULL,'Registrar anota tus horas: las horas y la descripción son obligatorias.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('movil_tareo',2,'campo',NULL,NULL,'Enviar registro del día manda tu jornada y pide confirmación.');
INSERT INTO public.asistente_manual_fichas (clave,tipo,pantalla_key,titulo,resumen,fuentes,revision) VALUES ('movil_tecnico','pantalla','campo','Móvil — Técnico','Trabajo del técnico en campo desde el celular.','["src/pages_mobile.jsx#TecnicoView"]'::jsonb,'3940dcb878')
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('movil_tecnico',1,'campo',NULL,NULL,'Iniciar esta tarea comienza una tarea y Continuar trabajando en esta tarea la retoma.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('movil_tecnico',2,'campo',NULL,NULL,'Escanear Material registra el material usado.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('movil_tecnico',3,'campo',NULL,NULL,'Parte registra el parte del día y Enviar al supervisor lo manda a revisión.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('movil_tecnico',4,'campo',NULL,NULL,'Firmar y Completar cierra el trabajo con firma.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('movil_tecnico',5,'campo',NULL,NULL,'SSOMA abre la sección de seguridad y SOS sirve para pedir ayuda.');
INSERT INTO public.asistente_manual_fichas (clave,tipo,pantalla_key,titulo,resumen,fuentes,revision) VALUES ('movil_vendedor','pantalla','campo','Móvil — Vendedor','Leads, oportunidades, agenda y comisión del vendedor desde el celular.','["src/pages_mobile.jsx#VendedorView"]'::jsonb,'30d5a9d29f')
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('movil_vendedor',1,'campo',NULL,NULL,'Agregar lead registra un prospecto a mano; Crear lead con foto de tarjeta extrae los datos de la tarjeta automáticamente.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('movil_vendedor',2,'campo',NULL,NULL,'Convertir pasa un lead a oportunidad y Descartar lo saca del seguimiento.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('movil_vendedor',3,'campo',NULL,NULL,'Registrar Actividad anota un contacto y Planificar en agenda agenda la próxima reunión o visita. Llamar marca al teléfono del contacto.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('movil_vendedor',4,'campo',NULL,NULL,'Una oportunidad se marca como Perdida con Confirmar perdida.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('movil_vendedor',5,'campo',NULL,NULL,'En Comisión, Proponer acuerdo especial envía tu propuesta con Enviar a aprobación; Retirar solicitud la retira.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('movil_vendedor',6,'campo',NULL,NULL,'Sincronizar ahora actualiza los datos cuando hay conexión.');
INSERT INTO public.asistente_manual_fichas (clave,tipo,pantalla_key,titulo,resumen,fuentes,revision) VALUES ('nomina','pantalla','nomina','Nomina','Cálculo, revisión y cierre de la planilla de cada período: cómo procesar la planilla del mes o de la quincena.','["src/pages_ops.jsx#Nomina"]'::jsonb,'21d2972451')
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('nomina',1,'nomina',NULL,NULL,'Crea el período con Nuevo período y calcula la planilla con Procesar. Si pagas por quincenas, debes procesar la primera quincena antes de la segunda.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('nomina',2,'nomina',NULL,NULL,'Nuevo ingreso y Nuevo descuento registran conceptos extraordinarios con su descripción y su monto.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('nomina',3,'nomina',NULL,NULL,'Boleta abre la boleta de un trabajador y Descargar boleta PDF la descarga. Descargar Excel PLAME genera el archivo del período.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('nomina',4,'nomina',NULL,NULL,'Cierra el período con Confirmar cierre: debe estar procesado y, cuando corresponde gratificación, antes hay que confirmar la gratificación real. Al cerrar se generan los egresos de la planilla.');
INSERT INTO public.asistente_manual_fichas (clave,tipo,pantalla_key,titulo,resumen,fuentes,revision) VALUES ('notificaciones_config','pantalla','parametros','Notificaciones','Avisos automáticos de la empresa (contratos y documentos por vencer, tardanzas, OT y partes): a quién llegan, por campana, correo o WhatsApp, y su historial de envíos.','["src/pages_notificaciones_config.jsx#NotificacionesConfig"]'::jsonb,'37041730c7')
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('notificaciones_config',1,'parametros',NULL,NULL,'Debes tener seleccionada una empresa para configurar sus notificaciones.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('notificaciones_config',2,'parametros',NULL,NULL,'En Eventos activas cada aviso y defines a quién llega; Agregar aviso suma uno nuevo y Guardar cambios conserva la configuración.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('notificaciones_config',3,'parametros',NULL,NULL,'Probar ahora ejecuta el aviso en el momento para comprobar que funciona.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('notificaciones_config',4,'parametros',NULL,NULL,'Historial de envíos muestra lo que ya se envió.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('notificaciones_config',5,'parametros',NULL,NULL,'Avisos disponibles: contratos por vencer (por defecto a 30, 15 y 7 días; hasta 5 avisos entre 1 y 180 días), contratos vencidos sin renovar, documentos por vencer, resumen diario de tardanzas (más de 10 minutos por defecto), OT creadas en el día y partes no llenados. Todos nacen apagados: cada empresa activa los que quiere.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('notificaciones_config',6,'parametros',NULL,NULL,'Cada aviso define a quién llega (RRHH o administración, jefe directo, colaborador, Operaciones) y por qué canal: campana del sistema, correo o WhatsApp. Se pueden sumar hasta 10 correos y 10 teléfonos adicionales por aviso, y elegir qué roles cuentan como RRHH u Operaciones.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('notificaciones_config',7,'parametros',NULL,NULL,'La campana avisa al instante. El correo llega como una lista diaria por destinatario, alrededor de las 7:20 a. m. El resumen de tardanzas admite una hora de envío propia para recibir las del mismo día.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('notificaciones_config',8,'parametros',NULL,NULL,'Si alguien no recibe un aviso, revisa: que el aviso esté activo, que su rol esté entre los destinatarios, que tenga correo real en su usuario (o teléfono para WhatsApp) y, para el jefe directo, que el organigrama indique a quién reporta. Historial de envíos muestra qué salió, a quién y si falló.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('notificaciones_config',9,'parametros',NULL,NULL,'Un contrato con renovación aprobada que empalma no genera aviso de vencimiento, y las adendas tampoco.');
INSERT INTO public.asistente_manual_fichas (clave,tipo,pantalla_key,titulo,resumen,fuentes,revision) VALUES ('nueva_of','pantalla','of','Nueva OF','Creación de una orden de fabricación a partir de la orden de servicio del cliente.','["operaciones-app/src/zahory-mock/pages/of/CrearOFPage.jsx#CrearOFPage"]'::jsonb,'4ff52824a1')
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('nueva_of',1,'of',NULL,NULL,'La OF se crea a partir de la OS del cliente; Cambiar permite elegir otra.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('nueva_of',2,'of',NULL,NULL,'La pantalla indica si la OS tiene Hoja de Costeo, que sirve de base a la orden.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('nueva_of',3,'of',NULL,NULL,'Crear OF registra la orden. Si la OS ya tiene una, el botón dice Crear OF adicional.');
INSERT INTO public.asistente_manual_fichas (clave,tipo,pantalla_key,titulo,resumen,fuentes,revision) VALUES ('nueva_ot','pantalla','ot','Nueva OT','Asistente de cinco pasos para crear una orden de trabajo: contexto, lugar, matriz DBS, responsable y revisión.','["operaciones-app/src/zahory-mock/pages/CrearOTPage.jsx#CrearOTPage"]'::jsonb,'cb7f933511')
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('nueva_ot',1,'ot',NULL,NULL,'Paso 1, Contexto: elige la línea de negocio y el objeto de costo raíz: un contrato de alquiler activo, una OS de cliente o un equipo interno de la plataforma.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('nueva_ot',2,'ot',NULL,NULL,'Paso 2, Lugar: indica dónde se ejecuta el trabajo. El horómetro actual del equipo es obligatorio en OTs de campo, bajo contrato o con equipo asociado.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('nueva_ot',3,'ot',NULL,NULL,'Paso 3, Matriz DBS: clasifica el cargo financiero (facturable al cliente, absorbido, recuperable del fabricante o retrabajo propio, que exige motivo) y arma segmentos con operaciones, mano de obra, repuestos y terceros. La pantalla suma los costos estimados.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('nueva_ot',4,'ot',NULL,NULL,'Paso 4, Responsable: asigna el técnico responsable, las fechas y el centro de costo; si la OS o el equipo no lo definen, debes elegirlo a mano.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('nueva_ot',5,'ot',NULL,NULL,'Paso 5, Revisión: revisa el resumen, agrega la descripción técnica y usa Crear OT. Desde el asistente también puedes vincular hallazgos y backlog del diagnóstico.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('nueva_ot',6,'ot',NULL,NULL,'Toda OT declara de dónde sale su costo: un contrato de alquiler, una OS de cliente o un equipo propio. Eso define a qué centro de costo se carga y si el trabajo se factura. Sin ese dato el asistente no deja avanzar.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('nueva_ot',7,'ot',NULL,NULL,'Si la OT viene de una OS de cliente, hereda cliente y centro de costo. Si viene de un contrato de alquiler, queda ligada al contrato y su costo cuenta en la rentabilidad del alquiler.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('nueva_ot',8,'ot',NULL,NULL,'Retrabajo propio es un trabajo que se repite por error interno: no se cobra y exige motivo. Recuperable del fabricante es garantía del proveedor. Absorbido es un costo que la empresa asume sin cobrar.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('nueva_ot',9,'ot',NULL,NULL,'Al programar la OT, los repuestos de sus segmentos se reservan en el almacén: bajan del disponible pero no salen hasta el despacho. Si falta stock se pide por SOLPE.');
INSERT INTO public.asistente_manual_fichas (clave,tipo,pantalla_key,titulo,resumen,fuentes,revision) VALUES ('cs_onboarding','pantalla','cs_onboarding','Onboarding','Seguimiento de la puesta en marcha de los clientes nuevos.','["src/pages_cs.jsx#CSOnboarding"]'::jsonb,'6a67ec3d29')
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('cs_onboarding',1,'cs_onboarding',NULL,NULL,'Inicia la puesta en marcha de un cliente con Nuevo onboarding.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('cs_onboarding',2,'cs_onboarding',NULL,NULL,'Ver detalle muestra su avance.');
INSERT INTO public.asistente_manual_fichas (clave,tipo,pantalla_key,titulo,resumen,fuentes,revision) VALUES ('orden_viaje','pantalla','transporte_comercial','Nueva orden de viaje','Registro de un viaje de transporte, desde una orden de servicio o como viaje directo.','["operaciones-app/src/zahory-mock/pages/transporte/OrdenViajePage.jsx#OrdenViajePage"]'::jsonb,'aa6bbffce0')
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('orden_viaje',1,'transporte_comercial',NULL,NULL,'Elige si el viaje parte Desde OS del cliente o es un Viaje directo, y avanza con Siguiente.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('orden_viaje',2,'transporte_comercial',NULL,NULL,'Guardar borrador conserva el viaje sin programarlo; Guardar y programar lo deja programado.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('orden_viaje',3,'transporte_comercial',NULL,NULL,'Si sales con cambios sin guardar, la pantalla pregunta si quieres Salir o Seguir editando.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('orden_viaje',4,'transporte_comercial',NULL,NULL,'Para qué sirve: la orden de viaje es el encargo de transporte: qué se lleva, de dónde a dónde, para qué cliente, cuándo y a qué precio. Puede nacer de una OS del cliente o registrarse como viaje directo. Cada viaje recibe un código que empieza con TV.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('orden_viaje',5,'transporte_comercial',NULL,NULL,'El asistente tiene cuatro pasos y un resumen al costado. El origen, el destino y las paradas intermedias se eligen del maestro de Lugares; si un lugar no existe se puede crear ahí mismo. Un viaje puede tener varias paradas.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('orden_viaje',6,'transporte_comercial',NULL,NULL,'El precio se resuelve solo: si el cliente tiene una tarifa propia para esa ruta se usa esa, y si no, la tarifa base de la ruta. También puedes escribir un precio manual.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('orden_viaje',7,'transporte_comercial',NULL,NULL,'Guardar borrador deja el viaje incompleto para seguir después. Guardar y programar lo deja programado y listo para asignarle unidad y conductor. Un viaje programado ya no vuelve a borrador: se corrige con Guardar cambios.');
INSERT INTO public.asistente_manual_fichas (clave,tipo,pantalla_key,titulo,resumen,fuentes,revision) VALUES ('ordenes_compra','pantalla','ordenes_compra','Órdenes de compra','Crea y emite órdenes de compra de bienes, registra anticipos, tránsito y recepción, y enlaza la factura del proveedor como cuenta por pagar.','["src/pages_ops.jsx#OrdenesCompra"]'::jsonb,'0fbfbec78b')
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('ordenes_compra',1,'ordenes_compra',NULL,NULL,'Usa Nueva OC para crear una orden: elige proveedor, centro de costo (CECO), sociedad si tu empresa usa varias, y agrega los ítems con cantidad y precio unitario. La pantalla calcula subtotal, IGV y total.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('ordenes_compra',2,'ordenes_compra',NULL,NULL,'Guardar borrador deja la OC editable. Emitir OC exige proveedor válido, CECO y al menos un ítem con cantidad mayor a cero; si las líneas tienen CECO distintos o sin CECO, reasígnalas antes de emitir.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('ordenes_compra',3,'ordenes_compra',NULL,NULL,'Una OC emitida se puede Marcar como confirmada cuando el proveedor la acepta. Mientras está en borrador puedes editarla desde su detalle.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('ordenes_compra',4,'ordenes_compra',NULL,NULL,'En el detalle usa Registrar anticipo para dejar constancia de un pago adelantado al proveedor, con fecha, monto y referencia del pago.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('ordenes_compra',5,'ordenes_compra',NULL,NULL,'Si la mercadería viaja, registra el tránsito (transportista, vehículo, conductor, guía y fecha de salida); solo se permite con la OC emitida o confirmada. Con la OC emitida, Registrar recepción permite ingresar lo que llegó.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('ordenes_compra',6,'ordenes_compra',NULL,NULL,'Si el proveedor no entregará un saldo, usa Liberar pendiente en la línea, indica la cantidad y el motivo: esa cantidad vuelve a la Bandeja de Sourcing para comprarla a otro proveedor.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('ordenes_compra',7,'ordenes_compra',NULL,NULL,'Cuando la OC tiene saldo por facturar, Registrar CxP vincula la factura del proveedor a la OC y evita duplicar la deuda; Ver CxP abre las cuentas por pagar ya registradas.');
INSERT INTO public.asistente_manual_fichas (clave,tipo,pantalla_key,titulo,resumen,fuentes,revision) VALUES ('ordenes_fabricacion','pantalla','of','Órdenes de Fab. (OF)','Bandeja de las órdenes de fabricación.','["operaciones-app/src/zahory-mock/pages/of/BandejaOFPage.jsx#BandejaOFPage"]'::jsonb,'6f1d2aaebd')
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('ordenes_fabricacion',1,'of',NULL,NULL,'La bandeja lista las órdenes de fabricación; Todas muestra todos los estados y Limpiar filtros quita los filtros.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('ordenes_fabricacion',2,'of',NULL,NULL,'Nueva OF abre el registro de una orden nueva.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('ordenes_fabricacion',3,'of',NULL,NULL,'Abre una orden para ver su ruta y sus materiales.');
INSERT INTO public.asistente_manual_fichas (clave,tipo,pantalla_key,titulo,resumen,fuentes,revision) VALUES ('ordenes_servicio','pantalla','ordenes_servicio','Ordenes de Servicio','Órdenes de servicio a proveedores y su conformidad.','["src/pages_ops.jsx#OrdenesServicio"]'::jsonb,'0144236b2a')
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('ordenes_servicio',1,'ordenes_servicio',NULL,NULL,'Crea una orden con Nueva OS: debes tener seleccionada una sociedad y elegir un CECO, que es obligatorio.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('ordenes_servicio',2,'ordenes_servicio',NULL,NULL,'Emitir OS la emite al proveedor.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('ordenes_servicio',3,'ordenes_servicio',NULL,NULL,'Conformidad registra que el servicio se recibió conforme.');
INSERT INTO public.asistente_manual_fichas (clave,tipo,pantalla_key,titulo,resumen,fuentes,revision) VALUES ('ot_admin','pantalla','ot','Ordenes de Trabajo','Órdenes de trabajo desde Administración: tareas, técnicos, costos, partes y cierre.','["src/pages_ops.jsx#OT"]'::jsonb,'00534e2e64')
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('ot_admin',1,'ot',NULL,NULL,'Dentro de una OT, Agregar tarea o Nueva tarea arma el trabajo y Asignar tecnico define quién lo hace y sirve también para reasignar la OT a otro técnico. Gestionar en Planner lleva a la programación.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('ot_admin',2,'ot',NULL,NULL,'El estimado de la OT se arma con Agregar material, Agregar servicio de tercero y Agregar gasto logístico; Importar desde HC trae la Hoja de Costeo como estimado editable, que debes revisar y guardar con Guardar estimado.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('ot_admin',3,'ot',NULL,NULL,'Iniciar OT comienza el trabajo. Para registrar un parte con Registrar Parte Diario debe existir al menos una tarea.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('ot_admin',4,'ot',NULL,NULL,'Los partes se envían con Enviar a revisión; quien revisa usa Aprobar, Observar o Rechazar, y Reabrir para editar devuelve un parte ya revisado.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('ot_admin',5,'ot',NULL,NULL,'Guardar costos reales y Recalcular costo real actualizan el costo real de la OT. Registrar Incidente deja constancia de un incidente.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('ot_admin',6,'ot',NULL,NULL,'Abrir en Operaciones y Cerrar en Operaciones llevan a la aplicación de Operaciones, donde se cierra la OT. Anular OT la deja sin efecto y pide confirmación.');
INSERT INTO public.asistente_manual_fichas (clave,tipo,pantalla_key,titulo,resumen,fuentes,revision) VALUES ('organigrama','pantalla','organigrama','Organigrama','Estructura de la empresa: unidades, cargos y posiciones, con el rol que recibe cada posición.','["src/pages_organigrama_v2.jsx#OrganigramaV2Page"]'::jsonb,'c1965a30ee')
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('organigrama',1,'organigrama',NULL,NULL,'Crea las áreas con Nueva unidad organizacional y elige su nivel.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('organigrama',2,'organigrama',NULL,NULL,'Dentro de una unidad defines el cargo y la cantidad de posiciones; al guardar se crean sus sillas vacantes.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('organigrama',3,'organigrama',NULL,NULL,'Cada posición lleva un rol sugerido, que puedes editar, y los módulos de campo habilitados para la aplicación móvil.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('organigrama',4,'organigrama',NULL,NULL,'Al guardar un cambio de rol o de módulos, se aplica a las personas que ocupan esa posición.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('organigrama',5,'organigrama',NULL,NULL,'Eliminar cargo retira un cargo del organigrama.');
INSERT INTO public.asistente_manual_fichas (clave,tipo,pantalla_key,titulo,resumen,fuentes,revision) VALUES ('os_cliente','pantalla','os_cliente','OS Cliente','Órdenes de servicio del cliente: alcance aprobado, órdenes de trabajo, valorizaciones y cierre.','["src/pages_core.jsx#OSCliente"]'::jsonb,'90315ca39a')
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('os_cliente',1,'os_cliente',NULL,NULL,'Crea una orden con Nueva OS. Vincular cotización la relaciona con una cotización aprobada e Importar desde cotización trae sus partidas.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('os_cliente',2,'os_cliente',NULL,NULL,'Crea el trabajo con Crear OT, o con Crear OF si es fabricación. La OS debe tener CEBE asignado, y cada OT un servicio y un centro de costo.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('os_cliente',3,'os_cliente',NULL,NULL,'Registra lo facturable con Nueva valorización. Agregar hito define los hitos de pago de la orden.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('os_cliente',4,'os_cliente',NULL,NULL,'Para un servicio recurrente elige el cobro mensual e indica la tarifa mensual sin IGV y la fecha de inicio: la primera OT la creas tú y luego se crea sola el día 1 de cada mes. El filtro Cobro mensual muestra solo estas órdenes.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('os_cliente',5,'os_cliente',NULL,NULL,'Pausar OS detiene la orden y Reactivar OS la retoma. Cerrar OS la termina y Anular OS la deja sin efecto. Abrir en Operaciones lleva a la orden de trabajo en la aplicación de Operaciones.');
INSERT INTO public.asistente_manual_fichas (clave,tipo,pantalla_key,titulo,resumen,fuentes,revision) VALUES ('panel_flota','pantalla','flota_panel','Panel de Flota','Equipos de la flota, su estado y su despacho o recepción.','["operaciones-app/src/zahory-mock/pages/flota/FlotaPanelPage.jsx#FlotaPanelPage"]'::jsonb,'a4bc77e2dd')
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('panel_flota',1,'flota_panel',NULL,NULL,'Registrar equipo da de alta un equipo de la flota.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('panel_flota',2,'flota_panel',NULL,NULL,'Despachar equipo inicia la entrega de un equipo y Recibir equipo su devolución; ambos requieren acceso a Actas & Despachos.');
INSERT INTO public.asistente_manual_fichas (clave,tipo,pantalla_key,titulo,resumen,fuentes,revision) VALUES ('panel_produccion','pantalla','os_cliente','Panel de Producción','Tablero de las órdenes de servicio en producción y sus atrasos.','["src/pages_produccion_os_cliente.jsx#PanelProduccionOSCliente"]'::jsonb,'25f708de95')
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('panel_produccion',1,'os_cliente',NULL,NULL,'Muestra las OS Cliente en Tablero o en Lista. Solo atrasadas filtra las que están fuera de plazo.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('panel_produccion',2,'os_cliente',NULL,NULL,'Nueva OS Cliente crea una orden: cliente y descripción son obligatorios y debes seleccionar o crear un activo.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('panel_produccion',3,'os_cliente',NULL,NULL,'Recepciones e Ir a Recepción de Activos llevan al ingreso de equipos al taller.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('panel_produccion',4,'os_cliente',NULL,NULL,'Una OS con registros asociados no se puede eliminar.');
INSERT INTO public.asistente_manual_fichas (clave,tipo,pantalla_key,titulo,resumen,fuentes,revision) VALUES ('parametros','pantalla','parametros','Parametros Generales','Configuración general de la empresa: sociedades, series, cuentas bancarias, tipo de cambio, feriados y nómina.','["src/pages_admin.jsx#Parametros"]'::jsonb,'980cef576e')
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('parametros',1,'parametros',NULL,NULL,'Nueva sociedad registra cada sociedad de la empresa.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('parametros',2,'parametros',NULL,NULL,'Las series de los documentos se crean con Agregar serie indicando documento y serie, y las cuentas bancarias con Agregar cuenta.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('parametros',3,'parametros',NULL,NULL,'Guardar TC registra el tipo de cambio; Actualizar ahora lo trae de la fuente externa.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('parametros',4,'parametros',NULL,NULL,'Agregar feriado suma un feriado con su fecha y su nombre.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('parametros',5,'parametros',NULL,NULL,'Las secciones de nómina y de evaluaciones guardan sus propios parámetros, entre ellos las tasas de AFP con Editar tasa AFP.');
INSERT INTO public.asistente_manual_fichas (clave,tipo,pantalla_key,titulo,resumen,fuentes,revision) VALUES ('partes','pantalla','partes','Partes Diarios','Revisión y aprobación de los partes diarios de trabajo.','["src/pages_ops.jsx#Partes"]'::jsonb,'294d071ef7')
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('partes',1,'partes',NULL,NULL,'La lista muestra los partes diarios registrados; Limpiar quita los filtros.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('partes',2,'partes',NULL,NULL,'Enviar a revisión manda un parte a su revisor.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('partes',3,'partes',NULL,NULL,'Quien revisa usa Aprobar, Observar, que envía una observación al autor, o Rechazar; cada acción pide confirmación.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('partes',4,'partes',NULL,NULL,'Reabrir para editar devuelve un parte ya revisado para corregirlo.');
INSERT INTO public.asistente_manual_fichas (clave,tipo,pantalla_key,titulo,resumen,fuentes,revision) VALUES ('partes_taller','pantalla','partes','Parte diario de taller','Registra el trabajo diario del técnico sobre una OT: actividades, fotos, hallazgos y repuestos, y lo envía a revisión.','["operaciones-app/src/zahory-mock/pages/pages3.jsx#ParteTallerPage"]'::jsonb,'a7974170a2')
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('partes_taller',1,'partes',NULL,NULL,'Elige la OT (programada o en ejecución), el técnico y la fecha del parte.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('partes_taller',2,'partes',NULL,NULL,'Agrega cada actividad realizada con su tiempo; puedes adjuntar fotos y usar Dictar por voz para describirla.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('partes_taller',3,'partes',NULL,NULL,'Reportar hallazgo adicional registra un problema encontrado durante el trabajo. Agrega los repuestos usados o pide los que faltan; si el pedido falla, usa Reintentar pedido de repuestos.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('partes_taller',4,'partes',NULL,NULL,'Guardar borrador conserva el parte para seguirlo luego. Enviar a revisión exige al menos una actividad y deja el parte en revisión del supervisor.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('partes_taller',5,'partes',NULL,NULL,'El parte es la base del avance y del costo real de la OT: las horas del parte por la tarifa del técnico se suman al costo real cuando el parte queda aprobado. Un parte en borrador o en revisión todavía no cuenta.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('partes_taller',6,'partes',NULL,NULL,'Ciclo del parte: Borrador → En revisión → Aprobado. Quien revisa puede Aprobar (confirma el avance), Observar (lo devuelve para corregir, con motivo obligatorio) o Rechazar (con motivo obligatorio). Un parte aprobado se corrige solo si quien aprueba usa Reabrir para editar e indica el motivo.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('partes_taller',7,'partes',NULL,NULL,'Si no puedes registrar el parte: la OT debe estar programada o en ejecución y tener al menos una tarea; si no aparece en la lista, pide al jefe de taller que la inicie o le agregue tareas.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('partes_taller',8,'partes',NULL,NULL,'Cada parte corresponde a un técnico, una OT y una fecha. Si el trabajo siguió al día siguiente, se hace otro parte con esa fecha.');
INSERT INTO public.asistente_manual_fichas (clave,tipo,pantalla_key,titulo,resumen,fuentes,revision) VALUES ('pasaporte_equipos','pantalla','pasaporte_equipos','Pasaporte de Equipos','Documentos de cada equipo de la flota.','["operaciones-app/src/zahory-mock/pages/flota/PasaporteEquiposPage.jsx#PasaporteEquiposPage"]'::jsonb,'14c7aba2b3')
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('pasaporte_equipos',1,'pasaporte_equipos',NULL,NULL,'Selecciona un equipo y usa Agregar documento para registrar un documento suyo.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('pasaporte_equipos',2,'pasaporte_equipos',NULL,NULL,'Editar cambia los datos del documento. Para cambiar el archivo hay que eliminar el documento y volver a registrarlo.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('pasaporte_equipos',3,'pasaporte_equipos',NULL,NULL,'Eliminar documento lo borra.');
INSERT INTO public.asistente_manual_fichas (clave,tipo,pantalla_key,titulo,resumen,fuentes,revision) VALUES ('rrhh_admin','pantalla','rrhh_admin','Personal Administrativo','Ficha del personal administrativo: datos, contratos, jornada, documentos y amonestaciones.','["src/pages_admin.jsx#RRHHAdmin"]'::jsonb,'2883372074')
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('rrhh_admin',1,'rrhh_admin',NULL,NULL,'Registra a un trabajador con Nuevo colaborador; Importar Excel carga varios a la vez con la plantilla. Al crearlo, la pantalla recuerda subir el contrato firmado para activar las alertas de vencimiento.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('rrhh_admin',2,'rrhh_admin',NULL,NULL,'Nuevo contrato registra su contrato y Renovar lo renueva. El contrato se puede enviar con Enviar a firma del trabajador y firmar con Firmar como empresa.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('rrhh_admin',3,'rrhh_admin',NULL,NULL,'Asignar jornada define su horario y Asignar cargo su puesto. Agregar cuenta registra sus datos bancarios.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('rrhh_admin',4,'rrhh_admin',NULL,NULL,'Sube sus documentos en la ficha; Archivar documento lo conserva pero deja de estar vigente. Configurar requisitos define qué documentos se exigen.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('rrhh_admin',5,'rrhh_admin',NULL,NULL,'Registrar amonestación deja constancia de una sanción; si el trabajador no tiene usuario de sistema, se le notifica por medios físicos y se adjunta el cargo firmado.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('rrhh_admin',6,'rrhh_admin',NULL,NULL,'Renovar con firma digital (en el contrato del trabajador) renueva sin papel: eliges la plantilla publicada, la modalidad, las fechas de inicio y fin, la causa objetiva, la remuneración base y el firmante de la empresa. Si la fecha de inicio es anterior a hoy, la pantalla avisa pero no bloquea.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('rrhh_admin',7,'rrhh_admin',NULL,NULL,'Orden de la firma digital: primero firma la empresa (el firmante recibe un código en el correo personal de su ficha), luego el sistema envía solo el enlace al trabajador, que firma con su propio código. Al completarse las dos firmas el contrato queda aprobado automáticamente y el PDF lleva las dos constancias.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('rrhh_admin',8,'rrhh_admin',NULL,NULL,'Un contrato firmado por ambas partes queda protegido: no se puede modificar ni eliminar. Renovar con firma digital no aparece en contratos históricos, en adendas ni cuando el contrato ya tiene una renovación aprobada.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('rrhh_admin',9,'rrhh_admin',NULL,NULL,'Antes de la primera renovación digital, el firmante de la empresa debe estar registrado en Firmantes de contratos y tener correo personal en su ficha; el trabajador también necesita correo personal. Hoy el enlace y el código llegan por correo.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('rrhh_admin',10,'rrhh_admin',NULL,NULL,'Se puede renovar por adelantado: el contrato actual sigue vigente hasta su fin y la ficha muestra el siguiente como «Próximo · desde». Un trabajador con renovación aprobada que empalma con su contrato ya no aparece en «Contratos por vencer».');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('rrhh_admin',11,'rrhh_admin',NULL,NULL,'Sin contrato o adenda vigente en la fecha, el sistema no deja registrar asistencia de ese trabajador. Si alguien no puede marcar, revisa primero la vigencia de su contrato.');
INSERT INTO public.asistente_manual_fichas (clave,tipo,pantalla_key,titulo,resumen,fuentes,revision) VALUES ('rrhh_operativo','pantalla','rrhh_operativo','Personal Operativo','Ficha del personal operativo: datos, contratos, jornada, documentos y amonestaciones.','["src/pages_ops.jsx#RRHH_Operativo"]'::jsonb,'8339f61f9c')
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('rrhh_operativo',1,'rrhh_operativo',NULL,NULL,'Registra a un trabajador con Nuevo Colaborador; Carga masiva registra a varios desde un archivo y Descargar Excel exporta la lista.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('rrhh_operativo',2,'rrhh_operativo',NULL,NULL,'Nuevo contrato registra su contrato y Renovar lo renueva. El contrato se puede enviar con Enviar a firma del trabajador y firmar con Firmar como empresa.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('rrhh_operativo',3,'rrhh_operativo',NULL,NULL,'Asignar jornada define su horario y Agregar cuenta registra sus datos bancarios.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('rrhh_operativo',4,'rrhh_operativo',NULL,NULL,'Un documento subido queda pendiente de aprobación por RRHH. Archivar documento lo conserva pero deja de estar vigente.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('rrhh_operativo',5,'rrhh_operativo',NULL,NULL,'Registrar amonestación deja constancia de una sanción; el motivo es obligatorio.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('rrhh_operativo',6,'rrhh_operativo',NULL,NULL,'Renovar con firma digital (en el contrato del trabajador) renueva sin papel: eliges la plantilla publicada, la modalidad, las fechas de inicio y fin, la causa objetiva, la remuneración base y el firmante de la empresa. Si la fecha de inicio es anterior a hoy, la pantalla avisa pero no bloquea.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('rrhh_operativo',7,'rrhh_operativo',NULL,NULL,'Orden de la firma digital: primero firma la empresa (el firmante recibe un código en el correo personal de su ficha), luego el sistema envía solo el enlace al trabajador, que firma con su propio código. Al completarse las dos firmas el contrato queda aprobado automáticamente y el PDF lleva las dos constancias.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('rrhh_operativo',8,'rrhh_operativo',NULL,NULL,'Un contrato firmado por ambas partes queda protegido: no se puede modificar ni eliminar. Renovar con firma digital no aparece en contratos históricos, en adendas ni cuando el contrato ya tiene una renovación aprobada.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('rrhh_operativo',9,'rrhh_operativo',NULL,NULL,'Antes de la primera renovación digital, el firmante de la empresa debe estar registrado en Firmantes de contratos y tener correo personal en su ficha; el trabajador también necesita correo personal. Hoy el enlace y el código llegan por correo.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('rrhh_operativo',10,'rrhh_operativo',NULL,NULL,'Se puede renovar por adelantado: el contrato actual sigue vigente hasta su fin y la ficha muestra el siguiente como «Próximo · desde». Un trabajador con renovación aprobada que empalma con su contrato ya no aparece en «Contratos por vencer».');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('rrhh_operativo',11,'rrhh_operativo',NULL,NULL,'Sin contrato o adenda vigente en la fecha, el sistema no deja registrar asistencia de ese trabajador. Si alguien no puede marcar, revisa primero la vigencia de su contrato.');
INSERT INTO public.asistente_manual_fichas (clave,tipo,pantalla_key,titulo,resumen,fuentes,revision) VALUES ('pipeline','pantalla','pipeline','Pipeline','Seguimiento de las oportunidades de venta por etapa, con su cotización, su acuerdo de comisión y su cierre.','["src/pages_core.jsx#Pipeline"]'::jsonb,'bcfa0a720d')
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('pipeline',1,'pipeline',NULL,NULL,'Crea una oportunidad con Nueva oportunidad y síguela en Kanban o en Lista. El Historial de movimientos muestra por qué etapas pasó.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('pipeline',2,'pipeline',NULL,NULL,'Desde la oportunidad usa Nueva Cotización para cotizar. Si necesita costeo, la Hoja de Costeo se crea desde aquí y exige tener elegida una sociedad concreta en el selector superior.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('pipeline',3,'pipeline',NULL,NULL,'Agendar programa una actividad con el cliente y Actividades muestra las registradas.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('pipeline',4,'pipeline',NULL,NULL,'El vendedor fija su comisión con Proponer acuerdo. Si cambia el porcentaje base o agrega una bonificación debe usar Enviar a aprobación; el Gerente Comercial lo aprueba o lo rechaza con un motivo, y el vendedor puede retirarlo con Retirar solicitud.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('pipeline',5,'pipeline',NULL,NULL,'Cierra la oportunidad con Ganar o con Perder, que pide confirmar la pérdida. Una oportunidad ganada sigue con Crear OS Cliente.');
INSERT INTO public.asistente_manual_fichas (clave,tipo,pantalla_key,titulo,resumen,fuentes,revision) VALUES ('cs_planes','pantalla','cs_planes','Planes de Exito','Planes de éxito de los clientes y sus reuniones de seguimiento.','["src/pages_cs.jsx#CSPlanes"]'::jsonb,'47127ab65e')
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('cs_planes',1,'cs_planes',NULL,NULL,'Crea un plan con Nuevo plan y ábrelo con Ver plan.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('cs_planes',2,'cs_planes',NULL,NULL,'Nueva reunión registra una reunión de seguimiento con el cliente.');
INSERT INTO public.asistente_manual_fichas (clave,tipo,pantalla_key,titulo,resumen,fuentes,revision) VALUES ('planner','pantalla','planner','Planner y Recursos','Asignación de personal y cuadrillas a las órdenes de trabajo por día y por semana.','["src/pages_ops.jsx#Planner"]'::jsonb,'08abbaac09')
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('planner',1,'planner',NULL,NULL,'Navega por semana o por mes; Hoy vuelve a la fecha actual.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('planner',2,'planner',NULL,NULL,'Agregar colaborador este día asigna a una persona; Asignar por rango la asigna a varios días y se confirma con Confirmar asignación.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('planner',3,'planner',NULL,NULL,'Nueva cuadrilla crea un grupo de trabajo con Crear cuadrilla.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('planner',4,'planner',NULL,NULL,'Editar fecha/horario cambia una asignación y Eliminar la quita.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('planner',5,'planner',NULL,NULL,'Exportar Excel descarga la programación y Ver Detalle OT abre la orden.');
INSERT INTO public.asistente_manual_fichas (clave,tipo,pantalla_key,titulo,resumen,fuentes,revision) VALUES ('planner_taller','pantalla','planner','Planner','Programación del taller: asignar y reprogramar OT a técnicos, bahías, puestos y máquinas, alertas y simulación de OT urgente.','["operaciones-app/src/zahory-mock/pages/planner/PlannerPage.jsx#PlannerPage"]'::jsonb,'609b8e7459')
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('planner_taller',1,'planner',NULL,NULL,'Antes de programar hay que configurar el taller con Configurar taller: sus bahías y puestos, y sus máquinas.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('planner_taller',2,'planner',NULL,NULL,'Al programar una OT se le asignan personas, máquinas y puesto.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('planner_taller',3,'planner',NULL,NULL,'La simulación permite elegir una OT para meterla con prioridad y ver cómo cambia el plan antes de aplicarlo con Aplicar al plan.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('planner_taller',4,'planner',NULL,NULL,'Necesita una empresa activa en la sesión de Operaciones.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('planner_taller',5,'planner',NULL,NULL,'El Planner tiene varias vistas: Panel (bandeja Por planificar, capacidad semanal por cargo y máquina, y las OS con sus OT), Tablero (el calendario por especialidad y por puesto), Configurar taller y Gemelo 3D.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('planner_taller',6,'planner',NULL,NULL,'Para programar, toma una OT de Por planificar y usa Asignar tarea: con Automático el sistema propone personas según la especialidad de la tarea; con + y − cambias cuántas personas; eliges máquina y puesto, y con «No empezar antes de» fijas la fecha más temprana (solo días hábiles).');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('planner_taller',7,'planner',NULL,NULL,'Para reprogramar o cambiar de técnico, arrastra el bloque en el Tablero a otra persona, otro puesto u otro día. Cada cambio se puede revertir con Deshacer.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('planner_taller',8,'planner',NULL,NULL,'Las ausencias aprobadas en RRHH (permisos, vacaciones) aparecen rayadas en el Tablero y esa persona no se debe cargar ese día. Un permiso recién registrado aparece al recargar la página.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('planner_taller',9,'planner',NULL,NULL,'Alertas lista los problemas que el Planner detecta en el plan, cada uno con una sugerencia y el botón Aplicar para resolverlo.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('planner_taller',10,'planner',NULL,NULL,'Simular OT urgente muestra cuántos días se corre cada OT si metes una con prioridad y cuál es el cuello de botella; nada cambia hasta usar Aplicar al plan, que tarda unos segundos y también se puede deshacer.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('planner_taller',11,'planner',NULL,NULL,'Si una persona no aparece para asignar, revisa en Personal que esté activa y que su cargo sea el de la tarea. Si una tarea no encuentra bahía, enlaza la máquina con su equipo en Configurar taller.');
INSERT INTO public.asistente_manual_fichas (clave,tipo,pantalla_key,titulo,resumen,fuentes,revision) VALUES ('prestamo_herramientas','pantalla','inventario','Préstamo de herramientas','Préstamo y devolución de herramientas del almacén: a quién se prestó, hasta cuándo y cuáles tienen la devolución vencida.','["operaciones-app/src/zahory-mock/pages/wms/HerramientasPage.jsx#HerramientasPage"]'::jsonb,'8536c0bbd6')
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('prestamo_herramientas',1,'inventario',NULL,NULL,'Prestar herramienta registra a quién se entrega con Registrar préstamo.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('prestamo_herramientas',2,'inventario',NULL,NULL,'Recibir anota su regreso con Registrar devolución.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('prestamo_herramientas',3,'inventario',NULL,NULL,'Para qué sirve: la herramienta prestada sigue siendo del almacén y conserva su valor; no es un consumo. Mientras está prestada deja de estar disponible para otros.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('prestamo_herramientas',4,'inventario',NULL,NULL,'Prestar herramienta pide la herramienta (búscala por código, descripción o serie), la cantidad, a quién se presta y la fecha de devolución; la OT y la observación son opcionales. No deja prestar más de lo disponible. Si el artículo no aparece, marca «Mostrar todo el stock, no solo herramientas».');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('prestamo_herramientas',5,'inventario',NULL,NULL,'Recibir registra la devolución con la cantidad devuelta; si regresa solo una parte, el resto sigue pendiente a nombre de la misma persona.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('prestamo_herramientas',6,'inventario',NULL,NULL,'Los filtros Activos, Vencidos y Devueltos separan los préstamos. «Con devolución vencida» cuenta los que pasaron su fecha sin regresar: es la lista para reclamar a cada persona. Puedes buscar por herramienta, persona u OT.');
INSERT INTO public.asistente_manual_fichas (clave,tipo,pantalla_key,titulo,resumen,fuentes,revision) VALUES ('prestamos_personal','pantalla','prestamos_personal','Prestamos al Personal','Préstamos de la empresa a sus trabajadores: registro, cuotas, descuento automático en planilla y pagos manuales.','["src/pages_fin.jsx#PrestamosPersonal"]'::jsonb,'5ed0bafa41')
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('prestamos_personal',1,'prestamos_personal',NULL,NULL,'Registra un préstamo con Nuevo Préstamo.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('prestamos_personal',2,'prestamos_personal',NULL,NULL,'Pagar cuota registra el pago manual de una cuota y pide confirmación.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('prestamos_personal',3,'prestamos_personal',NULL,NULL,'Ver abre el detalle del préstamo. Cancelar el préstamo no se puede deshacer.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('prestamos_personal',4,'prestamos_personal',NULL,NULL,'Nuevo Préstamo pide el trabajador, el monto total y el número de cuotas; la cuota mensual es el monto dividido entre las cuotas. Aquí no se calculan intereses.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('prestamos_personal',5,'prestamos_personal',NULL,NULL,'Con «Descontar automáticamente en nómina» marcado, la cuota mensual queda en la ficha del trabajador y la planilla la descuenta cada mes. Sin marcar, cada cuota se registra a mano con Pagar cuota.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('prestamos_personal',6,'prestamos_personal',NULL,NULL,'Avance Cuotas muestra cuántas van pagadas. Al pagarse la última, el préstamo queda cancelado y el descuento en planilla se detiene.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('prestamos_personal',7,'prestamos_personal',NULL,NULL,'No confundir con Financiamiento y Deuda, que son los préstamos que la empresa recibe de bancos; esta pantalla es lo que la empresa presta a su personal.');
INSERT INTO public.asistente_manual_fichas (clave,tipo,pantalla_key,titulo,resumen,fuentes,revision) VALUES ('presupuestos','pantalla','presupuestos','Presupuesto vs Real','Presupuesto del mes por partida, su aprobación y su comparación con lo ejecutado (presupuesto contra real): qué partidas se excedieron y de dónde sale cada cifra.','["src/pages_fin.jsx#Presupuestos"]'::jsonb,'0f8e7923fc')
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('presupuestos',1,'presupuestos',NULL,NULL,'Crea un presupuesto con Nuevo presupuesto y sus partidas con Agregar partida.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('presupuestos',2,'presupuestos',NULL,NULL,'Agregar aprobador define quién debe aprobarlo, y Enviar a aprobación lo manda a revisión.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('presupuestos',3,'presupuestos',NULL,NULL,'Los aprobadores usan Aprobar o Rechazar.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('presupuestos',4,'presupuestos',NULL,NULL,'Para qué sirve: fijar cuánto se planea gastar en un mes, por partida (Materiales, Mano de obra, Logística y otras categorías), y ver cuánto se va ejecutando. Un presupuesto puede ser de toda la empresa o de un centro de costo, y en empresas con varias sociedades pertenece a una sociedad.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('presupuestos',5,'presupuestos',NULL,NULL,'De dónde sale lo ejecutado: de las compras y gastos del mes con la misma categoría de la partida, de las cuentas por pagar de órdenes de compra emitidas en el mes, y del costo real de las órdenes de trabajo cerradas en el mes, que cuenta como Mano de obra. Solo se compara dentro de la misma moneda.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('presupuestos',6,'presupuestos',NULL,NULL,'Cada partida muestra presupuestado, ejecutado, variación y porcentaje de ejecución; en rojo las excedidas, y arriba un aviso con cuántas partidas se pasaron. Haz clic en una partida para ver los registros que suman su ejecutado.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('presupuestos',7,'presupuestos',NULL,NULL,'Si aparece gasto «sin partida», es gasto real del mes que no coincide con ninguna partida del presupuesto en esa moneda. Suele ser una categoría mal elegida al registrar el gasto o una partida que faltó presupuestar.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('presupuestos',8,'presupuestos',NULL,NULL,'Si lo ejecutado no cuadra, revisa la categoría y la fecha del gasto, y si el presupuesto es de un centro de costo: una OT de otro centro no cuenta en él.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('presupuestos',9,'presupuestos',NULL,NULL,'También puedes preguntarle a Aria cómo va el presupuesto del mes o qué partidas se excedieron: usa este mismo cálculo.');
INSERT INTO public.asistente_manual_fichas (clave,tipo,pantalla_key,titulo,resumen,fuentes,revision) VALUES ('problemas_corregir_registro','proceso',NULL,'Me equivoqué al registrar algo: cómo corregir o anular cada documento','Guía rápida de qué se puede editar, qué se anula y qué no se puede deshacer, documento por documento.','["src/pages_fin.jsx#Facturacion","src/pages_fin.jsx#CxC"]'::jsonb,'e697a23316 06993c9c6e')
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('problemas_corregir_registro',1,'ninguna',NULL,NULL,'Regla general: mientras un documento está en borrador se puede editar con libertad. Una vez emitido, aprobado o con movimientos de dinero, normalmente ya no se edita: se anula con un motivo y se registra de nuevo. Anular conserva el historial; eliminar borra el registro y suele estar permitido solo cuando el documento aún no generó nada.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('problemas_corregir_registro',2,'ninguna',NULL,NULL,'Egreso de caja chica: en el fondo, Historial › Egresos, usa Editar para cambiar concepto, categoría, centro de costo, número de comprobante y fecha. El monto no se edita: si está mal, anula el egreso con su motivo y regístralo otra vez. El egreso anulado devuelve su monto al saldo.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('problemas_corregir_registro',3,'ninguna',NULL,NULL,'Gasto en Compras / Gastos: ábrelo y usa Editar. No se puede editar ahí si ya tiene una cuenta por pagar generada, si viene de nómina, si está en Caja Chica o si se capitalizó como activo fijo; la pantalla indica dónde corregirlo.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('problemas_corregir_registro',4,'ninguna',NULL,NULL,'Orden de compra: se edita mientras está en borrador. Recepción: anularla revierte el stock que ingresó, y solo corresponde si la mercadería no llegó realmente. Cuenta por pagar: Anular conserva el historial y solo procede si no tiene pagos ni dependencias; una CxP preliminar se puede eliminar.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('problemas_corregir_registro',5,'ninguna',NULL,NULL,'Factura a cliente: Editar corrige datos del comprobante; Anular la deja sin efecto y Restaurar la devuelve a emitida. Para corregir un importe ya facturado lo correcto es una Nota de Crédito o de Débito. En Cuentas por Cobrar, Revertir cobros deshace cobros y conciliaciones.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('problemas_corregir_registro',6,'ninguna',NULL,NULL,'Parte diario: si ya fue revisado, el supervisor usa Reabrir para editar. Marcación de asistencia: se corrige con un ajuste que exige motivo y aprobación. Préstamo o financiamiento: Editar recalcula las cuotas pendientes y no cambia las pagadas.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('problemas_corregir_registro',7,'ninguna',NULL,NULL,'Acciones que no se pueden deshacer y piden doble cuidado: eliminar un fondo de caja chica, eliminar un financiamiento con sus pagos, revocar una API key, eliminar un rol y cerrar un período de nómina.');
INSERT INTO public.asistente_manual_fichas (clave,tipo,pantalla_key,titulo,resumen,fuentes,revision) VALUES ('problemas_saldo_banco','proceso',NULL,'No me cuadra el saldo del banco con el sistema: qué revisar','Pasos para encontrar por qué el saldo de una cuenta en Tesorería no coincide con el del banco.','["src/pages_fin.jsx#Tesoreria"]'::jsonb,'b0397fbc8c')
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('problemas_saldo_banco',1,'ninguna',NULL,NULL,'El saldo de una cuenta en el sistema es su saldo inicial más todos los movimientos registrados. Si no coincide con el banco, falta un movimiento, sobra uno, hay uno duplicado o el saldo inicial está mal.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('problemas_saldo_banco',2,'ninguna',NULL,NULL,'Primero importa el extracto del banco en Tesorería › Extracto banco con Importar extracto, y ve a Match Bancario: lo que queda sin emparejar de un lado o del otro es exactamente la diferencia.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('problemas_saldo_banco',3,'ninguna',NULL,NULL,'Movimiento del banco sin pareja en el sistema: falta registrarlo. Si es un cobro o un pago, regístralo en su módulo (Cuentas por Cobrar o Cuentas por Pagar); si es una comisión bancaria, un interés u otro movimiento que no viene de un módulo, usa Movimiento manual.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('problemas_saldo_banco',4,'ninguna',NULL,NULL,'Movimiento del sistema sin pareja en el banco: puede ser un pago registrado que el banco aún no procesa, un registro en la cuenta equivocada o un duplicado. Revisa cuenta, fecha e importe antes de confirmar un match; un match equivocado se puede deshacer.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('problemas_saldo_banco',5,'ninguna',NULL,NULL,'Si importaste el mismo extracto dos veces, el historial de lotes permite borrar el lote cargado por error.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('problemas_saldo_banco',6,'ninguna',NULL,NULL,'Si todo está emparejado y aun así hay diferencia desde el primer día, corrige el saldo con el que empezó la cuenta con Editar saldo inicial.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('problemas_saldo_banco',7,'ninguna',NULL,NULL,'El dinero que pasa de una cuenta propia a otra se registra como Transferencia entre cuentas, no como un egreso y un ingreso sueltos: así no distorsiona los gastos.');
INSERT INTO public.asistente_manual_fichas (clave,tipo,pantalla_key,titulo,resumen,fuentes,revision) VALUES ('proceso_almacen','proceso',NULL,'Almacén: del ingreso de la compra al despacho y el control de stock','Sigue el material dentro del almacén: recepción de la compra, ubicaciones, kardex, reserva y despacho a la OT, conteos, reposición y devoluciones.','["operaciones-app/src/zahory-mock/pages/RecepcionOCPage.jsx#RecepcionOCPage","operaciones-app/src/zahory-mock/pages/UbicacionesPage.jsx#UbicacionesPage","operaciones-app/src/zahory-mock/pages/InventarioKardexPage.jsx#InventarioKardexPage","operaciones-app/src/zahory-mock/pages/ReservaRepuestosPage.jsx#ReservaRepuestosPage","operaciones-app/src/zahory-mock/pages/wms/DespachosPage.jsx#DespachosPage","operaciones-app/src/zahory-mock/pages/wms/ConteosPage.jsx#ConteosPage","operaciones-app/src/zahory-mock/pages/wms/StockMinimosPage.jsx#StockMinimosPage","operaciones-app/src/zahory-mock/pages/wms/DevolucionesPage.jsx#DevolucionesPage"]'::jsonb,'84d78fcc4a 1fc2efb872 8dad26c438 3d08475098 4b4a871230 f926063c1c 126af95fbf 895a94a0ee')
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('proceso_almacen',1,'recepciones',NULL,NULL,'Cuando llega una compra, en Recepciones usa Registrar recepción: el material ingresa al almacén y se generan sus movimientos en el kardex.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('proceso_almacen',2,'inventario',NULL,NULL,'Las ubicaciones del almacén se crean con Nueva ubicación. Una ubicación que ya no se usa se desactiva y se puede reactivar después.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('proceso_almacen',3,'inventario',NULL,NULL,'En Inventario & Kardex la pestaña Stock muestra las existencias y Kardex los movimientos. Registrar entrada, Registrar salida, Mover y Ajustar stock registran movimientos; antes debes elegir una sociedad concreta.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('proceso_almacen',4,'inventario',NULL,NULL,'Los repuestos de una OT se ven en Reserva de Repuestos, donde almacén los entrega al taller con Despachar. La cola de Despachos reúne los pedidos de OT, venta y custodia para prepararlos.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('proceso_almacen',5,'inventario',NULL,NULL,'Para verificar existencias usa Nuevo conteo y elige el almacén. Guardar avance conserva lo contado y Cerrar conteo registra los ajustes en el kardex; si las diferencias superan el umbral, el conteo queda por aprobar por otra persona, que usa Aprobar ajustes o Devolver a recontar.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('proceso_almacen',6,'inventario',NULL,NULL,'En Stock mínimos & reposición, Seleccionar sugeridos marca lo que hay que reponer y Generar SOLPE crea la solicitud de compra, que Compras ve en su bandeja.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('proceso_almacen',7,'inventario',NULL,NULL,'Una devolución se ingresa con Registrar devolución y la mercadería queda en cuarentena para inspección. Al usar Cerrar inspección, Administración recibe el aviso para emitir la nota de crédito.');
INSERT INTO public.asistente_manual_fichas (clave,tipo,pantalla_key,titulo,resumen,fuentes,revision) VALUES ('proceso_alquiler_flota','proceso',NULL,'Alquiler de equipos: del contrato a la liquidación','Sigue un alquiler de equipo: registro del equipo, contrato, acta de despacho y de recepción, partes diarios y liquidación mensual.','["operaciones-app/src/zahory-mock/pages/flota/FlotaPanelPage.jsx#FlotaPanelPage","operaciones-app/src/zahory-mock/pages/flota/ContratosRentalPage.jsx#ContratosRentalPage","operaciones-app/src/zahory-mock/pages/flota/ActasDespachosPage.jsx#ActasDespachosPage","operaciones-app/src/zahory-mock/pages/flota/LiquidacionFlotaPage.jsx#LiquidacionFlotaPage"]'::jsonb,'a4bc77e2dd b8f7626900 b079728c36 a3c150a93e')
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('proceso_alquiler_flota',1,'flota_panel',NULL,NULL,'El equipo propio se da de alta en el Panel de Flota con Registrar equipo.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('proceso_alquiler_flota',2,'contratos_alquiler',NULL,NULL,'El alquiler se formaliza en Contratos Rental con Nuevo contrato. Si la tarifa cambia, Cambiar tarifa guarda una nueva versión del contrato.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('proceso_alquiler_flota',3,'actas_despachos',NULL,NULL,'Al entregar el equipo usa Despachar equipo y emite el acta con Crear acta: completa el checklist (Cargar checklist sugerido trae uno base), marca cada punto como Conforme u Observado y cierra con Confirmar acta. Guardar borrador permite seguir después.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('proceso_alquiler_flota',4,'actas_despachos',NULL,NULL,'Cuando el equipo regresa usa Recibir equipo y emite el acta de recepción de la misma forma. Un acta equivocada se deja sin efecto con Anular acta.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('proceso_alquiler_flota',5,'liquidacion_flota',NULL,NULL,'En Liquidación & DMR registra cada día con Nuevo parte: las horas operadas, el horómetro y las paradas, que se agregan con Agregar parada.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('proceso_alquiler_flota',6,'liquidacion_flota',NULL,NULL,'Al cierre del mes usa Liquidar un mes y Crear liquidación, que queda en borrador. Se manda con Enviar a revisión y quien revisa usa Aprobar o Devolver.');
INSERT INTO public.asistente_manual_fichas (clave,tipo,pantalla_key,titulo,resumen,fuentes,revision) VALUES ('proceso_asistencia','proceso',NULL,'Turnos, asistencia y solicitudes del personal','Sigue el control de asistencia: turnos, marcaciones, geocercas, ajustes, vacaciones y permisos, y el reporte del mes.','["src/pages_turnos.jsx#TurnosHorarios","src/pages_ops.jsx#ControlAsistencia","src/pages_ops.jsx#SolicitudesRrhh"]'::jsonb,'0f9bfb4e97 ce8d288576 fe86ec31ab')
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('proceso_asistencia',1,'turnos',NULL,NULL,'Crea los horarios con Nuevo turno. Un turno que ya usan trabajadores o que tiene asistencias no se puede eliminar: edítalo y cambia su estado a Inactivo.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('proceso_asistencia',2,'asistencia',NULL,NULL,'Cada trabajador necesita un turno asignado antes de marcar asistencia; se le asigna desde su ficha en Personal.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('proceso_asistencia',3,'asistencia',NULL,NULL,'Las marcaciones llegan del Reloj Control (Móvil). También puedes registrarlas a mano, con Registro masivo o con Importar marcaciones desde un archivo.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('proceso_asistencia',4,'asistencia',NULL,NULL,'Las geocercas definen dónde se puede marcar: se crean con nombre, latitud y longitud, o dibujando en el mapa un polígono de al menos tres vértices.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('proceso_asistencia',5,'asistencia',NULL,NULL,'Para corregir una marcación se pide un ajuste indicando el motivo, que es obligatorio; quien aprueba usa Aprobar o Rechazar.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('proceso_asistencia',6,'solicitudes_rrhh',NULL,NULL,'Las vacaciones y permisos se piden con Nueva solicitud; el sistema avisa si no alcanza el saldo de vacaciones. Una solicitud aprobada se pasa a la asistencia con Aplicar a asistencia.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('proceso_asistencia',7,'asistencia',NULL,NULL,'Para cerrar el mes usa Reporte mensual y Exportar Excel.');
INSERT INTO public.asistente_manual_fichas (clave,tipo,pantalla_key,titulo,resumen,fuentes,revision) VALUES ('proceso_caja_chica','proceso',NULL,'Ciclo del fondo de Caja Chica','Controla un fondo desde su creación hasta el arqueo y el cierre con saldo cero.','["src/pages_fin.jsx#CajaChica","src/components/NuevoEgreso.jsx#NuevoEgreso","src/components/CerrarFondoModal.jsx#CerrarFondoModal"]'::jsonb,'99d34ba223 2c804b78dc e7344f6212')
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('proceso_caja_chica',1,'caja','caja','crear','Crea el fondo con su responsable, importe, moneda y origen del dinero.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('proceso_caja_chica',2,'caja',NULL,NULL,'Registra cada egreso con Nuevo egreso: tipo de gasto, categoría del Estado de Resultados, comprobante adjunto y revisión final.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('proceso_caja_chica',3,'caja',NULL,NULL,'Cuando el fondo necesite reposición, presenta la rendición del periodo.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('proceso_caja_chica',4,'caja','caja','aprobar','Revisa y aprueba o rechaza la rendición para reponer el fondo.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('proceso_caja_chica',5,'caja',NULL,NULL,'Realiza el arqueo con el efectivo contado y revisa las diferencias.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('proceso_caja_chica',6,'caja','caja','editar','Cierra el fondo dejando el saldo en cero: transfiere lo que quede a otra caja abierta o devuélvelo a una cuenta bancaria.');
INSERT INTO public.asistente_manual_fichas (clave,tipo,pantalla_key,titulo,resumen,fuentes,revision) VALUES ('proceso_cierre_mes','proceso',NULL,'Cierre de mes','Recorre lo que se revisa al cerrar el mes: conciliación bancaria, cuentas por cobrar y por pagar, cierre de la nómina, presupuesto y Estado de Resultados.','["src/pages_fin.jsx#Tesoreria","src/pages_fin.jsx#CxC","src/pages_fin.jsx#CxP","src/pages_ops.jsx#Nomina","src/pages_fin.jsx#Presupuestos","src/pages_fin.jsx#Resultados"]'::jsonb,'b0397fbc8c 06993c9c6e d66ee1335d 21d2972451 0f8e7923fc 07b83d2f9d')
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('proceso_cierre_mes',1,'tesoreria',NULL,NULL,'Carga el extracto del banco con Importar extracto y concilia en Match Bancario cada movimiento del sistema con el del banco, hasta no dejar partidas sin conciliar.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('proceso_cierre_mes',2,'cxc',NULL,NULL,'Revisa las cuentas por cobrar con su saldo y vencimiento, registra los cobros pendientes con Cobrar y deja el seguimiento de lo vencido con Nueva gestión.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('proceso_cierre_mes',3,'cxp',NULL,NULL,'Revisa las cuentas por pagar y sus vencimientos para confirmar qué quedó pagado y qué pasa al mes siguiente.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('proceso_cierre_mes',4,'nomina',NULL,NULL,'Cierra el período de nómina con Confirmar cierre; el período debe estar procesado. Al cerrar se generan los egresos de la planilla.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('proceso_cierre_mes',5,'presupuestos',NULL,NULL,'En Presupuesto vs Real compara lo gastado con lo presupuestado. Un presupuesto se crea con Nuevo presupuesto y sus partidas, y se manda con Enviar a aprobación; los aprobadores usan Aprobar o Rechazar.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('proceso_cierre_mes',6,'resultados',NULL,NULL,'En Estado Resultados revisa el resultado del período, abre el detalle de una línea para ver sus gastos y descarga el reporte con PDF.');
INSERT INTO public.asistente_manual_fichas (clave,tipo,pantalla_key,titulo,resumen,fuentes,revision) VALUES ('proceso_configuracion_inicial','proceso',NULL,'Configuración inicial de la empresa','Recorre lo que se configura antes de empezar a operar: sociedades, series y cuentas, maestros base, catálogo de servicios, roles y usuarios.','["src/pages_admin.jsx#Parametros","src/pages_admin.jsx#Maestros","src/pages_admin.jsx#Servicios","src/pages_admin.jsx#Roles","src/pages_admin.jsx#Usuarios"]'::jsonb,'980cef576e 50855bc116 fb5e7f9dc7 0186d2d3a6 e59ec721a1')
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('proceso_configuracion_inicial',1,'parametros',NULL,NULL,'En Parametros Generales registra cada sociedad con Nueva sociedad, las series de los documentos, las cuentas bancarias y el tipo de cambio. Los feriados se agregan con Agregar feriado.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('proceso_configuracion_inicial',2,'maestros',NULL,NULL,'En Maestros Base carga los datos comunes: centros de costo (CECO), centros de beneficio (CEBE), materiales y sus familias. Para cargas grandes usa Descargar plantilla e Importar Excel.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('proceso_configuracion_inicial',3,'servicios',NULL,NULL,'En Catalogo Servicios crea lo que la empresa vende con Nuevo servicio o con Importar Excel. Un servicio que se cobra todos los meses se marca como Recurrente mensual.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('proceso_configuracion_inicial',4,'roles',NULL,NULL,'En Roles y Permisos crea cada rol con Nuevo rol o parte de uno existente con Clonar, y define qué puede hacer con Guardar permisos. Como ve la app este rol? muestra la aplicación tal como la verá ese rol.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('proceso_configuracion_inicial',5,'usuarios',NULL,NULL,'Crea a cada persona con Nuevo usuario y elige su posición en el organigrama, que debe tener un rol de sistema configurado. Si su acceso es solo a algunas sociedades, selecciona al menos una.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('proceso_configuracion_inicial',6,'usuarios',NULL,NULL,'Definir contrasena temporal asigna una clave provisional; la persona deberá cambiarla en su próximo inicio de sesión.');
INSERT INTO public.asistente_manual_fichas (clave,tipo,pantalla_key,titulo,resumen,fuentes,revision) VALUES ('proceso_cotizacion_cobro','proceso',NULL,'De la cotización aprobada al cobro','Sigue un servicio vendido desde la cotización aprobada hasta que el cobro queda conciliado en el banco: orden de servicio, órdenes de trabajo, valorización, factura y cobranza.','["src/pages_extra.jsx#Cotizaciones","src/pages_core.jsx#OSCliente","src/pages_fin.jsx#Facturacion","src/pages_fin.jsx#CxC","src/pages_fin.jsx#Tesoreria"]'::jsonb,'2e3ef06c5d 90315ca39a e697a23316 06993c9c6e b0397fbc8c')
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('proceso_cotizacion_cobro',1,'cotizaciones',NULL,NULL,'Con la cotización aprobada usa Crear OS Cliente: puedes Crear nueva OS o Agregar a OS existente. Las cotizaciones aprobadas que aún no tienen OS aparecen en el indicador Por convertir.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('proceso_cotizacion_cobro',2,'os_cliente',NULL,NULL,'En la OS Cliente crea el trabajo con Crear OT, o con Crear OF si es fabricación. Antes de crear órdenes de trabajo la OS debe tener CEBE asignado, y cada OT necesita un servicio y un centro de costo.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('proceso_cotizacion_cobro',3,'os_cliente',NULL,NULL,'Para un servicio recurrente elige el cobro mensual al crear la OS e indica la tarifa mensual sin IGV y la fecha de inicio. La primera OT la creas tú; después, cada mes de la vigencia se crea sola su OT el día 1, y los meses incompletos se valorizan prorrateados por días. El filtro Cobro mensual muestra solo estas órdenes.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('proceso_cotizacion_cobro',4,'os_cliente',NULL,NULL,'Registra lo que ya se puede facturar con Nueva valorización, dentro de la OS Cliente.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('proceso_cotizacion_cobro',5,'facturacion',NULL,NULL,'Emite el comprobante desde la valorización y luego usa Generar CxC para crear la cuenta por cobrar.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('proceso_cotizacion_cobro',6,'cxc',NULL,NULL,'Haz seguimiento de la cobranza con Nueva gestión. Cuando el cliente paga usa Cobrar: elige el medio de pago e ingresa el número de operación.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('proceso_cotizacion_cobro',7,'tesoreria',NULL,NULL,'En Match Bancario concilia el cobro con el movimiento del extracto del banco y confírmalo con Confirmar match.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('proceso_cotizacion_cobro',8,'os_cliente',NULL,NULL,'Al terminar el servicio usa Cerrar OS. Si el servicio se detiene puedes Pausar OS y retomarlo con Reactivar OS.');
INSERT INTO public.asistente_manual_fichas (clave,tipo,pantalla_key,titulo,resumen,fuentes,revision) VALUES ('proceso_fabricacion_of','proceso',NULL,'Fabricación con Orden de Fabricación (OF)','Sigue un trabajo de fabricación desde la orden de servicio del cliente hasta la OF lista para entrega: creación, ruta de tareas, materiales, aprobación, avance por partes y calidad.','["src/pages_core.jsx#OSCliente","operaciones-app/src/zahory-mock/pages/of/CrearOFPage.jsx#CrearOFPage","operaciones-app/src/zahory-mock/pages/of/DetalleOFPage.jsx#DetalleOFPage","operaciones-app/src/zahory-mock/pages/of/BandejaOFPage.jsx#BandejaOFPage"]'::jsonb,'90315ca39a 4ff52824a1 8875d0cc93 6f1d2aaebd')
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('proceso_fabricacion_of',1,'os_cliente',NULL,NULL,'Cuando el trabajo vendido es una fabricación, en la OS Cliente usa Crear OF en lugar de Crear OT.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('proceso_fabricacion_of',2,'of',NULL,NULL,'En Nueva OF, la orden parte de la OS del cliente y toma su Hoja de Costeo si la tiene. Crear OF la registra; si la OS ya tiene una, el botón dice Crear OF adicional.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('proceso_fabricacion_of',3,'of',NULL,NULL,'En el detalle de la OF arma la Ruta con Agregar tarea y la lista de Materiales con Agregar material. Lo que no estaba previsto se agrega como Material no planificado.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('proceso_fabricacion_of',4,'of',NULL,NULL,'Con la ruta y los materiales definidos usa Aprobar OF.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('proceso_fabricacion_of',5,'of',NULL,NULL,'La bandeja Órdenes de Fab. lista todas las OF; fíltralas por estado y usa Limpiar filtros para verlas todas. Nueva OF también se abre desde ahí.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('proceso_fabricacion_of',6,'of',NULL,NULL,'Qué decide si un trabajo va a OT o a OF: el tipo del Trabajo (mantenimiento o fabricación), que se marca en la Hoja de Costeo y viaja a la cotización y a la OS. Una OS de mantenimiento genera OT, una de fabricación genera OF y una mixta genera las dos.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('proceso_fabricacion_of',7,'of',NULL,NULL,'Solo se puede crear OF desde una OS de tipo fabricación o mixta. Cada OS admite una OF con copia de su hoja; una segunda se crea como OF adicional, vacía. Desde Administración, el botón Crear OF de la OS abre Operaciones, y la pestaña OF de la OS lista las que ya tiene.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('proceso_fabricacion_of',8,'of',NULL,NULL,'Con la OF aprobada, el avance se registra en su ficha con Registrar avance; el jefe de taller aprueba u observa cada parte en la pestaña Partes. El primer parte aprobado pasa la OF a En producción y cada aprobación actualiza el avance y el costo real.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('proceso_fabricacion_of',9,'of',NULL,NULL,'Terminada la producción, Enviar a calidad pasa la OF a En calidad; se mide en la pestaña Calidad y Liberar OF la deja Lista para entrega. La reserva de materiales en el almacén y la entrega de la OF aún no están disponibles.');
INSERT INTO public.asistente_manual_fichas (clave,tipo,pantalla_key,titulo,resumen,fuentes,revision) VALUES ('proceso_lead_cotizacion','proceso',NULL,'Del prospecto a la cotización aprobada','Sigue una venta desde que registras al prospecto hasta que el cliente aprueba la cotización: lead, oportunidad, costeo y cotización.','["src/pages_core.jsx#Leads","src/pages_core.jsx#Pipeline","src/pages_hoja_costeo_wizard.jsx#HojaCosteoWizard","src/pages_extra.jsx#Cotizaciones"]'::jsonb,'5cd977019c bcfa0a720d c181c07274 2e3ef06c5d')
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('proceso_lead_cotizacion',1,'leads',NULL,NULL,'Registra al prospecto con Nuevo lead. Puedes verlo en Lista o en Kanban y dejar cada contacto con Registrar Actividad.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('proceso_lead_cotizacion',2,'leads',NULL,NULL,'Cuando el prospecto califica usa Convertir, que crea su cuenta de cliente. Si no prospera usa Descartar; un lead descartado se puede volver a activar con Reactivar.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('proceso_lead_cotizacion',3,'pipeline',NULL,NULL,'Crea la oportunidad con Nueva oportunidad y síguela en Kanban o en Lista. Al cerrarla usa Ganar o Perder; al perderla la pantalla pide confirmar la pérdida.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('proceso_lead_cotizacion',4,'pipeline',NULL,NULL,'En la oportunidad, el vendedor fija su comisión con Proponer acuerdo. Si cambia el porcentaje base o agrega una bonificación, debe enviarlo con Enviar a aprobación: el Gerente Comercial lo aprueba o lo rechaza indicando el motivo, y el vendedor puede corregirlo y reenviarlo.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('proceso_lead_cotizacion',5,'pipeline',NULL,NULL,'Si el servicio necesita costeo, la Hoja de Costeo se crea desde la oportunidad. Para crearla debes tener elegida una sociedad concreta en el selector superior.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('proceso_lead_cotizacion',6,'hoja_costeo',NULL,NULL,'En la Hoja de Costeo agrega los trabajos y los materiales, y define el porcentaje de gasto administrativo y de margen; la suma de ambos debe ser menor a 100 %. Luego usa Enviar a revisión: la hoja solo se puede aprobar con Aprobar hoja después de enviarla.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('proceso_lead_cotizacion',7,'cotizaciones',NULL,NULL,'Crea la cotización con Nueva cotización: elige la cuenta, agrega las partidas y la condición de pago; puedes dividir el pago en hitos. Desde la oportunidad también puedes partir con Nueva Cotización.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('proceso_lead_cotizacion',8,'cotizaciones',NULL,NULL,'Envía la cotización al cliente con PDF o con Copiar enlace. Cuando el cliente acepta, regístralo con Confirmar aprobación indicando el canal de aprobación; puedes adjuntar el sustento.');
INSERT INTO public.asistente_manual_fichas (clave,tipo,pantalla_key,titulo,resumen,fuentes,revision) VALUES ('proceso_planilla','proceso',NULL,'Del ingreso de un trabajador al pago de planilla y su cese','Sigue a un trabajador desde la vacante y su alta, con contrato y jornada, hasta el proceso y cierre de la nómina y la liquidación por cese.','["src/pages_reclutamiento.jsx#Reclutamiento","src/pages_admin.jsx#RRHHAdmin","src/pages_ops.jsx#RRHH_Operativo","src/pages_ops.jsx#Nomina","src/pages_liquidaciones.jsx#LiquidacionesCese"]'::jsonb,'a1ede63e31 2883372074 8339f61f9c 21d2972451 8409cfda1b')
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('proceso_planilla',1,'reclutamiento',NULL,NULL,'Crea la vacante y comparte su Link publico para recibir postulaciones. Registra a los candidatos y sigue su avance en la vista Pipeline; Ver CV abre la hoja de vida.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('proceso_planilla',2,'rrhh_admin',NULL,NULL,'Da de alta al trabajador administrativo con Nuevo colaborador. Registra su contrato con Nuevo contrato; el contrato se puede enviar con Enviar a firma del trabajador y firmar con Firmar como empresa.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('proceso_planilla',3,'rrhh_admin',NULL,NULL,'Completa la ficha: Asignar jornada define su horario y Agregar cuenta registra sus datos bancarios. Los contratos se renuevan con Renovar.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('proceso_planilla',4,'rrhh_operativo',NULL,NULL,'El personal operativo se registra igual en Personal Operativo con Nuevo Colaborador; para muchos trabajadores usa Carga masiva.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('proceso_planilla',5,'nomina',NULL,NULL,'Crea el período con Nuevo período y calcula la planilla con Procesar. Si pagas por quincenas, debes procesar la primera quincena antes de la segunda.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('proceso_planilla',6,'nomina',NULL,NULL,'Registra lo extraordinario con Nuevo ingreso y Nuevo descuento. Boleta descarga la boleta en PDF de cada trabajador y Descargar Excel PLAME genera el archivo del período.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('proceso_planilla',7,'nomina',NULL,NULL,'Cierra el período con Confirmar cierre. El período debe estar procesado y, cuando corresponde gratificación, primero debes confirmar la gratificación real. Al cerrar se generan los egresos de la planilla.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('proceso_planilla',8,'liquidaciones_cese',NULL,NULL,'Cuando un trabajador cesa usa Nueva liquidación: elige al colaborador, el tipo de cese y la fecha de cese, que no puede ser anterior a su fecha de ingreso. Al confirmar se genera la cuenta por pagar y se bloquea su acceso al sistema.');
INSERT INTO public.asistente_manual_fichas (clave,tipo,pantalla_key,titulo,resumen,fuentes,revision) VALUES ('proceso_recepcion_entrega','proceso',NULL,'De la recepción del equipo a la entrega con conformidad','Sigue un trabajo de taller desde que ingresa el equipo del cliente hasta el acta de conformidad: recepción, diagnóstico, orden de trabajo, repuestos, partes diarios y cierre.','["operaciones-app/src/zahory-mock/pages/RecepcionActivosClientePage.jsx#RecepcionActivosClientePage","operaciones-app/src/zahory-mock/pages/DiagnosticoTecnicoPage.jsx#DiagnosticoTecnicoPage","operaciones-app/src/zahory-mock/pages/CrearOTPage.jsx#CrearOTPage","operaciones-app/src/zahory-mock/pages/pages2_v2.jsx#OTsListadoPage","operaciones-app/src/zahory-mock/pages/ReservaRepuestosPage.jsx#ReservaRepuestosPage","operaciones-app/src/zahory-mock/pages/pages3.jsx#ParteTallerPage","operaciones-app/src/zahory-mock/pages/CierreConformidadPage.jsx#CierreConformidadPage"]'::jsonb,'4923fe7cdf e945eecb6f cb7f933511 b22cbde9d1 3d08475098 a7974170a2 b188e26ea6')
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('proceso_recepcion_entrega',1,'recepcion_activos_cliente',NULL,NULL,'Registra el ingreso del equipo con Nueva recepción: elige el cliente propietario, el activo (o Registrar como activo nuevo si aún no existe), el almacén de custodia y la fecha de ingreso. Puedes adjuntar fotos del estado en que llega.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('proceso_recepcion_entrega',2,'recepcion_activos_cliente',NULL,NULL,'Desde la recepción usa Abrir diagnóstico para empezar la evaluación técnica del equipo.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('proceso_recepcion_entrega',3,'diagnostico_tecnico',NULL,NULL,'En el Diagnóstico Técnico indica si el trabajo es de Mantenimiento o de Fabricación, registra lo encontrado con Agregar hallazgo y arma los trabajos con sus actividades; cada trabajo necesita al menos una actividad. Emitir diagnóstico lo cierra, e Informe al cliente prepara el informe.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('proceso_recepcion_entrega',4,'diagnostico_tecnico',NULL,NULL,'Con el diagnóstico listo usa Generar hoja de costeo para costear el trabajo. La cotización y la aprobación del cliente siguen el proceso Del prospecto a la cotización aprobada.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('proceso_recepcion_entrega',5,'ot',NULL,NULL,'Con el trabajo aprobado crea la orden de trabajo con Nueva OT: el asistente pide el contexto, el lugar, el cargo financiero, el técnico responsable y el centro de costo.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('proceso_recepcion_entrega',6,'ot',NULL,NULL,'En la Bandeja de OTs usa Iniciar para pasar la OT programada a ejecución. La OT debe tener técnico responsable y centro de costo.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('proceso_recepcion_entrega',7,'inventario',NULL,NULL,'En Reserva de Repuestos, almacén entrega al taller los repuestos de la OT con Despachar.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('proceso_recepcion_entrega',8,'partes',NULL,NULL,'Cada día el técnico registra su parte de taller con las actividades y sus tiempos, y lo manda con Enviar a revisión. El supervisor aprueba los partes; sin partes aprobados la OT no se puede cerrar.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('proceso_recepcion_entrega',9,'ot',NULL,NULL,'En Cierre & Conformidad emite el acta: la OT debe tener técnico responsable, al menos un parte aprobado y ningún parte pendiente. El acta recorre resumen, fotos, conformidad, firma del técnico y firma del cliente, y su resultado puede ser conforme, con observaciones o pendiente de firma.');
INSERT INTO public.asistente_manual_fichas (clave,tipo,pantalla_key,titulo,resumen,fuentes,revision) VALUES ('proceso_solpe_pago','proceso',NULL,'De la SOLPE al pago conciliado','Sigue una compra desde la solicitud interna hasta su pago y conciliación bancaria.','["src/pages_ops.jsx#SOLPE","src/pages_ops.jsx#BandejaSourcing","src/pages_ops.jsx#OrdenesCompra","src/pages_ops.jsx#Recepciones","src/pages_fin.jsx#CxP","src/pages_fin.jsx#Tesoreria"]'::jsonb,'e43d59cb5b 59f4c3339c 0fbfbec78b 4edd4b32ac d66ee1335d b0397fbc8c')
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('proceso_solpe_pago',1,'solpe',NULL,NULL,'Crea la SOLPE con Nueva SOLPE, agrega los ítems y envíala. Quien la atiende puede generar la orden de compra desde la propia SOLPE.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('proceso_solpe_pago',2,'ordenes_compra',NULL,NULL,'Si los materiales se compran a varios proveedores, usa la Bandeja de Sourcing para asignar un proveedor por línea y generar una orden de compra por proveedor.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('proceso_solpe_pago',3,'ordenes_compra',NULL,NULL,'Revisa la orden de compra, sus datos y su estado de atención.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('proceso_solpe_pago',4,'recepciones',NULL,NULL,'Registra la recepción de lo comprado con Nueva recepción y confirma las cantidades. La factura del proveedor puede completarse después con Completar.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('proceso_solpe_pago',5,'cxp',NULL,NULL,'Revisa la cuenta por pagar generada para la compra y su vencimiento antes de programar el pago.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('proceso_solpe_pago',6,'tesoreria',NULL,NULL,'Registra el pago y concílialo con el movimiento del extracto bancario en Match Bancario.');
INSERT INTO public.asistente_manual_fichas (clave,tipo,pantalla_key,titulo,resumen,fuentes,revision) VALUES ('proceso_viaje_transporte','proceso',NULL,'Transporte: de la orden de viaje al despacho','Sigue un viaje de transporte: orden de viaje, programación en la Hoja de Ruta, asignación de unidad y conductor, despacho y seguimiento.','["operaciones-app/src/zahory-mock/pages/transporte/OrdenViajePage.jsx#OrdenViajePage","operaciones-app/src/zahory-mock/pages/transporte/HojaDeRutaPage.jsx#HojaDeRutaPage","operaciones-app/src/zahory-mock/pages/transporte/ViajeDetallePage.jsx#ViajeDetallePage","operaciones-app/src/zahory-mock/pages/transporte/MonitorViajesPage.jsx#MonitorViajesPage"]'::jsonb,'aa6bbffce0 fb0b722c0a 42c87dc48a 89fb9d5ef7')
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('proceso_viaje_transporte',1,'transporte_comercial',NULL,NULL,'Registra el viaje con Nueva orden de viaje. Puedes partir Desde OS del cliente o como Viaje directo. Guardar borrador lo conserva sin programar y Guardar y programar lo deja programado.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('proceso_viaje_transporte',2,'transporte_comercial',NULL,NULL,'En la Hoja de Ruta arma las rutas del día: crea una ruta, agrega los pedidos y asígnala. Imprimir hojas del día genera las hojas para los conductores.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('proceso_viaje_transporte',3,'transporte_comercial',NULL,NULL,'En el detalle del viaje usa Asignar y despachar para definir la unidad y el conductor y dar la salida. Reprogramar cambia la fecha y Cambiar asignación reemplaza la unidad o el conductor.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('proceso_viaje_transporte',4,'transporte_comercial',NULL,NULL,'El Monitor de Viajes agrupa los viajes por estado y marca los atrasados y los que salen hoy sin unidad asignada, para atenderlos primero.');
INSERT INTO public.asistente_manual_fichas (clave,tipo,pantalla_key,titulo,resumen,fuentes,revision) VALUES ('proveedores','pantalla','proveedores','Proveedores','Mantiene la ficha de cada proveedor: datos, contactos, cuentas bancarias, documentos, evaluaciones y familias de materiales que atiende.','["src/pages_ops.jsx#Proveedores"]'::jsonb,'72e8365316')
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('proveedores',1,'proveedores',NULL,NULL,'Usa Nuevo proveedor para registrarlo. El RUC peruano debe tener 11 dígitos y empezar con 1 o 2, y el teléfono 9 dígitos empezando con 9.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('proveedores',2,'proveedores',NULL,NULL,'En Ver ficha agrega contactos, documentos y cuentas bancarias (banco y número de cuenta o CCI). La cuenta del Banco de la Nación para detracciones debe estar en soles; al registrar una nueva, la anterior se inactiva.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('proveedores',3,'proveedores',NULL,NULL,'Nueva evaluacion registra la calificación del proveedor; su estado (por ejemplo homologado u observado) define si aparece al crear órdenes de compra.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('proveedores',4,'proveedores',NULL,NULL,'Emparejar Proveedores y Familias asigna qué familias de materiales atiende cada proveedor; la Bandeja de Sourcing usa esa relación para sugerir proveedores.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('proveedores',5,'proveedores',NULL,NULL,'Desde la ficha puedes iniciar Nueva OC o Solicitar cotizacion. Importar Excel carga muchos proveedores con la plantilla, y Descargar reporte exporta la lista.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('proveedores',6,'proveedores',NULL,NULL,'Editar proveedor corrige sus datos con Guardar cambios. Eliminar proveedor lo borra y pide confirmación. Antes de importar con Excel usa Descargar plantilla.');
INSERT INTO public.asistente_manual_fichas (clave,tipo,pantalla_key,titulo,resumen,fuentes,revision) VALUES ('proyectos_tarifas','pantalla','contratos_alquiler','Proyectos & Tarifas','Proyectos y sus tarifas de equipo y de mano de obra.','["operaciones-app/src/zahory-mock/pages/ProyectosTarifasPage.jsx#ProyectosTarifasPage"]'::jsonb,'21ba55ea69')
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('proyectos_tarifas',1,'contratos_alquiler',NULL,NULL,'Nuevo Proyecto crea un proyecto y Editar cambia sus datos; solo aparecen si tu rol puede editar.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('proyectos_tarifas',2,'contratos_alquiler',NULL,NULL,'Nueva tarifa registra una tarifa de equipo o de mano de obra con Guardar tarifa.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('proyectos_tarifas',3,'contratos_alquiler',NULL,NULL,'Eliminar borra un registro y pide confirmación.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('proyectos_tarifas',4,'contratos_alquiler',NULL,NULL,'Contratos Rental lleva a los contratos de alquiler.');
INSERT INTO public.asistente_manual_fichas (clave,tipo,pantalla_key,titulo,resumen,fuentes,revision) VALUES ('recepcion_activos','pantalla','recepcion_activos_cliente','Recepción de Activos','Ingreso al taller de los equipos del cliente, con su custodia y su diagnóstico.','["operaciones-app/src/zahory-mock/pages/RecepcionActivosClientePage.jsx#RecepcionActivosClientePage"]'::jsonb,'4923fe7cdf')
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('recepcion_activos',1,'recepcion_activos_cliente',NULL,NULL,'Registra el ingreso con Nueva recepción: elige el cliente propietario, el tipo de activo, el activo, el almacén de custodia y la fecha de ingreso, que es obligatoria.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('recepcion_activos',2,'recepcion_activos_cliente',NULL,NULL,'Si el equipo aún no existe usa Registrar como activo nuevo; para una maquinaria completa la marca y el modelo son obligatorios. El activo se crea al registrar la recepción.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('recepcion_activos',3,'recepcion_activos_cliente',NULL,NULL,'Puedes adjuntar fotos; si alguna falla, la recepción se registra igual y la pantalla indica cuáles no se cargaron.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('recepcion_activos',4,'recepcion_activos_cliente',NULL,NULL,'Abrir diagnóstico inicia la evaluación técnica del equipo y Ver informe PDF descarga el informe.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('recepcion_activos',5,'recepcion_activos_cliente',NULL,NULL,'Si tu rol o la sociedad activa no lo permiten, la pantalla avisa que no puedes registrar ni editar recepciones.');
INSERT INTO public.asistente_manual_fichas (clave,tipo,pantalla_key,titulo,resumen,fuentes,revision) VALUES ('recepcion_oc_almacen','pantalla','recepciones','Recepciones (Operaciones)','Ingreso al almacén de lo comprado con una orden de compra.','["operaciones-app/src/zahory-mock/pages/RecepcionOCPage.jsx#RecepcionOCPage"]'::jsonb,'84d78fcc4a')
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('recepcion_oc_almacen',1,'recepciones',NULL,NULL,'Elige la orden de compra que llegó e indica lo recibido.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('recepcion_oc_almacen',2,'recepciones',NULL,NULL,'Registrar recepción ingresa el material al almacén y genera sus movimientos en el kardex.');
INSERT INTO public.asistente_manual_fichas (clave,tipo,pantalla_key,titulo,resumen,fuentes,revision) VALUES ('recepciones','pantalla','recepciones','Recepciones','Registra la llegada de la mercadería de una orden de compra, completa la factura del proveedor para generar la cuenta por pagar y gestiona devoluciones.','["src/pages_ops.jsx#Recepciones"]'::jsonb,'4edd4b32ac')
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('recepciones',1,'recepciones',NULL,NULL,'Usa Nueva recepcion para registrar lo que llegó de una OC: indica las cantidades recibidas por línea y confirma con Confirmar recepcion. La recepción actualiza el stock.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('recepciones',2,'recepciones',NULL,NULL,'La recepción física y la factura van por separado. Si la factura llegó después, usa Completar factura y generar CxP e ingresa el número de factura del proveedor; con eso se crea la cuenta por pagar.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('recepciones',3,'recepciones',NULL,NULL,'Si el precio o el monto de la factura se aleja de la OC más que la tolerancia de compras de la empresa (5 % por defecto), la pantalla lo advierte; corrige el monto o usa Confirmar igualmente si la diferencia es correcta.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('recepciones',4,'recepciones',NULL,NULL,'Para devolver mercadería usa Iniciar devolución a proveedor en una recepción confirmada, total o parcial. La devolución se crea en borrador, se envía al proveedor y se marca aceptada; luego puedes registrar la nota de crédito del proveedor.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('recepciones',5,'recepciones',NULL,NULL,'Anular una recepción revierte el stock que ingresó; confirma la anulación solo si la mercadería no llegó realmente.');
INSERT INTO public.asistente_manual_fichas (clave,tipo,pantalla_key,titulo,resumen,fuentes,revision) VALUES ('recetas_actividad','pantalla','maestros','Recetas de actividad','Definición de las tareas que componen cada actividad, base del diagnóstico y del costeo.','["src/pages_recetas_actividad.jsx#RecetasActividad"]'::jsonb,'9ef699c848')
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('recetas_actividad',1,'maestros',NULL,NULL,'Elige una actividad y arma su receta con las tareas que la componen. Crear tarea agrega una tarea nueva.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('recetas_actividad',2,'maestros',NULL,NULL,'Subir tarea y Bajar tarea cambian el orden; Quitar tarea la retira de la receta.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('recetas_actividad',3,'maestros',NULL,NULL,'Guardar receta conserva los cambios. Si cambias de actividad con cambios sin guardar, la pantalla pregunta si quieres descartarlos.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('recetas_actividad',4,'maestros',NULL,NULL,'Ver variables de costeo abre los valores que usa el costeo y Maestros regresa a Maestros Base.');
INSERT INTO public.asistente_manual_fichas (clave,tipo,pantalla_key,titulo,resumen,fuentes,revision) VALUES ('reclutamiento','pantalla','reclutamiento','Reclutamiento','Vacantes, candidatos y su avance hasta la contratación.','["src/pages_reclutamiento.jsx#Reclutamiento"]'::jsonb,'a1ede63e31')
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('reclutamiento',1,'reclutamiento',NULL,NULL,'Crea una vacante con Crear vacante y comparte su Link publico para recibir postulaciones; Copiar lo copia.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('reclutamiento',2,'reclutamiento',NULL,NULL,'Registra a un candidato con Registrar. La vista Pipeline muestra en qué etapa está cada uno y Ver CV abre su hoja de vida.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('reclutamiento',3,'reclutamiento',NULL,NULL,'Invitar a esta vacante suma a la vacante a un candidato que ya está en el banco.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('reclutamiento',4,'reclutamiento',NULL,NULL,'Al contratar, la pantalla pregunta si el alta se crea como personal administrativo u operativo.');
INSERT INTO public.asistente_manual_fichas (clave,tipo,pantalla_key,titulo,resumen,fuentes,revision) VALUES ('cs_renovaciones','pantalla','cs_renovaciones','Renovaciones','Renovaciones de contratos de clientes y las oportunidades que generan.','["src/pages_cs.jsx#CSRenovaciones"]'::jsonb,'4ce1c80053')
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('cs_renovaciones',1,'cs_renovaciones',NULL,NULL,'Registra una renovación próxima con Nueva renovación.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('cs_renovaciones',2,'cs_renovaciones',NULL,NULL,'Generar oportunidad crea en el Pipeline la oportunidad de esa renovación.');
INSERT INTO public.asistente_manual_fichas (clave,tipo,pantalla_key,titulo,resumen,fuentes,revision) VALUES ('reportes_mina','pantalla','partes','Reportes Mina','Reportes de trabajo en mina: registro, hallazgos, revisión y aprobación.','["operaciones-app/src/zahory-mock/pages/ReportesMinaPage.jsx#ReportesMinaPage"]'::jsonb,'58d1cb1a20')
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('reportes_mina',1,'partes',NULL,NULL,'Nuevo reporte abre el registro; Guardar borrador lo conserva y Continuar borrador lo retoma.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('reportes_mina',2,'partes',NULL,NULL,'Agregar hallazgo registra lo encontrado, que puede marcarse como Urgente; Agregar al backlog lo deja como requerimiento pendiente.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('reportes_mina',3,'partes',NULL,NULL,'Enviar a revisión manda el reporte a su revisor.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('reportes_mina',4,'partes',NULL,NULL,'Quien revisa usa Aprobar reporte u Observar; un reporte observado vuelve al técnico, que lo corrige con Corregir y reenviar.');
INSERT INTO public.asistente_manual_fichas (clave,tipo,pantalla_key,titulo,resumen,fuentes,revision) VALUES ('reserva_repuestos','pantalla','inventario','Reserva de repuestos','Muestra los repuestos reservados para cada OT y permite despacharlos, liberarlos, revertir un despacho o trasladar la reserva.','["operaciones-app/src/zahory-mock/pages/ReservaRepuestosPage.jsx#ReservaRepuestosPage"]'::jsonb,'3d08475098')
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('reserva_repuestos',1,'inventario',NULL,NULL,'Elige una OT de la lista para ver sus repuestos reservados, despachados y pendientes.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('reserva_repuestos',2,'inventario','inventario','despachar','Despachar entrega la cantidad reservada al taller y actualiza el kardex. Revertir devuelve un despacho a la reserva de la OT, solo si la OT está programada o en ejecución.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('reserva_repuestos',3,'inventario','inventario','liberar','Liberar devuelve la cantidad reservada al stock disponible, con motivo.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('reserva_repuestos',4,'inventario','inventario','despachar','Si la reserva está en otro almacén, Trasladar la mueve al almacén de la OT.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('reserva_repuestos',5,'inventario',NULL,NULL,'Ver Kardex abre los movimientos del material y Volver a OT regresa a la orden de trabajo.');
INSERT INTO public.asistente_manual_fichas (clave,tipo,pantalla_key,titulo,resumen,fuentes,revision) VALUES ('roles','pantalla','roles','Roles y Permisos','Definición de roles y de lo que cada uno puede ver y hacer: aquí se da o se quita a alguien el acceso a una pantalla.','["src/pages_admin.jsx#Roles"]'::jsonb,'0186d2d3a6')
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('roles',1,'roles',NULL,NULL,'Crea un rol con Nuevo rol, o parte de uno existente con Clonar rol.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('roles',2,'roles',NULL,NULL,'Marca lo que el rol puede ver y hacer en cada pantalla y usa Guardar permisos.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('roles',3,'roles',NULL,NULL,'Como ve la app este rol? muestra la aplicación tal como la verá alguien con ese rol.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('roles',4,'roles',NULL,NULL,'Antes de eliminar un rol, Reasignar pasa sus usuarios a otro rol. Eliminar rol no se puede deshacer.');
INSERT INTO public.asistente_manual_fichas (clave,tipo,pantalla_key,titulo,resumen,fuentes,revision) VALUES ('salud_implementacion_tenant','pantalla','parametros','Salud Implementacion','Estado de la implementación del sistema en la empresa.','["src/pages_salud_tenant.jsx#SaludImplementacionTenant"]'::jsonb,'2f5fe0eb24')
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('salud_implementacion_tenant',1,'parametros',NULL,NULL,'Es una pantalla de consulta sobre el avance de la implementación de la empresa activa.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('salud_implementacion_tenant',2,'parametros',NULL,NULL,'Solo entra el Administrador de Empresa o el personal de TIDEO; a los demás les muestra acceso denegado.');
INSERT INTO public.asistente_manual_fichas (clave,tipo,pantalla_key,titulo,resumen,fuentes,revision) VALUES ('salud_implementacion','pantalla','tenants','Salud de implementación (plataforma)','Estado de la implementación de las empresas, visto por el personal de la plataforma.','["src/pages_plataforma.jsx#SaludImplementacion"]'::jsonb,'cf7ef1176b')
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('salud_implementacion',1,'tenants',NULL,NULL,'Es una pantalla de consulta para el personal de la plataforma.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('salud_implementacion',2,'tenants',NULL,NULL,'Muestra el avance de la implementación de las empresas; no registra información.');
INSERT INTO public.asistente_manual_fichas (clave,tipo,pantalla_key,titulo,resumen,fuentes,revision) VALUES ('solicitudes_rrhh','pantalla','solicitudes_rrhh','Solicitudes','Solicitudes de vacaciones, descansos y permisos del personal, y su aprobación.','["src/pages_ops.jsx#SolicitudesRrhh"]'::jsonb,'fe86ec31ab')
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('solicitudes_rrhh',1,'solicitudes_rrhh',NULL,NULL,'Pide vacaciones o un permiso con Nueva solicitud. Si no alcanza el saldo de vacaciones, la pantalla lo avisa con los días disponibles.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('solicitudes_rrhh',2,'solicitudes_rrhh',NULL,NULL,'Quien aprueba usa Aprobar o Rechazar; el motivo es obligatorio al rechazar. Anular deja sin efecto una solicitud.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('solicitudes_rrhh',3,'solicitudes_rrhh',NULL,NULL,'Aplicar a asistencia crea los registros de asistencia de la solicitud aprobada; si ya existen registros en esas fechas, pide confirmar antes de reemplazarlos.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('solicitudes_rrhh',4,'solicitudes_rrhh',NULL,NULL,'PDF descarga la solicitud e Historial muestra las anteriores.');
INSERT INTO public.asistente_manual_fichas (clave,tipo,pantalla_key,titulo,resumen,fuentes,revision) VALUES ('solpe','pantalla','solpe','SOLPE Interna','Aquí pido un material o un servicio que necesito (cómo pedir un material): registra el pedido interno, lo envía a aprobación y lo deriva a Compras para generar la orden de compra.','["src/pages_ops.jsx#SOLPE"]'::jsonb,'e43d59cb5b')
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('solpe',1,'solpe',NULL,NULL,'Usa Nueva SOLPE para crear un pedido. Completa el tipo, el área solicitante, la urgencia, el centro de costo (CECO), la descripción de la necesidad y, si aplica, la OT asociada.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('solpe',2,'solpe',NULL,NULL,'En Ítems solicitados agrega cada material con su cantidad y unidad. En pedidos de tipo bien es obligatorio al menos un ítem con material y cantidad; sin CECO la SOLPE no se guarda.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('solpe',3,'solpe',NULL,NULL,'La SOLPE nace en borrador. Usa Enviar (o Enviar solicitud en su detalle) para pasarla a solicitada y dejarla pendiente de atención.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('solpe',4,'solpe',NULL,NULL,'Quien la revisa usa Atender o Atender SOLPE: la SOLPE queda aprobada y disponible para Compras.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('solpe',5,'solpe',NULL,NULL,'Con la SOLPE aprobada, Generar OC abre la Bandeja de Sourcing, donde se elige el proveedor por línea y se genera la orden de compra. La columna Etapa de compras indica si la SOLPE aún no está en sourcing, si espera OC o si ya tiene OC.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('solpe',6,'solpe',NULL,NULL,'Filtra la lista por estado, fechas, solicitante o texto. Haz clic en una SOLPE para ver su detalle, sus ítems con cantidad pedida y recibida, y la OC vinculada.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('solpe',7,'solpe',NULL,NULL,'Cómo apruebo una SOLPE y la paso a orden de compra: abre la SOLPE solicitada, usa Atender SOLPE para aprobarla y luego Generar OC, que la lleva a la Bandeja de Sourcing para elegir proveedor y crear la orden de compra. Si no ves Atender, tu rol no tiene permiso para aprobar SOLPE.');
INSERT INTO public.asistente_manual_fichas (clave,tipo,pantalla_key,titulo,resumen,fuentes,revision) VALUES ('tickets','pantalla','tickets','Soporte y Tickets','Registro y seguimiento de tickets de soporte hasta su resolución.','["src/pages_ops.jsx#Tickets"]'::jsonb,'9edc6256b1')
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('tickets',1,'tickets',NULL,NULL,'Crea un ticket con Nuevo Ticket; el título es obligatorio. Puedes verlos en Kanban o en Lista y acotar con Filtros.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('tickets',2,'tickets',NULL,NULL,'Dentro del ticket agrega comentarios al hilo y usa Adjuntar imagen para sumar evidencia.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('tickets',3,'tickets',NULL,NULL,'Un ticket no se puede resolver hasta aprobar su control de calidad.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('tickets',4,'tickets',NULL,NULL,'Reabrir ticket lo vuelve a abrir; debes escribir el motivo de la reapertura.');
INSERT INTO public.asistente_manual_fichas (clave,tipo,pantalla_key,titulo,resumen,fuentes,revision) VALUES ('stock_minimos','pantalla','inventario','Stock mínimos & reposición','Stock mínimo, punto de reorden y máximo por material y almacén; materiales por reponer y generación de la SOLPE de reposición.','["operaciones-app/src/zahory-mock/pages/wms/StockMinimosPage.jsx#StockMinimosPage"]'::jsonb,'126af95fbf')
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('stock_minimos',1,'inventario',NULL,NULL,'La lista muestra los materiales por debajo de su mínimo. Editar cambia los parámetros de reposición de un material.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('stock_minimos',2,'inventario',NULL,NULL,'Seleccionar sugeridos marca lo que conviene reponer.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('stock_minimos',3,'inventario',NULL,NULL,'Generar SOLPE crea la solicitud de compra con los materiales elegidos; Compras la ve en su bandeja.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('stock_minimos',4,'inventario',NULL,NULL,'Cada material tiene, por almacén, stock mínimo, punto de reorden, stock máximo y stock de seguridad. Se definen con Editar y Guardar parámetros. El punto de reorden debe ser igual o mayor al mínimo, y ninguno puede superar al máximo.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('stock_minimos',5,'inventario',NULL,NULL,'Estados: Quiebre (disponible en cero), Bajo mínimo (por debajo del mínimo), Reordenar (en el punto de reorden o por debajo), OK, y Sin parámetro (aún no se configuró). El filtro Alertas muestra los tres primeros; «Sin parámetro» lista lo que falta configurar.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('stock_minimos',6,'inventario',NULL,NULL,'La cantidad sugerida repone hasta el stock máximo; si no hay máximo, hasta el doble del punto de reorden. Cobertura indica para cuántos meses alcanza el disponible según el consumo mensual.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('stock_minimos',7,'inventario',NULL,NULL,'Generar SOLPE pide centro de costo y descripción y crea una sola SOLPE con los materiales marcados; sigue el circuito normal de compras. Seleccionar sugeridos marca todos los que tienen cantidad sugerida.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('stock_minimos',8,'inventario',NULL,NULL,'En almacenes de uso mixto, «Protegido para operaciones» es la cantidad que los pedidos de venta no pueden reservar, para no dejar sin repuestos al taller.');
INSERT INTO public.asistente_manual_fichas (clave,tipo,pantalla_key,titulo,resumen,fuentes,revision) VALUES ('tareo_admin','pantalla','tareo_admin','Tareo Administrativo','Registro diario de las horas del personal administrativo.','["src/pages_ops.jsx#TareoAdmin"]'::jsonb,'d77baa9ebb')
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('tareo_admin',1,'tareo_admin',NULL,NULL,'Muestra por persona las horas estimadas, las ejecutadas en OT y las horas libres, con su costo calculado.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('tareo_admin',2,'tareo_admin',NULL,NULL,'Registrar horas manuales agrega una entrada con su descripción, por ejemplo una reunión o gestión interna.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('tareo_admin',3,'tareo_admin',NULL,NULL,'Las horas que vienen de una OT son de solo lectura aquí: se gestionan desde la OT.');
INSERT INTO public.asistente_manual_fichas (clave,tipo,pantalla_key,titulo,resumen,fuentes,revision) VALUES ('tarifas_transporte','pantalla','transporte_comercial','Tarifas Transporte','Tarifas del servicio de transporte.','["operaciones-app/src/zahory-mock/pages/transporte/TarifasTransportePage.jsx#TarifasTransportePage"]'::jsonb,'4231d5fd58')
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('tarifas_transporte',1,'transporte_comercial',NULL,NULL,'Nueva tarifa registra una tarifa; una tarifa también se puede anular.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('tarifas_transporte',2,'transporte_comercial',NULL,NULL,'Resolver tarifa consulta qué tarifa aplica a un caso concreto.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('tarifas_transporte',3,'transporte_comercial',NULL,NULL,'Para qué sirve: la tarifa dice cuánto se cobra por un viaje en una ruta, según el tipo de unidad, la modalidad y la moneda. Hay dos niveles: la tarifa base de la ruta y la tarifa acordada con un cliente. Al crear un viaje se usa primero la del cliente y, si no tiene, la base.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('tarifas_transporte',4,'transporte_comercial',NULL,NULL,'Cada tarifa tiene un periodo de vigencia y dos tarifas iguales no pueden estar vigentes a la vez. Si la que estás guardando se cruza con otra, la pantalla lo avisa y ofrece Editar esa tarifa para cerrar la anterior.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('tarifas_transporte',5,'transporte_comercial',NULL,NULL,'El simulador ¿Cuánto cobro? responde qué tarifa se aplicaría a un caso concreto antes de crear el viaje.');
INSERT INTO public.asistente_manual_fichas (clave,tipo,pantalla_key,titulo,resumen,fuentes,revision) VALUES ('tesoreria','pantalla','tesoreria','Tesorería y match bancario','Consulta saldos y flujo de caja, concilia movimientos con el extracto del banco y registra movimientos manuales y transferencias entre cuentas propias.','["src/pages_fin.jsx#Tesoreria","src/services/tesoreriaService.js"]'::jsonb,'b0397fbc8c 5f79da0382')
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('tesoreria',1,'tesoreria',NULL,NULL,'En la pestaña Flujo de caja revisa las cuentas bancarias, sus saldos por moneda y la proyección a 90 días. Si se proyecta un saldo negativo, la pantalla muestra una alerta.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('tesoreria',2,'tesoreria',NULL,NULL,'En Extracto banco usa Importar extracto para cargar los movimientos del banco desde un archivo CSV. El historial de lotes permite revisar lo importado y borrar un lote cargado por error.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('tesoreria',3,'tesoreria',NULL,NULL,'En Match Bancario compara los movimientos del sistema con los del extracto. Selecciona ambos lados y usa Confirmar match; verifica cuenta, fecha e importe antes de confirmar. Un match se puede deshacer.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('tesoreria',4,'tesoreria',NULL,NULL,'Usa Movimiento manual para registrar un ingreso o egreso que no proviene de otro módulo, indicando cuenta, fecha, monto y referencia.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('tesoreria',5,'tesoreria','tesoreria','crear','Para mover dinero entre cuentas propias elige Movimiento manual y el tipo Transferencia entre cuentas. Indica cuenta de origen y de destino, fecha y monto; ambas deben estar activas, ser de la misma sociedad y no ser cuentas de detracciones. Si las monedas son distintas, ingresa el tipo de cambio en soles por unidad extranjera; la pantalla muestra el monto recibido y la diferencia referencial.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('tesoreria',6,'tesoreria',NULL,NULL,'Usa Agregar cuenta para registrar una cuenta bancaria con su sociedad y su saldo inicial.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('tesoreria',7,'tesoreria',NULL,NULL,'Editar cuenta cambia los datos de una cuenta bancaria. Editar saldo inicial corrige el saldo con el que empezó la cuenta; ingresa un saldo válido y usa Guardar saldo inicial.');
INSERT INTO public.asistente_manual_fichas (clave,tipo,pantalla_key,titulo,resumen,fuentes,revision) VALUES ('remision','pantalla','remision','Transporte y Guias','Órdenes de venta, guías de despacho, transportistas, vehículos y conductores.','["src/pages_ops.jsx#Remision"]'::jsonb,'11875105df')
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('remision',1,'remision',NULL,NULL,'Nueva OV crea una orden de venta; Confirmar OV reserva el stock.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('remision',2,'remision',NULL,NULL,'Nueva Guía o Crear guía de despacho prepara la guía y Emitir guía la emite.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('remision',3,'remision',NULL,NULL,'Marcar en tránsito indica que la carga salió y Confirmar entrega que llegó.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('remision',4,'remision',NULL,NULL,'Nuevo Transportista registra un transportista; dentro de él se agregan sus vehículos y conductores.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('remision',5,'remision',NULL,NULL,'Anular deja sin efecto un documento y pide Confirmar anulación. Abrir la Hoja de Ruta lleva a la programación de rutas en Operaciones.');
INSERT INTO public.asistente_manual_fichas (clave,tipo,pantalla_key,titulo,resumen,fuentes,revision) VALUES ('turnos','pantalla','turnos','Turnos y Horarios','Definición de los turnos de trabajo que se asignan al personal.','["src/pages_turnos.jsx#TurnosHorarios"]'::jsonb,'0f9bfb4e97')
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('turnos',1,'turnos',NULL,NULL,'Crea un horario con Nuevo turno. Copiar el primer día a todos repite el horario del primer día en el resto de la semana.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('turnos',2,'turnos',NULL,NULL,'Editar turno cambia sus horas.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('turnos',3,'turnos',NULL,NULL,'Un turno que ya usan trabajadores o que tiene asistencias en el historial no se puede eliminar: edítalo y cambia su estado a Inactivo.');
INSERT INTO public.asistente_manual_fichas (clave,tipo,pantalla_key,titulo,resumen,fuentes,revision) VALUES ('ubicaciones_almacen','pantalla','inventario','Ubicaciones','Ubicaciones físicas del almacén.','["operaciones-app/src/zahory-mock/pages/UbicacionesPage.jsx#UbicacionesPage"]'::jsonb,'1fc2efb872')
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('ubicaciones_almacen',1,'inventario',NULL,NULL,'Crea una ubicación con Nueva ubicación; nace sin stock.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('ubicaciones_almacen',2,'inventario',NULL,NULL,'Editar cambia sus datos. Desactivar la retira del uso y Reactivar la devuelve.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('ubicaciones_almacen',3,'inventario',NULL,NULL,'Mostrar inactivas incluye en la lista las ubicaciones desactivadas.');
INSERT INTO public.asistente_manual_fichas (clave,tipo,pantalla_key,titulo,resumen,fuentes,revision) VALUES ('usuarios','pantalla','usuarios','Usuarios','Alta de usuarios, su posición, sus sociedades y su contraseña.','["src/pages_admin.jsx#Usuarios"]'::jsonb,'e59ec721a1')
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('usuarios',1,'usuarios',NULL,NULL,'Crea a una persona con Nuevo usuario y elige su posición en el organigrama, que debe tener un rol de sistema configurado.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('usuarios',2,'usuarios',NULL,NULL,'Si su acceso es solo a algunas sociedades, selecciona al menos una. Agregar asignacion suma otra posición o sociedad.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('usuarios',3,'usuarios',NULL,NULL,'Definir contrasena temporal asigna una clave provisional; la persona deberá cambiarla en su próximo inicio de sesión.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('usuarios',4,'usuarios',NULL,NULL,'Desde el usuario puedes crear su ficha con Crear ficha en Personal Administrativo o Crear ficha en Personal Operativo.');
INSERT INTO public.asistente_manual_fichas (clave,tipo,pantalla_key,titulo,resumen,fuentes,revision) VALUES ('valorizacion','pantalla','valorizacion','Valorizaciones','Valorización de lo ejecutado en una orden de servicio, su aprobación y su paso a facturación.','["src/pages_extra.jsx#Valorizacion"]'::jsonb,'e710949e0a')
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('valorizacion',1,'valorizacion',NULL,NULL,'Inicia con Generar valorización: primero debes seleccionar una OS Cliente y luego avanzas con Siguiente.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('valorizacion',2,'valorizacion',NULL,NULL,'Agregar línea suma conceptos a la valorización y Guardar borrador la conserva sin aprobar.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('valorizacion',3,'valorizacion',NULL,NULL,'Aprobar valorización la deja lista; con ella aprobada, Facturar la lleva a facturación.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('valorizacion',4,'valorizacion',NULL,NULL,'Ver cierre y Ver conformidad muestran el cierre técnico y la conformidad del cliente que la sustentan.');
